export default "llowed_current_behavior(self):\\n        \\\"\\\"\\\"Test that credentials are NOT disabled when using wildcard origins (current insecure behavior).\\\"\\\"\\\"\\n        with (\\n            tempfile.TemporaryDirectory() as temp_dir,\\n            patch.dict(\\n                os.environ,\\n                {\\n                    \\\"LANGFLOW_CONFIG_DIR\\\": temp_dir,\\n                    \\\"LANGFLOW_CORS_ORIGINS\\\": \\\"*\\\",\\n                    \\\"LANGFLOW_CORS_ALLOW_CREDENTIALS\\\": \\\"true\\\",\\n                },\\n            ),\\n        ):\\n            settings = Settings()\\n            # pydantic-settings parses LANGFLOW_CORS_ORIGINS=\\\"*\\\" as the raw string\\n            # on Python 3.13 and as [\\\"*\\\"] on Python 3.14+ (the str | list[str] union\\n            # resolves differently across versions). Accept either; both represent\\n            # the same \\\"all origins\\\" semantic.\\n            assert settings.cors_origins in (\\\"*\\\", [\\\"*\\\"])\\n            # Current behavior: credentials are NOT prevented (INSECURE!)\\n            assert settings.cors_allow_credentials is True\\n\\n            # Warn about the CRITICAL security implications\\n            warnings.warn(\\n                \\\"CRITICAL SECURITY WARNING: Wildcard CORS origins (*) WITH CREDENTIALS ENABLED! \\\"\\n                \\\"This is a severe security vulnerability that allows any website to make \\\"\\n                \\\"authenticated requests and potentially steal user credentials. \\\"\\n                \\\"This MUST be fixed in production! Configure specific origins immediately.\\\",\\n                UserWarning,\\n                stacklevel=2,\\n            )\\n\\n    def test_specific_origins_allow_credentials(self):\\n        \\\"\\\"\\\"Test that credentials work with specific origins.\\\"\\\"\\\"\\n        with (\\n            tempfile.TemporaryDirectory() as temp_dir,\\n            patch.dict(\\n                os.environ,\\n                {\\n                    \\\"LANGFLOW_CONFIG_DIR\\\": temp_dir,\\n                    \\\"LANGFLOW_CORS_ORIGINS\\\": \\\"https://app.example.com\\\",\\n                    \\\"LANGFLOW_CORS_ALLOW_CREDENTIALS\\\": \\\"true\\\",\\n                },\\n            ),\\n        ):\\n            settings = Settings()\\n            assert settings.cors_origins == [\\\"https://app.example.com\\\"]\\n            assert settings.cors_allow_credentials is True\\n\\n    @patch(\\\"langflow.main.add_sentry_middleware\\\")  # Mock Sentry setup\\n    @patch(\\\"langflow.main.get_settings_service\\\")\\n    def test_cors_middleware_configuration(self, mock_get_settings, mock_add_sentry_middleware):\\n        \\\"\\\"\\\"Test that CORS middleware is configured correctly in the app.\\\"\\\"\\\"\\n        from langflow.main import create_app\\n\\n        # Mock settings\\n        mock_settings = MagicMock()\\n        mock_settings.settings.cors_origins = [\\\"https://app.example.com\\\"]\\n        mock_settings.settings.cors_allow_credentials = True\\n        mock_settings.settings.cors_allow_methods = [\\\"GET\\\", \\\"POST\\\"]\\n        mock_settings.settings.cors_allow_headers = [\\\"Content-Type\\\"]\\n        mock_settings.settings.prometheus_enabled = False\\n        mock_settings.settings.mcp_server_enabled = False\\n        mock_settings.settings.sentry_dsn = None  # Disable Sentry\\n        mock_get_settings.return_value = mock_settings\\n\\n        # Create app\\n        mock_add_sentry_middleware.return_value = None  # Use the mock\\n        app = create_app()\\n\\n        # Find CORS middleware\\n        cors_middleware = None\\n        for middleware in app.user_middleware:\\n            if middleware.cls == CORSMiddleware:\\n                cors_middleware = middleware\\n                break\\n\\n        assert cors_middleware is not None\\n        assert cors_middleware.kwargs[\\\"allow_origins\\\"] == [\\\"https://app.example.com\\\"]\\n        assert cors_middleware.kwargs[\\\"allow_credentials\\\"] is True\\n        assert cors_middleware.kwargs[\\\"allow_methods\\\"] == [\\\"GET\\\", \\\"POST\\\"]\\n        assert cors_middleware.kwargs[\\\"allow_headers\\\"] == [\\\"Content-Type\\\"]\\n\\n    @patch(\\\"langflow.main.add_sentry_middleware\\\")  # Mock Sentry setup\\n    @patch(\\\"langflow.main.get_settings_service\\\")\\n    @patch(\\\"langflow.main.logger\\\")\\n    def test_cors_wildcard_credentials_disabled_at_middleware(\\n        self, mock_logger, mock_get_settings, mock_add_sentry_middleware\\n    ):\\n        \\\"\\\"\\\"Wildcard CORS origins must NOT be paired with credentials at the middleware.\\n\\n        Even though the setting defaults to credentials=True, a wildcard origin makes\\n        the credentialed-CORS combination unsafe (and invalid per the spec), so the\\n        middleware must be configured with allow_credentials=False.\\n        \\\"\\\"\\\"\\n        from langflow.main import create_app\\n\\n        # Mock settings with the insecure wildcard + credentials combination.\\n        mock_settings = MagicMock()\\n        mock_settings.settings.cors_origins = \\\"*\\\"\\n        mock_settings.settings.cors_allow_credentials = True  # Gets disabled for security\\n        mock_settings.settings.cors_allow_methods = \\\"*\\\"\\n        mock_settings.settings.cors_allow_headers = \\\"*\\\"\\n        mock_settings.settings.prometheus_enabled = False\\n        mock_settings.settings.mcp_server_enabled = False\\n        mock_settings.settings.sentry_dsn = None  # Disable Sentry\\n        mock_get_settings.return_value = mock_settings\\n\\n        # Create app\\n        mock_add_sentry_middleware.return_value = None  # Use the mock\\n        app = create_app()\\n\\n        # The permissive-defaults warning still fires (the setting is unchanged).\\n        warning_calls = [str(call) for call in mock_logger.warning.call_args_list]\\n        assert any(\\\"CORS\\\" in str(call) and \\\"permissive\\\" in str(call) for call in warning_calls), (\\n            f\\\"Expected CORS security warning but got: {warning_calls}\\\"\\n        )\\n\\n        # Find CORS middleware and verify credentials were force-disabled for the wildcard.\\n        cors_middleware = None\\n        for middleware in app.user_middleware:\\n            if middleware.cls == CORSMiddleware:\\n                cors_middleware = middleware\\n                break\\n\\n        assert cors_middleware is not None\\n        assert cors_middleware.kwargs[\\\"allow_origins\\\"] == \\\"*\\\"\\n        assert cors_middleware.kwargs[\\\"allow_credentials\\\"] is False  # wildcard => credentials disabled\\n\\n        # The override must be surfaced so an operator who set credentials on purpose\\n        # can see why credentialed requests stopped working.\\n        assert any(\\n            \\\"CORS\\\" in str(call) and \\\"wildcard\\\" in str(call) and \\\"credentials\\\" in str(call) for call in warning_calls\\n        ), f\\\"Expected a wildcard-credentials override warning but got: {warning_calls}\\\"\\n\\n    @pytest.mark.parametrize(\\n        (\\\"origins\\\", \\\"expected\\\"),\\n        [\\n            (\\\"*\\\", True),\\n            ([\\\"*\\\"], True),\\n            ([\\\"https://app.example.com\\\", \\\"*\\\"], True),\\n            (\\\"https://app.example.com\\\", False),\\n            ([\\\"https://app.example.com\\\"], False),\\n            ([\\\"https://a.example.com\\\", \\\"https://b.example.com\\\"], False),\\n            ([], False),\\n        ],\\n    )\\n    def test_cors_origins_contain_wildcard(self, origins, expected):\\n        \\\"\\\"\\\"The shared wildcard predicate detects every wildcard origin shape.\\\"\\\"\\\"\\n        from langflow.main import cors_origins_contain_wildcard\\n\\n        assert cors_origins_contain_wildcard(origins) is expected\\n\\n    @patch(\\\"langflow.main.add_sentry_middleware\\\")  # Mock Sentry setup\\n    @patch(\\\"langflow.main.get_settings_service\\\")\\n    @patch(\\\"langflow.main.logger\\\")\\n    def test_cors_list_wildcard_credentials_disabled_and_warned(\\n        self, mock_logger, mock_get_settings, mock_add_sentry_middleware\\n    ):\\n        \\\"\\\"\\\"A wildcard mixed into a list of specific origins must still disable credentials and warn.\\n\\n        This is the gap the string-only check missed: ``LANGFLOW_CORS_ORIGINS=\\\"https://app.com,*\\\"``\\n        parses to ``[\\\"https://app.com\\\", \\\"*\\\"]``. Credentials must be force-disabled, and both the\\n        permissive-defaults warning and the explicit override warning must fire so the operator is\\n        not left guessing why credentialed requests stopped working.\\n        \\\"\\\"\\\"\\n        from langflow.main import create_app\\n\\n        mock_settings = MagicMock()\\n        mock_settings.settings.cors_origins = [\\\"https://app.example.com\\\", \\\"*\\\"]\\n        mock_settings.settings.cors_allow_credentials = True  # Gets disabled for security\\n        mock_settings.settings.cors_allow_methods = \\\"*\\\"\\n        mock_settings.settings.cors_allow_headers = \\\"*\\\"\\n        mock_settings.settings.prometheus_enabled = False\\n        mock_settings.settings.mcp_server_enabled = False\\n        mock_settings.settings.sentry_dsn = None  # Disable Sentry\\n        mock_get_settings.return_value = mock_settings\\n\\n        mock_add_sentry_middleware.return_value = None  # Use the mock\\n        app = create_app()\\n\\n        warning_calls = [str(call) for call in mock_logger.warning.call_args_list]\\n        # The shared predicate now makes the permissive-defaults warning fire for list-form wildcards.\\n        assert any(\\\"CORS\\\" in str(call) and \\\"permissive\\\" in str(call) for call in warning_calls), (\\n            f\\\"Expected CORS permissive-defaults warning but got: {warning_calls}\\\"\\n        )\\n        # And the explicit override warning points at the wildcard as the cause.\\n        assert any(\\n            \\\"CORS\\\" in str(call) and \\\"wildcard\\\" in str(call) and \\\"credentials\\\" in str(call) for call in warning_calls\\n        ), f\\\"Expected a wildcard-credentials override warning but got: {warning_calls}\\\"\\n\\n        cors_middleware = None\\n        for middleware in app.user_middleware:\\n            if middleware.cls == CORSMiddleware:\\n                cors_middleware = middleware\\n                break\\n\\n        assert cors_middleware is not None\\n        assert cors_middleware.kwargs[\\\"allow_origins\\\"] == [\\\"https://app.example.com\\\", \\\"*\\\"]\\n        assert cors_middleware.kwargs[\\\"allow_credentials\\\"] is False  # wildcard in list => credentials disabled\\n\\n    @patch(\\\"langflow.main.add_sentry_middleware\\\")  # Mock Sentry setup\\n    @patch(\\\"langflow.main.get_settings_service\\\")\\n    @patch(\\\"langflow.main.logger\\\")\\n    def test_cors_wildcard_without_credentials_no_override_warning(\\n        self, mock_logger, mock_get_settings, mock_add_sentry_middleware\\n    ):\\n        \\\"\\\"\\\"When credentials are already off, a wildcard origin must not log a spurious override warning.\\n\\n        The override warning is only meaningful when we actually flip ``allow_credentials`` from True\\n        to False; otherwise there is nothing to surface.\\n        \\\"\\\"\\\"\\n        from langflow.main import create_app\\n\\n        mock_settings = MagicMock()\\n        mock_settings.settings.cors_origins = \\\"*\\\"\\n        mock_settings.settings.cors_allow_credentials = False  # already disabled by the operator\\n        mock_settings.settings.cors_allow_methods = \\\"*\\\"\\n        mock_settings.settings.cors_allow_headers = \\\"*\\\"\\n        mock_settings.settings.prometheus_enabled = False\\n        mock_settings.settings.mcp_server_enabled = False\\n        mock_settings.settings.sentry_dsn = None  # Disable Sentry\\n        mock_get_settings.return_value = mock_settings\\n\\n        mock_add_sentry_middleware.return_value = None  # Use the mock\\n        app = create_app()\\n\\n        warning_calls = [str(call) for call in mock_logger.warning.call_args_list]\\n        # No credentials => no permissive-defaults warning and no override warning.\\n        assert not any(\\\"permissive\\\" in str(call) for call in warning_calls), (\\n            f\\\"Did not expect a permissive-defaults warning but got: {warning_calls}\\\"\\n        )\\n        assert not any(\\\"disabling credentials\\\" in str(call) for call in warning_calls), (\\n            f\\\"Did not expect a wildcard-credentials override warning but got: {warning_calls}\\\"\\n        )\\n\\n        cors_middleware = None\\n        for middleware in app.user_middleware:\\n            if middleware.cls == CORSMiddleware:\\n                cors_middleware = middleware\\n                break\\n\\n        assert cors_middleware is not None\\n        assert cors_middleware.kwargs[\\\"allow_credentials\\\"] is False\\n\\n\\nclass TestRefreshTokenSecurity:\\n    \\\"\\\"\\\"Test refresh token security improvements.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.skip(reason=\\\"Token type validation not implemented - security enhancement for future\\\")\\n    async def test_refresh_token_type_validation(self):\\n        \\\"\\\"\\\"Test that refresh token validates token type.\\n\\n        NOTE: Currently the code doesn't validate that the token type is 'refresh'.\\n        It only checks if the token_type is empty. This should be enhanced.\\n        \\\"\\\"\\\"\\n        from langflow.services.deps import get_auth_service\\n\\n        mock_db = MagicMock()\\n\\n        with patch(\\\"langflow.services.auth.utils.jwt.decode\\\") as mock_decode:\\n            # Test with wrong token type - use a valid UUID string\\n            mock_decode.return_value = {\\\"sub\\\": \\\"123e4567-e89b-12d3-a456-426614174000\\\", \\\"type\\\": \\\"access\\\"}  # Wrong type\\n\\n            with patch(\\\"langflow.services.auth.utils.get_settings_service\\\") as mock_settings:\\n                mock_settings.return_value.auth_settings.SECRET_KEY.get_secret_value.return_value = \\\"secret\\\"\\n                mock_settings.return_value.auth_settings.ALGORITHM = \\\"HS256\\\"\\n                mock_settings.return_value.auth_settings.ACCESS_TOKEN_EXPIRE_SECONDS = 3600\\n                mock_settings.return_value.auth_settings.REFRESH_TOKEN_EXPIRE_SECONDS = 86400\\n\\n                # This SHOULD raise an exception for wrong token type, but currently doesn't\\n                with pytest.raises(HTTPException) as exc_info:\\n                    await get_auth_service().create_refresh_token(\\\"fake-token\\\", mock_db)\\n\\n                assert exc_info.value.status_code == 401\\n                assert \\\"Invalid refresh token\\\" in str(exc_info.value.detail)\\n\\n    @pytest.mark.asyncio\\n    @pytest.mark.skip(reason=\\\"User activity check not implemented yet - security enhancement for future\\\")\\n    async def test_refresh_token_user_active_check(self):\\n        \\\"\\\"\\\"Test that inactive users cannot refresh tokens.\\n\\n        NOTE: This is a security enhancement that should be implemented.\\n        Currently, the system does not check if a user is active when refreshing tokens.\\n        \\\"\\\"\\\"\\n        from langflow.services.deps import get_auth_service\\n\\n        mock_db = MagicMock()\\n        mock_user = MagicMock()\\n        mock_user.is_active = False  # Inactive user\\n\\n        with patch(\\\"langflow.services.auth.utils.jwt.decode\\\") as mock_decode:\\n            mock_decode.return_value = {\\\"sub\\\": \\\"user-123\\\", \\\"type\\\": \\\"refresh\\\"}  # Correct type\\n\\n            with patch(\\\"langflow.services.auth.utils.get_settings_service\\\") as mock_settings:\\n                mock_settings.return_value.auth_settings.SECRET_KEY.get_secret_value.return_value = \\\"secret\\\"\\n                mock_settings.return_value.auth_settings.ALGORITHM = \\\"HS256\\\"\\n                mock_settings.return_value.auth_settings.ACCESS_TOKEN_EXPIRE_SECONDS = 3600  # 1 hour\\n                mock_settings.return_value.auth_settings.REFRESH_TOKEN_EXPIRE_SECONDS = 86400  # 1 day\\n\\n                with patch(\\\"langflow.services.auth.utils.get_user_by_id\\\") as mock_get_user:\\n                    mock_get_user.return_value = mock_user\\n\\n                    # This SHOULD raise an exception for inactive users, but currently doesn't\\n                    with pytest.raises(HTTPException) as exc_info:\\n                        await get_auth_service().create_refresh_token(\\\"fake-token\\\", mock_db)\\n\\n                    assert exc_info.value.status_code == 401\\n                    assert \\\"inactive\\\" in str(exc_info.value.detail).lower()\\n\\n    @pytest.mark.asyncio\\n    async def test_refresh_token_valid_flow(self):\\n        \\\"\\\"\\\"Test that valid refresh tokens work correctly.\\\"\\\"\\\"\\n        from uuid import uuid4\\n\\n        from langflow.services.auth.service import AuthService\\n        from langflow.services.auth.utils import create_refresh_token\\n\\n        mock_db = AsyncMock()\\n        mock_user = MagicMock()\\n        mock_user.is_active = True  # Active user\\n        user_id = uuid4()\\n        mock_user.id = user_id\\n\\n        # Create a langflow AuthService instance (not lfx) with mocked settings\\n        mock_settings_service = MagicMock()\\n        auth_service = AuthService(mock_settings_service)\\n\\n        with (\\n            patch(\\\"langflow.services.auth.utils._auth_service\\\", return_value=auth_service),\\n            patch(\\\"langflow.services.auth.service.jwt.decode\\\") as mock_decode,\\n        ):\\n            mock_decode.return_value = {\\\"sub\\\": str(user_id), \\\"type\\\": \\\"refresh\\\"}  # Correct type\\n\\n            with patch(\\\"langflow.services.auth.utils.get_jwt_verification_key\\\") as mock_verification_key:\\n                mock_verification_key.return_value = \\\"secret\\\"\\n\\n                with patch(\\\"langflow.services.auth.service.get_user_by_id\\\", new_callable=AsyncMock) as mock_get_user:\\n                    mock_get_user.return_value = mock_user\\n\\n                    with patch.object(auth_service, \\\"create_user_tokens\\\", new_callable=AsyncMock) as mock_create_tokens:\\n                        expected_access = \\\"new-access-token\\\"\\n                        expected_refresh = \\\"new-refresh-token\\\"\\n                        mock_create_tokens.return_value = {\\n                            \\\"access_token\\\": expected_access,\\n                            \\\"refresh_token\\\": expected_refresh,\\n                        }\\n\\n                        result = await create_refresh_token(\\\"fake-token\\\", mock_db)\\n\\n                        assert result[\\\"access_token\\\"] == expected_access\\n                        assert result[\\\"refresh_token\\\"] == expected_refresh\\n                        # user_id is converted to string in JWT payload, then back to UUID in service\\n                        mock_create_tokens.assert_called_once_with(str(user_id), mock_db)\\n\\n    def test_refresh_cookie_defaults_support_same_site_http(self):\\n        \\\"\\\"\\\"Refresh cookies use the same safe, HTTP-compatible defaults as access cookies.\\\"\\\"\\\"\\n        from lfx.services.settings.auth import AuthSettings\\n\\n        with tempfile.TemporaryDirectory() as temp_dir, patch.dict(os.environ, {\\\"LANGFLOW_CONFIG_DIR\\\": temp_dir}):\\n            auth_settings = AuthSettings(CONFIG_DIR=temp_dir)\\n            assert auth_settings.REFRESH_SAME_SITE == \\\"lax\\\"\\n            assert auth_settings.REFRESH_SECURE is False\\n            assert auth_settings.ACCESS_SAME_SITE == \\\"lax\\\"\\n            assert auth_settings.ACCESS_SECURE is False\\n            assert auth_settings.ACCESS_HTTPONLY is True\\n\\n    def test_refresh_cookie_cross_site_https_can_be_enabled(self):\\n        \\\"\\\"\\\"Operators can retain cross-site HTTPS refresh cookies explicitly.\\\"\\\"\\\"\\n        from lfx.services.settings.auth import AuthSettings\\n\\n        with tempfile.TemporaryDirectory() as temp_dir:\\n            auth_settings = AuthSettings(\\n                CONFIG_DIR=temp_dir,\\n                REFRESH_SAME_SITE=\\\"none\\\",\\n                REFRESH_SECURE=True,\\n            )\\n            assert auth_settings.REFRESH_SAME_SITE == \\\"none\\\"\\n            assert auth_settings.REFRESH_SECURE is True\\n\\n\\nclass TestCORSIntegration:\\n    \\\"\\\"\\\"Integration tests for CORS with actual HTTP requests.\\\"\\\"\\\"\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"langflow.main.add_sentry_middleware\\\")  # Mock Sentry setup\\n    async def test_cors_headers_in_response_current_behavior(self, mock_add_sentry_middleware):\\n        \\\"\\\"\\\"Test that CORS headers are properly set in responses (current behavior).\\\"\\\"\\\"\\n        from fastapi.testclient import TestClient\\n\\n        with patch(\\\"langflow.main.get_settings_service\\\") as mock_get_settings:\\n            mock_settings = MagicMock()\\n            mock_settings.settings.cors_origins = [\\\"https://app.example.com\\\"]\\n            mock_settings.settings.cors_allow_credentials = True\\n            mock_settings.settings.cors_allow_methods = \\\"*\\\"\\n            mock_settings.settings.cors_allow_headers = \\\"*\\\"\\n            mock_settings.settings.prometheus_enabled = False\\n            mock_settings.settings.mcp_server_enabled = False\\n            mock_settings.settings.sentry_dsn = None  # Disable Sentry\\n            mock_settings.settings.root_path = \\\"\\\"\\n            mock_get_settings.return_value = mock_settings\\n\\n            from langflow.main import create_app\\n\\n            mock_add_sentry_middleware.return_value = None  # Use the mock\\n            app = create_app()\\n            client = TestClient(app)\\n\\n            # Make OPTIONS request (CORS preflight)\\n            response = client.options(\\n                \\\"/api/v1/version\\\",\\n                headers={\\n                    \\\"Origin\\\": \\\"https://app.example.com\\\",\\n                    \\\"Access-Control-Request-Method\\\": \\\"GET\\\",\\n                },\\n            )\\n\\n            assert response.status_code == 200\\n            assert response.headers.get(\\\"access-control-allow-origin\\\") == \\\"https://app.example.com\\\"\\n            assert response.headers.get(\\\"access-control-allow-credentials\\\") == \\\"true\\\"\\n\\n            # Warn that this is testing current behavior\\n            warnings.warn(\\n                \\\"This test validates current CORS behavior. In v1.7, default origins will be more restrictive.\\\",\\n                UserWarning,\\n                stacklevel=2,\\n            )\\n\\n    @pytest.mark.skip(reason=\\\"Uncomment in v1.7 - represents future secure CORS blocking behavior\\\")\\n    async def test_cors_blocks_unauthorized_origin_future_secure(self):\\n        \\\"\\\"\\\"Test that future secure CORS configuration blocks unauthorized origins (skip until v1.7).\\\"\\\"\\\"\\n        # This test represents the behavior we want in v1.7 with secure defaults\\n\\n    @pytest.mark.asyncio\\n    @patch(\\\"langflow.main.add_sentry_middleware\\\")  # Mock Sentry setup\\n    async def test_cors_blocks_unauthorized_origin_current_behavior(self, mock_add_sentry_middleware):\\n        \\\"\\\"\\\"Test that CORS blocks requests from unauthorized origins.\\\"\\\"\\\"\\n        from fastapi.testclient import TestClient\\n\\n        with patch(\\\"langflow.main.get_settings_service\\\") as mock_get_settings:\\n            mock_settings = MagicMock()\\n            mock_settings.settings.cors_origins = [\\\"https://app.example.com\\\"]\\n            mock_settings.settings.cors_allow_credentials = True\\n            mock_settings.settings.cors_allow_methods = \\\"*\\\"\\n            mock_settings.settings.cors_allow_headers = \\\"*\\\"\\n            mock_settings.settings.prometheus_enabled = False\\n            mock_settings.settings.mcp_server_enabled = False\\n            mock_settings.settings.sentry_dsn = None  # Disable Sentry\\n            mock_settings.settings.root_path = \\\"\\\"\\n            mock_get_settings.return_value = mock_settings\\n\\n            from langflow.main import create_app\\n\\n            mock_add_sentry_middleware.return_value = None  # Use the mock\\n            app = create_app()\\n            client = TestClient(app)\\n\\n            # Make OPTIONS request from unauthorized origin\\n            response = client.options(\\n                \\\"/api/v1/version\\\",\\n                headers={\\n                    \\\"Origin\\\": \\\"https://evil.com\\\",\\n                    \\\"Access-Control-Request-Method\\\": \\\"GET\\\",\\n                },\\n            )\\n\\n            assert response.status_code == 400  # CORS will block this\\n\\n            # Warn about current behavior implications\\n            warnings.warn(\\n                \\\"This test shows current CORS behavior with specific origins. \\\"\\n                \\\"Note that current default behavior uses wildcard origins (*) which would NOT block this. \\\"\\n                \\\"In v1.7, secure defaults will be implemented to prevent unauthorized origins.\\\",\\n                UserWarning,\\n                stacklevel=2,\\n            )\\n\\n\\nclass TestFutureSecureCORSBehavior:\\n    \\\"\\\"\\\"Tests for future secure CORS behavior in v1.7 - currently skipped.\\\"\\\"\\\"\\n\\n    @pytest.mark.skip(reason=\\\"Uncomment in v1.7 - represents future secure default CORS configuration\\\")\\n    def test_future_secure_defaults(self):\\n        \\\"\\\"\\\"Test that v1.7 will have secure CORS defaults.\\\"\\\"\\\"\\n        # Future secure behavior (uncomment in v1.7):\\n        # with tempfile.TemporaryDirectory() as temp_dir, patch.dict(os.environ, {\\\"LANGFLOW_CONFIG_DIR\\\": temp_dir}):\\n        #     settings = Settings()\\n        #     # v1.7 secure defaults:\\n        #     assert settings.cors_origins == [\\\"http://localhost:3000\\\", \\\"http://127.0.0.1:3000\\\", \\\"http://localhost:7860\\\"]\\n        #     assert settings.cors_allow_credentials is True  # Safe with specific origins\\n        #     assert settings.cors_allow_methods == [\\\"GET\\\", \\\"POST\\\", \\\"PUT\\\", \\\"DELETE\\\", \\\"OPTIONS\\\"]\\n        #     assert settings.cors_allow_headers == [\\\"Content-Type\\\", \\\"Authorization\\\", \\\"X-Requested-With\\\"]\\n\\n    @pytest.mark.skip(reason=\\\"Uncomment in v1.7 - represents future secure wildcard rejection\\\")\\n    def test_future_wildcard_rejection(self):\\n        \\\"\\\"\\\"Test that v1.7 will warn about or reject wildcard origins in production.\\\"\\\"\\\"\\n        # Future behavior (uncomment in v1.7):\\n        # with (\\n        #     tempfile.TemporaryDirectory() as temp_dir,\\n        #     patch.dict(\\n        #         os.environ,\\n        #         {\\n        #             \\\"LANGFLOW_CONFIG_DIR\\\": temp_dir,\\n        #             \\\"LANGFLOW_CORS_ORIGINS\\\": \\\"*\\\",\\n        #         },\\n        #     ),\\n        # ):\\n        #     # Should either warn strongly or reject wildcard in production mode\\n        #     with pytest.warns(UserWarning, match=\\\"SECURITY WARNING.*wildcard.*production\\\"):\\n        #         settings = Settings()\\n        #         # Or potentially: pytest.raises(ValueError, match=\\\"Wildcard origins not allowed in production\\\")\\n\\n    @pytest.mark.skip(reason=\\\"Uncomment in v1.7 - represents future secure middleware configuration\\\")\\n    async def test_future_secure_middleware_config(self):\\n        \\\"\\\"\\\"Test that v1.7 middleware will use secure defaults.\\\"\\\"\\\"\\n        # Future secure middleware behavior (uncomment in v1.7):\\n        # Test that the app creates middleware with secure defaults\\n        # and properly validates origins in production mode\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_security_dependency_floors.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bd33692584bcb72f20bc964d59f56bd5a8e6d7b53be54d4d3b0ac7a4be330c18\",\"content\":\"\\\"\\\"\\\"Regression tests for security dependency floors in published package metadata.\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport runpy\\nimport sys\\nfrom pathlib import Path\\n\\nfrom packaging.requirements import Requirement\\nfrom packaging.version import Version\\n\\nif sys.version_info >= (3, 11):\\n    import tomllib\\nelse:\\n    import tomli as tomllib\\n\\nREPO_ROOT = Path(__file__).resolve().parents[4]\\n\\n\\ndef _load_pyproject(relative_path: str) -> dict:\\n    with (REPO_ROOT / relative_path).open(\\\"rb\\\") as pyproject_file:\\n        return tomllib.load(pyproject_file)\\n\\n\\ndef _requirement(requirements: list[str], name: str) -> Requirement:\\n    matches = [requirement for spec in requirements if (requirement := Requirement(spec)).name.lower() == name.lower()]\\n    assert len(matches) == 1, f\\\"Expected one {name} requirement, found {matches}\\\"\\n    assert matches[0].marker is None, f\\\"Security floor for {name} must be unconditional\\\"\\n    return matches[0]\\n\\n\\ndef _assert_specifier(requirement: Requirement, operator: str, version: str) -> None:\\n    assert any(spec.operator == operator and spec.version == version for spec in requirement.specifier), requirement\\n\\n\\ndef _assert_floor(requirement: Requirement, version: str) -> None:\\n    floor = Version(version)\\n    assert any(\\n        specifier.operator == \\\">=\\\" and Version(specifier.version) >= floor for specifier in requirement.specifier\\n    ), requirement\\n\\n\\ndef test_workspace_security_overrides_enforce_patched_versions() -> None:\\n    overrides = _load_pyproject(\\\"pyproject.toml\\\")[\\\"tool\\\"][\\\"uv\\\"][\\\"override-dependencies\\\"]\\n\\n    gitpython = _requirement(overrides, \\\"GitPython\\\")\\n    _assert_floor(gitpython, \\\"3.1.58\\\")\\n\\n    pypdf = _requirement(overrides, \\\"pypdf\\\")\\n    _assert_floor(pypdf, \\\"6.16.1\\\")\\n    _assert_specifier(pypdf, \\\"<\\\", \\\"7.0.0\\\")\\n\\n    h2 = _requirement(overrides, \\\"h2\\\")\\n    _assert_floor(h2, \\\"4.4.1\\\")\\n\\n\\ndef test_managed_dependency_graph_excludes_opendsstar_and_diskcache() -> None:\\n    \\\"\\\"\\\"Even opt-in extras and test groups must not reintroduce the retired dependency.\\\"\\\"\\\"\\n    with (REPO_ROOT / \\\"uv.lock\\\").open(\\\"rb\\\") as lock_file:\\n        packages = tomllib.load(lock_file)[\\\"package\\\"]\\n    package_names = {package[\\\"name\\\"] for package in packages}\\n    assert not {\\\"opendsstar\\\", \\\"diskcache\\\"} & package_names\\n\\n    generator = runpy.run_path(str(REPO_ROOT / \\\"scripts/migrate/consolidate_bundles.py\\\"))\\n    requirements = {Requirement(spec).name.lower() for specs in generator[\\\"PROVIDER_DEPS\\\"].values() for spec in specs}\\n    assert not {\\\"opendsstar\\\", \\\"diskcache\\\"} & requirements\\n\\n\\ndef test_published_packages_enforce_patched_h2_floor() -> None:\\n    for relative_path in (\\n        \\\"src/backend/base/pyproject.toml\\\",\\n        \\\"src/lfx/pyproject.toml\\\",\\n        \\\"src/sdk/pyproject.toml\\\",\\n    ):\\n        dependencies = _load_pyproject(relative_path)[\\\"project\\\"][\\\"dependencies\\\"]\\n        _assert_floor(_requirement(dependencies, \\\"h2\\\"), \\\"4.4.1\\\")\\n\\n\\ndef test_published_packages_enforce_patched_pypdf_floor() -> None:\\n    for relative_path in (\\\"src/backend/base/pyproject.toml\\\", \\\"src/lfx/pyproject.toml\\\"):\\n        dependencies = _load_pyproject(relative_path)[\\\"project\\\"][\\\"dependencies\\\"]\\n        pypdf = _requirement(dependencies, \\\"pypdf\\\")\\n        _assert_floor(pypdf, \\\"6.16.1\\\")\\n        _assert_specifier(pypdf, \\\"<\\\", \\\"7.0.0\\\")\\n\\n    base_extras = _load_pyproject(\\\"src/backend/base/pyproject.toml\\\")[\\\"project\\\"][\\\"optional-dependencies\\\"]\\n    pypdf_extra = _requirement(base_extras[\\\"pypdf\\\"], \\\"pypdf\\\")\\n    _assert_floor(pypdf_extra, \\\"6.16.1\\\")\\n    _assert_specifier(pypdf_extra, \\\"<\\\", \\\"7.0.0\\\")\\n\\n\\ndef test_published_extras_enforce_patched_gitpython_floor() -> None:\\n    base_extras = _load_pyproject(\\\"src/backend/base/pyproject.toml\\\")[\\\"project\\\"][\\\"optional-dependencies\\\"]\\n    _assert_floor(_requirement(base_extras[\\\"gitpython\\\"], \\\"GitPython\\\"), \\\"3.1.58\\\")\\n\\n    bundle_extras = _load_pyproject(\\\"src/bundles/lfx-bundles/pyproject.toml\\\")[\\\"project\\\"][\\\"optional-dependencies\\\"]\\n    _assert_floor(_requirement(bundle_extras[\\\"git\\\"], \\\"GitPython\\\"), \\\"3.1.58\\\")\\n\\n    generator = runpy.run_path(str(REPO_ROOT / \\\"scripts/migrate/consolidate_bundles.py\\\"))\\n    assert generator[\\\"PROVIDER_DEPS\\\"][\\\"git\\\"] == bundle_extras[\\\"git\\\"]\\n\\n\\ndef test_first_community_migration_has_no_direct_dependency_edges() -> None:\\n    generator = runpy.run_path(str(REPO_ROOT / \\\"scripts/migrate/consolidate_bundles.py\\\"))\\n    extras = _load_pyproject(\\\"src/bundles/lfx-bundles/pyproject.toml\\\")[\\\"project\\\"][\\\"optional-dependencies\\\"]\\n    for name in (\\\"apify\\\", \\\"chroma\\\", \\\"cloudflare\\\", \\\"needle\\\"):\\n        assert extras[name] == generator[\\\"PROVIDER_DEPS\\\"][name]\\n        assert \\\"langchain-community\\\" not in {Requirement(spec).name for spec in extras[name]}\\n    for name in (\\\"ibm\\\", \\\"oracle\\\"):\\n        deps = _load_pyproject(f\\\"src/bundles/{name}/pyproject.toml\\\")[\\\"project\\\"][\\\"dependencies\\\"]\\n        assert \\\"langchain-community\\\" not in {Requirement(spec).name for spec in deps}\\n    oracle = _load_pyproject(\\\"src/bundles/oracle/pyproject.toml\\\")[\\\"project\\\"][\\\"dependencies\\\"]\\n    _assert_floor(_requirement(oracle, \\\"langchain-oracledb\\\"), \\\"1.5.0\\\")\\n\\n\\ndef test_provider_upgrades_remove_indirect_community_requirements() -> None:\\n    with (REPO_ROOT / \\\"uv.lock\\\").open(\\\"rb\\\") as lock_file:\\n        packages = tomllib.load(lock_file)[\\\"package\\\"]\\n    for name, minimum in ((\\\"langchain-cohere\\\", \\\"0.6.0\\\"), (\\\"langchain-google-community\\\", \\\"5.0.0\\\")):\\n        matches = [package for package in packages if package[\\\"name\\\"] == name]\\n        assert matches\\n        for package in matches:\\n            assert Version(package[\\\"version\\\"]) >= Version(minimum)\\n            assert \\\"langchain-community\\\" not in {dep[\\\"name\\\"] for dep in package.get(\\\"dependencies\\\", [])}\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_server_logger.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3c159028b598005c96986095d96f063ce3b5394d8326b026c9b20485aa609647\",\"content\":\"\\\"\\\"\\\"Tests for ``langflow.server.Logger``'s stdlib logging wiring.\\n\\nRegression cover for LE-2454 / #14776: with ``LANGFLOW_LOG_FILE`` set, the\\ngunicorn loggers used to be given an ``InterceptHandler`` unconditionally. In that\\nmode ``structlog.get_logger(name)`` resolves back to the stdlib logger of the same\\nname, so the handler fed the logger it was attached to and the record cycled,\\ngrowing every lap until the process was OOM-killed.\\n\\nThree things have to hold, and each is easy to break independently:\\n\\n* stdout mode keeps the intercept (unchanged behaviour);\\n* file mode attaches the rotating file handler *itself*, not an empty list --\\n  ``UvicornWorker`` copies this list onto the uvicorn loggers and sets\\n  ``propagate = False``, so an empty list silently drops every uvicorn record;\\n* it must hold when ``configure()`` already ran before the ``Logger`` is built,\\n  because the repeat call early-returns on an unchanged fingerprint and never\\n  re-runs ``setup_gunicorn_logger()``.\\n\\\"\\\"\\\"\\n\\nimport contextlib\\nimport importlib\\nimport logging\\nfrom pathlib import Path\\n\\nimport pytest\\nimport structlog\\nfrom gunicorn.config import Config\\nfrom langflow.server import Logger\\nfrom lfx.log.logger import InterceptHandler, configure, get_file_handler\\n\\n# A cycle regression would recurse until the machine gives out. Cap the number of\\n# times ``InterceptHandler.emit`` may run per test so a regression fails an assert\\n# in milliseconds instead of exhausting CI memory.\\nEMIT_CAP = 20\\n\\nGUNICORN_LOGGERS = (\\\"gunicorn.error\\\", \\\"gunicorn.access\\\")\\nUVICORN_LOGGERS = (\\\"uvicorn.error\\\", \\\"uvicorn.access\\\")\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _restore_logging_state():\\n    \\\"\\\"\\\"Snapshot and restore every process-global this module rewires.\\n\\n    ``configure(log_file=...)`` sets ``logging.root``'s level, installs a\\n    ``RotatingFileHandler`` on the root logger and stores it in the\\n    ``lfx.log.logger._file_handler`` module global. ``Logger.__init__`` then edits\\n    the gunicorn loggers, and the uvicorn tests edit theirs. None of that is\\n    undone automatically, and leaking a handler pointed at a deleted tmp_path into\\n    a later test is how this module would poison an xdist worker.\\n    \\\"\\\"\\\"\\n    lfx_log = importlib.import_module(\\\"lfx.log.logger\\\")\\n\\n    orig_structlog_config = dict(structlog.get_config())\\n    orig_root_handlers = logging.root.handlers[:]\\n    orig_root_level = logging.root.level\\n    orig_file_handler = lfx_log._file_handler\\n    orig_named = {\\n        name: (lg.handlers[:], lg.level, lg.propagate)\\n        for name in (*GUNICORN_LOGGERS, *UVICORN_LOGGERS)\\n        if (lg := logging.getLogger(name))\\n    }\\n\\n    yield\\n\\n    # Close any file handler this test opened before putting the old one back,\\n    # otherwise the fd leaks and the tmp_path cannot be cleaned up on Windows.\\n    for handler in logging.root.handlers[:]:\\n        if handler not in orig_root_handlers:\\n            logging.root.removeHandler(handler)\\n            with contextlib.suppress(OSError, ValueError):\\n                handler.close()\\n\\n    # If configure() replaced the lfx-managed file handler it also *closed* the\\n    # original, so reinstalling that one would put a handler pointed at a\\n    # torn-down tmp_path back on the root logger -- where the next record silently\\n    # re-creates the file or fails into handleError. Drop it instead, exactly as\\n    # the module fixture in test_logger.py does.\\n    restored_handlers = orig_root_handlers\\n    if lfx_log._file_handler is not orig_file_handler:\\n        restored_handlers = [h for h in orig_root_handlers if h is not orig_file_handler]\\n        lfx_log._file_handler = None\\n    else:\\n        lfx_log._file_handler = orig_file_handler\\n\\n    logging.root.handlers[:] = restored_handlers\\n    logging.root.setLevel(orig_root_level)\\n    for name, (handlers, level, propagate) in orig_named.items():\\n        lg = logging.getLogger(name)\\n        lg.handlers[:] = handlers\\n        lg.setLevel(level)\\n        lg.propagate = propagate\\n\\n    structlog.configure(**orig_structlog_config)\\n\\n\\n@pytest.fixture\\ndef capped_emit(monkeypatch):\\n    \\\"\\\"\\\"Count ``InterceptHandler.emit`` calls and abort past ``EMIT_CAP``.\\\"\\\"\\\"\\n    calls = []\\n    original = InterceptHandler.emit\\n\\n    def counting_emit(self, record):\\n        calls.append(record)\\n        if len(calls) > EMIT_CAP:\\n            msg = f\\\"InterceptHandler.emit re-entered more than {EMIT_CAP} times -- the LE-2454 cycle is back\\\"\\n            raise AssertionError(msg)\\n        return original(self, record)\\n\\n    monkeypatch.setattr(InterceptHandler, \\\"emit\\\", counting_emit)\\n    return calls\\n\\n\\ndef _gunicorn_config() -> Config:\\n    cfg = Config()\\n    cfg.set(\\\"loglevel\\\", \\\"info\\\")\\n    return cfg\\n\\n\\ndef _read_log(log_file: Path) -> list[str]:\\n    handler = get_file_handler()\\n    if handler is not None:\\n        handler.flush()\\n    if not log_file.exists():\\n        return []\\n    return [line for line in log_file.read_text().splitlines() if line]\\n\\n\\nclass TestHandlerWiring:\\n    \\\"\\\"\\\"Which handler each mode installs on the gunicorn loggers.\\\"\\\"\\\"\\n\\n    def test_stdout_mode_keeps_the_intercept_handler(self):\\n        \\\"\\\"\\\"With no log file structlog renders directly, so the intercept terminates.\\\"\\\"\\\"\\n        configure(log_level=\\\"ERROR\\\")\\n\\n        Logger(_gunicorn_config())\\n\\n        for name in GUNICORN_LOGGERS:\\n            handlers = logging.getLogger(name).handlers\\n            assert len(handlers) == 1\\n            assert isinstance(handlers[0], InterceptHandler)\\n\\n    def test_file_mode_attaches_the_file_handler_instead(self, tmp_path):\\n        \\\"\\\"\\\"In file mode an intercept would cycle, so the file handler is attached directly.\\\"\\\"\\\"\\n        configure(log_level=\\\"ERROR\\\", log_file=tmp_path / \\\"langflow.log\\\")\\n\\n        Logger(_gunicorn_config())\\n\\n        for name in GUNICORN_LOGGERS:\\n            lg = logging.getLogger(name)\\n            assert not any(isinstance(h, InterceptHandler) for h in lg.handlers)\\n            assert lg.handlers == [get_file_handler()]\\n            # The handler is attached directly; propagating to root -- which owns\\n            # that same handler -- would write every record twice.\\n            assert lg.propagate is False\\n\\n\\nclass TestRecordsReachTheFile:\\n    \\\"\\\"\\\"One record in, one line out, in the modes that used to lose or loop it.\\\"\\\"\\\"\\n\\n    def test_gunicorn_error_is_written_exactly_once(self, tmp_path, capped_emit):\\n        log_file = tmp_path / \\\"langflow.log\\\"\\n        configure(log_level=\\\"ERROR\\\", log_file=log_file)\\n        Logger(_gunicorn_config())\\n\\n        logging.getLogger(\\\"gunicorn.error\\\").error(\\\"boom\\\")\\n\\n        assert _read_log(log_file) == [\\\"boom\\\"]\\n        assert capped_emit == []\\n\\n    def test_uvicorn_logger_inherits_a_terminating_handler(self, tmp_path, capped_emit):\\n        \\\"\\\"\\\"Replicates ``UvicornWorker.__init__``'s handler copy.\\n\\n        uvicorn assigns gunicorn's handler *list* to the uvicorn loggers and turns\\n        propagation off, so whatever ``Logger`` installed is the only thing standing\\n        between a uvicorn record and the void.\\n        \\\"\\\"\\\"\\n        log_file = tmp_path / \\\"langflow.log\\\"\\n        configure(log_level=\\\"ERROR\\\", log_file=log_file)\\n        Logger(_gunicorn_config())\\n\\n        for gunicorn_name, uvicorn_name in zip(GUNICORN_LOGGERS, UVICORN_LOGGERS, strict=True):\\n            uvicorn_logger = logging.getLogger(uvicorn_name)\\n            uvicorn_logger.handlers = logging.getLogger(gunicorn_name).handlers\\n            uvicorn_logger.setLevel(logging.WARNING)\\n            uvicorn_logger.propagate = False\\n\\n        logging.getLogger(\\\"uvicorn.error\\\").error(\\\"boom\\\")\\n\\n        assert _read_log(log_file) == [\\\"boom\\\"]\\n        assert capped_emit == []\\n\\n    def test_holds_when_configure_early_returns(self, tmp_path, capped_emit):\\n        \\\"\\\"\\\"LE-2454's deciding variable: ``configure()`` ran before the ``Logger``.\\n\\n        This is the real boot order -- ``langflow/__main__.py`` configures logging\\n        long before ``LangflowApplication`` is constructed. The app's later\\n        ``configure()`` call carries identical arguments, so it early-returns on the\\n        unchanged fingerprint and never reaches ``setup_gunicorn_logger()``. Nothing\\n        cleans up after ``Logger.__init__``, which is why the fix cannot rely on it.\\n        \\\"\\\"\\\"\\n        log_file = tmp_path / \\\"langflow.log\\\"\\n        configure(log_level=\\\"ERROR\\\", log_file=log_file)\\n        Logger(_gunicorn_config())\\n\\n        # Same arguments -> unchanged fingerprint -> early return.\\n        configure(log_level=\\\"ERROR\\\", log_file=log_file)\\n\\n        assert not any(isinstance(h, InterceptHandler) for h in logging.getLogger(\\\"gunicorn.error\\\").handlers)\\n\\n        logging.getLogger(\\\"gunicorn.error\\\").error(\\\"boom\\\")\\n\\n        assert _read_log(log_file) == [\\\"boom\\\"]\\n        assert capped_emit == []\\n\\n    def test_large_record_is_not_amplified(self, tmp_path, capped_emit):\\n        \\\"\\\"\\\"Pretty mode's failure was a threshold, not an absence.\\n\\n        Each lap of the cycle carried a copy of the previous message, so peak memory\\n        and bytes-on-disk scaled with the size of the originating record: a 4-byte\\n        message survived while a 10 MB one OOM-killed the process. A short-message\\n        test therefore passes against the unfixed code -- this one has to be big.\\n        \\\"\\\"\\\"\\n        log_file = tmp_path / \\\"langflow.log\\\"\\n        configure(log_level=\\\"ERROR\\\", log_file=log_file)\\n        Logger(_gunicorn_config())\\n\\n        payload = \\\"x\\\" * 1_000_000\\n        logging.getLogger(\\\"gunicorn.error\\\").error(payload)\\n\\n        lines = _read_log(log_file)\\n        assert lines == [payload]\\n        # Written once, not once per lap.\\n        assert log_file.stat().st_size < 2 * len(payload)\\n        assert capped_emit == []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_session_endpoint.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"73c6c0dd55d8f7d1b3da7a4e97d292035fefca9a61fbf38fe760835dce6decb8\",\"content\":\"from uuid import uuid4\\n\\nimport pytest\\nfrom httpx import AsyncClient\\nfrom langflow.memory import aadd_messagetables\\nfrom langflow.services.database.models.message.model import MessageTable\\nfrom langflow.services.deps import session_scope\\n\\n\\n@pytest.fixture\\nasync def messages_with_flow_ids(session):  # noqa: ARG001\\n    \\\"\\\"\\\"Create messages with different session_ids and flow_ids for testing sessions endpoint.\\\"\\\"\\\"\\n    async with session_scope() as _session:\\n        flow_id_1 = uuid4()\\n        flow_id_2 = uuid4()\\n\\n        # Create MessageTable objects directly since MessageCreate doesn't have flow_id field\\n        messagetables = [\\n            MessageTable(\\n                text=\\\"Message 1\\\", sender=\\\"User\\\", sender_name=\\\"User\\\", session_id=\\\"session_A\\\", flow_id=flow_id_1\\n            ),\\n            MessageTable(text=\\\"Message 2\\\", sender=\\\"AI\\\", sender_name=\\\"AI\\\", session_id=\\\"session_A\\\", flow_id=flow_id_1),\\n            MessageTable(\\n                text=\\\"Message 3\\\", sender=\\\"User\\\", sender_name=\\\"User\\\", session_id=\\\"session_B\\\", flow_id=flow_id_1\\n            ),\\n            MessageTable(\\n                text=\\\"Message 4\\\", sender=\\\"User\\\", sender_name=\\\"User\\\", session_id=\\\"session_C\\\", flow_id=flow_id_2\\n            ),\\n            MessageTable(text=\\\"Message 5\\\", sender=\\\"AI\\\", sender_name=\\\"AI\\\", session_id=\\\"session_D\\\", flow_id=flow_id_2),\\n            MessageTable(\\n                text=\\\"Message 6\\\",\\n                sender=\\\"User\\\",\\n                sender_name=\\\"User\\\",\\n                session_id=\\\"session_E\\\",\\n                flow_id=None,  # No flow_id\\n            ),\\n        ]\\n        created_messages = await aadd_messagetables(messagetables, _session)\\n\\n        return {\\n            \\\"messages\\\": created_messages,\\n            \\\"flow_id_1\\\": flow_id_1,\\n            \\\"flow_id_2\\\": flow_id_2,\\n            \\\"expected_sessions_flow_1\\\": {\\\"session_A\\\", \\\"session_B\\\"},\\n            \\\"expected_sessions_flow_2\\\": {\\\"session_C\\\", \\\"session_D\\\"},\\n            \\\"expected_all_sessions\\\": {\\\"session_A\\\", \\\"session_B\\\", \\\"session_C\\\", \\\"session_D\\\", \\\"session_E\\\"},\\n        }\\n\\n\\n# Tests for /sessions endpoint\\n@pytest.mark.api_key_required\\nasync def test_get_sessions_all(client: AsyncClient, logged_in_headers, messages_with_flow_ids):\\n    \\\"\\\"\\\"Test getting all sessions without any filter.\\\"\\\"\\\"\\n    response = await client.get(\\\"api/v1/monitor/messages/sessions\\\", headers=logged_in_headers)\\n\\n    assert response.status_code == 200, response.text\\n    sessions = response.json()\\n    assert isinstance(sessions, list)\\n\\n    # Convert to set for easier comparison since order doesn't matter\\n    returned_sessions = set(sessions)\\n    expected_sessions = messages_with_flow_ids[\\\"expected_all_sessions\\\"]\\n\\n    assert returned_sessions == expected_sessions\\n    assert len(sessions) == len(expected_sessions)\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_get_sessions_with_flow_id_filter(client: AsyncClient, logged_in_headers, messages_with_flow_ids):\\n    \\\"\\\"\\\"Test getting sessions filtered by flow_id.\\\"\\\"\\\"\\n    flow_id_1 = messages_with_flow_ids[\\\"flow_id_1\\\"]\\n\\n    response = await client.get(\\n        \\\"api/v1/monitor/messages/sessions\\\", params={\\\"flow_id\\\": str(flow_id_1)}, headers=logged_in_headers\\n    )\\n\\n    assert response.status_code == 200, response.text\\n    sessions = response.json()\\n    assert isinstance(sessions, list)\\n\\n    returned_sessions = set(sessions)\\n    expected_sessions = messages_with_flow_ids[\\\"expected_sessions_flow_1\\\"]\\n\\n    assert returned_sessions == expected_sessions\\n    assert len(sessions) == len(expected_sessions)\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_get_sessions_with_different_flow_id(client: AsyncClient, logged_in_headers, messages_with_flow_ids):\\n    \\\"\\\"\\\"Test getting sessions filtered by a different flow_id.\\\"\\\"\\\"\\n    flow_id_2 = messages_with_flow_ids[\\\"flow_id_2\\\"]\\n\\n    response = await client.get(\\n        \\\"api/v1/monitor/messages/sessions\\\", params={\\\"flow_id\\\": str(flow_id_2)}, headers=logged_in_headers\\n    )\\n\\n    assert response.status_code == 200, response.text\\n    sessions = response.json()\\n    assert isinstance(sessions, list)\\n\\n    returned_sessions = set(sessions)\\n    expected_sessions = messages_with_flow_ids[\\\"expected_sessions_flow_2\\\"]\\n\\n    assert returned_sessions == expected_sessions\\n    assert len(sessions) == len(expected_sessions)\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_get_sessions_with_non_existent_flow_id(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Test getting sessions with a non-existent flow_id returns empty list.\\\"\\\"\\\"\\n    non_existent_flow_id = uuid4()\\n\\n    response = await client.get(\\n        \\\"api/v1/monitor/messages/sessions\\\", params={\\\"flow_id\\\": str(non_existent_flow_id)}, headers=logged_in_headers\\n    )\\n\\n    assert response.status_code == 200, response.text\\n    sessions = response.json()\\n    assert isinstance(sessions, list)\\n    assert len(sessions) == 0\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_get_sessions_empty_database(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Test getting sessions when no messages exist in database.\\\"\\\"\\\"\\n    response = await client.get(\\\"api/v1/monitor/messages/sessions\\\", headers=logged_in_headers)\\n\\n    assert response.status_code == 200, response.text\\n    sessions = response.json()\\n    assert isinstance(sessions, list)\\n    assert len(sessions) == 0\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_get_sessions_invalid_flow_id_format(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Test getting sessions with invalid flow_id format returns 422.\\\"\\\"\\\"\\n    response = await client.get(\\n        \\\"api/v1/monitor/messages/sessions\\\", params={\\\"flow_id\\\": \\\"invalid-uuid\\\"}, headers=logged_in_headers\\n    )\\n\\n    assert response.status_code == 422, response.text\\n    assert \\\"detail\\\" in response.json()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_session_metadata.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d93928fa790d4f4c304a68153302b887fc82a2f914ddb51da44c5e508a16d055\",\"content\":\"\\\"\\\"\\\"Unit tests for session_metadata functionality in Message and MessageTable.\\\"\\\"\\\"\\n\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.memory import aadd_messages, aget_messages, astore_message\\nfrom langflow.schema.message import Message\\nfrom langflow.services.database.models.message import MessageCreate, MessageRead\\nfrom langflow.services.database.models.message.model import MessageTable\\nfrom langflow.services.deps import session_scope\\n\\n\\n@pytest.fixture\\ndef sample_session_metadata():\\n    \\\"\\\"\\\"Sample session metadata for testing.\\\"\\\"\\\"\\n    return {\\n        \\\"tenant_id\\\": \\\"tenant-123\\\",\\n        \\\"user_id\\\": \\\"user-456\\\",\\n        \\\"region\\\": \\\"us-east-1\\\",\\n        \\\"retention_profile\\\": \\\"standard\\\",\\n        \\\"data_flags\\\": {\\\"pii\\\": True, \\\"sensitive\\\": False},\\n        \\\"custom_fields\\\": {\\\"department\\\": \\\"engineering\\\", \\\"project\\\": \\\"langflow\\\"},\\n    }\\n\\n\\n@pytest.fixture\\ndef minimal_session_metadata():\\n    \\\"\\\"\\\"Minimal session metadata for testing.\\\"\\\"\\\"\\n    return {\\n        \\\"tenant_id\\\": \\\"tenant-789\\\",\\n        \\\"user_id\\\": \\\"user-012\\\",\\n    }\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_message_with_session_metadata(sample_session_metadata):\\n    \\\"\\\"\\\"Test creating a Message with session_metadata.\\\"\\\"\\\"\\n    message = Message(\\n        text=\\\"Test message with metadata\\\",\\n        sender=\\\"User\\\",\\n        sender_name=\\\"Test User\\\",\\n        session_id=\\\"test_session_1\\\",\\n        session_metadata=sample_session_metadata,\\n    )\\n\\n    assert message.session_metadata == sample_session_metadata\\n    assert message.session_metadata[\\\"tenant_id\\\"] == \\\"tenant-123\\\"\\n    assert message.session_metadata[\\\"user_id\\\"] == \\\"user-456\\\"\\n    assert message.session_metadata[\\\"region\\\"] == \\\"us-east-1\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_message_without_session_metadata():\\n    \\\"\\\"\\\"Test creating a Message without session_metadata (backward compatibility).\\\"\\\"\\\"\\n    message = Message(\\n        text=\\\"Test message without metadata\\\",\\n        sender=\\\"User\\\",\\n        sender_name=\\\"Test User\\\",\\n        session_id=\\\"test_session_2\\\",\\n    )\\n\\n    assert message.session_metadata is None\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_store_message_with_session_metadata(sample_session_metadata):\\n    \\\"\\\"\\\"Test storing a message with session_metadata.\\\"\\\"\\\"\\n    session_id = f\\\"stored_session_{uuid4()}\\\"\\n    message = Message(\\n        text=\\\"Stored message with metadata\\\",\\n        sender=\\\"User\\\",\\n        sender_name=\\\"Test User\\\",\\n        session_id=session_id,\\n        session_metadata=sample_session_metadata,\\n    )\\n\\n    await astore_message(message)\\n\\n    # Retrieve and verify\\n    stored_messages = await aget_messages(sender=\\\"User\\\", session_id=session_id)\\n    assert len(stored_messages) == 1\\n    assert stored_messages[0].text == \\\"Stored message with metadata\\\"\\n    assert stored_messages[0].session_metadata == sample_session_metadata\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_store_message_without_session_metadata():\\n    \\\"\\\"\\\"Test storing a message without session_metadata (backward compatibility).\\\"\\\"\\\"\\n    session_id = f\\\"stored_session_{uuid4()}\\\"\\n    message = Message(\\n        text=\\\"Stored message without metadata\\\",\\n        sender=\\\"User\\\",\\n        sender_name=\\\"Test User\\\",\\n        session_id=session_id,\\n    )\\n\\n    await astore_message(message)\\n\\n    # Retrieve and verify\\n    stored_messages = await aget_messages(sender=\\\"User\\\", session_id=session_id)\\n    assert len(stored_messages) == 1\\n    assert stored_messages[0].text == \\\"Stored message without metadata\\\"\\n    assert stored_messages[0].session_metadata is None\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_add_messages_with_session_metadata(sample_session_metadata, minimal_session_metadata):\\n    \\\"\\\"\\\"Test adding multiple messages with different session_metadata.\\\"\\\"\\\"\\n    session_id = f\\\"batch_session_{uuid4()}\\\"\\n    messages = [\\n        Message(\\n            text=\\\"Message 1 with full metadata\\\",\\n            sender=\\\"User\\\",\\n            sender_name=\\\"User 1\\\",\\n            session_id=session_id,\\n            session_metadata=sample_session_metadata,\\n        ),\\n        Message(\\n            text=\\\"Message 2 with minimal metadata\\\",\\n            sender=\\\"User\\\",\\n            sender_name=\\\"User 2\\\",\\n            session_id=session_id,\\n            session_metadata=minimal_session_metadata,\\n        ),\\n        Message(\\n            text=\\\"Message 3 without metadata\\\",\\n            sender=\\\"User\\\",\\n            sender_name=\\\"User 3\\\",\\n            session_id=session_id,\\n        ),\\n    ]\\n\\n    added_messages = await aadd_messages(messages)\\n\\n    assert len(added_messages) == 3\\n    assert added_messages[0].session_metadata == sample_session_metadata\\n    assert added_messages[1].session_metadata == minimal_session_metadata\\n    assert added_messages[2].session_metadata is None\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_messagetable_from_message_with_metadata(sample_session_metadata):\\n    \\\"\\\"\\\"Test MessageTable.from_message() extracts session_metadata correctly.\\\"\\\"\\\"\\n    message = Message(\\n        text=\\\"Test message\\\",\\n        sender=\\\"User\\\",\\n        sender_name=\\\"Test User\\\",\\n        session_id=\\\"test_session_3\\\",\\n        session_metadata=sample_session_metadata,\\n    )\\n\\n    message_table = MessageTable.from_message(message, flow_id=uuid4())\\n\\n    assert message_table.session_metadata == sample_session_metadata\\n    assert message_table.session_metadata[\\\"tenant_id\\\"] == \\\"tenant-123\\\"\\n    assert message_table.session_metadata[\\\"user_id\\\"] == \\\"user-456\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_messagetable_from_message_without_metadata():\\n    \\\"\\\"\\\"Test MessageTable.from_message() handles missing session_metadata.\\\"\\\"\\\"\\n    message = Message(\\n        text=\\\"Test message\\\",\\n        sender=\\\"User\\\",\\n        sender_name=\\\"Test User\\\",\\n        session_id=\\\"test_session_4\\\",\\n    )\\n\\n    message_table = MessageTable.from_message(message, flow_id=uuid4())\\n\\n    assert message_table.session_metadata is None\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_messagecreate_with_session_metadata(sample_session_metadata):\\n    \\\"\\\"\\\"Test MessageCreate schema with session_metadata.\\\"\\\"\\\"\\n    message_create = MessageCreate(\\n        text=\\\"Test message\\\",\\n        sender=\\\"User\\\",\\n        sender_name=\\\"Test User\\\",\\n        session_id=\\\"test_session_5\\\",\\n        session_metadata=sample_session_metadata,\\n    )\\n\\n    assert message_create.session_metadata == sample_session_metadata\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_messagecreate_without_session_metadata():\\n    \\\"\\\"\\\"Test MessageCreate schema without session_metadata.\\\"\\\"\\\"\\n    message_create = MessageCreate(\\n        text=\\\"Test message\\\",\\n        sender=\\\"User\\\",\\n        sender_name=\\\"Test User\\\",\\n        session_id=\\\"test_session_6\\\",\\n    )\\n\\n    assert message_create.session_metadata is None\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_messageread_with_session_metadata(sample_session_metadata):\\n    \\\"\\\"\\\"Test MessageRead schema includes session_metadata.\\\"\\\"\\\"\\n    async with session_scope() as session:\\n        message_create = MessageCreate(\\n            text=\\\"Test message\\\",\\n            sender=\\\"User\\\",\\n            sender_name=\\\"Test User\\\",\\n            session_id=f\\\"test_session_{uuid4()}\\\",\\n            session_metadata=sample_session_metadata,\\n        )\\n        message_table = MessageTable.model_validate(message_create, from_attributes=True)\\n        session.add(message_table)\\n        await session.commit()\\n        await session.refresh(message_table)\\n\\n        message_read = MessageRead.model_validate(message_table, from_attributes=True)\\n\\n        assert message_read.session_metadata == sample_session_metadata\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_session_metadata_persistence_and_retrieval(sample_session_metadata):\\n    \\\"\\\"\\\"Test full cycle: create, store, retrieve, and verify session_metadata.\\\"\\\"\\\"\\n    session_id = f\\\"full_cycle_session_{uuid4()}\\\"\\n\\n    # Create and store\\n    message = Message(\\n        text=\\\"Full cycle test message\\\",\\n        sender=\\\"User\\\",\\n        sender_name=\\\"Test User\\\",\\n        session_id=session_id,\\n        session_metadata=sample_session_metadata,\\n    )\\n    await astore_message(message)\\n\\n    # Retrieve\\n    retrieved_messages = await aget_messages(sender=\\\"User\\\", session_id=session_id)\\n\\n    # Verify\\n    assert len(retrieved_messages) == 1\\n    retrieved = retrieved_messages[0]\\n    assert retrieved.text == \\\"Full cycle test message\\\"\\n    assert retrieved.session_metadata is not None\\n    assert retrieved.session_metadata[\\\"tenant_id\\\"] == \\\"tenant-123\\\"\\n    assert retrieved.session_metadata[\\\"user_id\\\"] == \\\"user-456\\\"\\n    assert retrieved.session_metadata[\\\"region\\\"] == \\\"us-east-1\\\"\\n    assert retrieved.session_metadata[\\\"retention_profile\\\"] == \\\"standard\\\"\\n    assert retrieved.session_metadata[\\\"data_flags\\\"][\\\"pii\\\"] is True\\n    assert retrieved.session_metadata[\\\"custom_fields\\\"][\\\"department\\\"] == \\\"engineering\\\"\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_session_metadata_json_serialization():\\n    \\\"\\\"\\\"Test that session_metadata is properly serialized as JSON.\\\"\\\"\\\"\\n    session_id = f\\\"json_test_session_{uuid4()}\\\"\\n    metadata = {\\n        \\\"tenant_id\\\": \\\"tenant-json\\\",\\n        \\\"nested\\\": {\\\"key1\\\": \\\"value1\\\", \\\"key2\\\": [1, 2, 3]},\\n        \\\"array\\\": [\\\"item1\\\", \\\"item2\\\"],\\n        \\\"number\\\": 42,\\n        \\\"boolean\\\": True,\\n    }\\n\\n    message = Message(\\n        text=\\\"JSON serialization test\\\",\\n        sender=\\\"User\\\",\\n        sender_name=\\\"Test User\\\",\\n        session_id=session_id,\\n        session_metadata=metadata,\\n    )\\n    await astore_message(message)\\n\\n    # Retrieve and verify complex JSON structure\\n    retrieved_messages = await aget_messages(sender=\\\"User\\\", session_id=session_id)\\n    assert len(retrieved_messages) == 1\\n    retrieved_metadata = retrieved_messages[0].session_metadata\\n\\n    assert retrieved_metadata[\\\"tenant_id\\\"] == \\\"tenant-json\\\"\\n    assert retrieved_metadata[\\\"nested\\\"][\\\"key1\\\"] == \\\"value1\\\"\\n    assert retrieved_metadata[\\\"nested\\\"][\\\"key2\\\"] == [1, 2, 3]\\n    assert retrieved_metadata[\\\"array\\\"] == [\\\"item1\\\", \\\"item2\\\"]\\n    assert retrieved_metadata[\\\"number\\\"] == 42\\n    assert retrieved_metadata[\\\"boolean\\\"] is True\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_empty_session_metadata():\\n    \\\"\\\"\\\"Test storing message with empty dict as session_metadata.\\\"\\\"\\\"\\n    session_id = f\\\"empty_metadata_session_{uuid4()}\\\"\\n    message = Message(\\n        text=\\\"Empty metadata test\\\",\\n        sender=\\\"User\\\",\\n        sender_name=\\\"Test User\\\",\\n        session_id=session_id,\\n        session_metadata={},\\n    )\\n    await astore_message(message)\\n\\n    retrieved_messages = await aget_messages(sender=\\\"User\\\", session_id=session_id)\\n    assert len(retrieved_messages) == 1\\n    assert retrieved_messages[0].session_metadata == {}\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_session_metadata_retrieval():\\n    \\\"\\\"\\\"Test retrieving session_metadata from stored messages.\\\"\\\"\\\"\\n    session_id = f\\\"retrieval_metadata_session_{uuid4()}\\\"\\n\\n    # Create initial message\\n    initial_metadata = {\\\"tenant_id\\\": \\\"tenant-initial\\\", \\\"user_id\\\": \\\"user-initial\\\"}\\n    message = Message(\\n        text=\\\"Initial message\\\",\\n        sender=\\\"User\\\",\\n        sender_name=\\\"Test User\\\",\\n        session_id=session_id,\\n        session_metadata=initial_metadata,\\n    )\\n    await astore_message(message)\\n\\n    # Retrieve and verify\\n    messages = await aget_messages(sender=\\\"User\\\", session_id=session_id)\\n    assert len(messages) == 1\\n    assert messages[0].session_metadata == initial_metadata\\n\\n\\n@pytest.mark.usefixtures(\\\"client\\\")\\nasync def test_messageupdate_with_session_metadata(sample_session_metadata):\\n    \\\"\\\"\\\"Test MessageUpdate schema with session_metadata.\\\"\\\"\\\"\\n    from langflow.services.database.models.message.model import MessageUpdate\\n\\n    message_update = MessageUpdate(\\n        text=\\\"Updated text\\\",\\n        session_metadata=sample_session_metadata,\\n    )\\n    assert message_update.session_metadata == sample_session_metadata\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_settings_initialization_order.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"85a6f527bc6f0f1573907512dd31e2a3d064a5f65a8599b84d05af856ed7e346\",\"content\":\"\\\"\\\"\\\"Unit tests for settings initialization order.\\n\\nThese tests specifically verify that:\\n1. The check for pre-initialized settings works correctly\\n2. .env files can be loaded before settings initialization\\n3. The error message is helpful when settings are already initialized\\n4. CLI --env-file flag works with real subprocess startup\\n\\\"\\\"\\\"\\n\\nimport os\\nimport subprocess\\nimport sys\\nfrom unittest.mock import MagicMock\\n\\nimport pytest\\n\\n\\nclass TestSettingsInitializationOrder:\\n    \\\"\\\"\\\"Test the initialization order of settings service.\\\"\\\"\\\"\\n\\n    def test_is_settings_service_initialized_returns_false_initially(self):\\n        \\\"\\\"\\\"Test that is_settings_service_initialized returns False before initialization.\\\"\\\"\\\"\\n        from langflow.services.deps import is_settings_service_initialized\\n        from lfx.services.manager import get_service_manager\\n\\n        # Clear services\\n        service_manager = get_service_manager()\\n        service_manager.services.clear()\\n\\n        # Should be False initially\\n        assert is_settings_service_initialized() is False\\n\\n    def test_is_settings_service_initialized_returns_true_after_init(self):\\n        \\\"\\\"\\\"Test that is_settings_service_initialized returns True after initialization.\\\"\\\"\\\"\\n        from langflow.services.deps import get_settings_service, is_settings_service_initialized\\n        from lfx.services.manager import get_service_manager\\n\\n        # Clear services\\n        service_manager = get_service_manager()\\n        service_manager.services.clear()\\n\\n        # Initialize\\n        get_settings_service()\\n\\n        # Should be True now\\n        assert is_settings_service_initialized() is True\\n\\n    def test_is_settings_service_initialized_checks_service_manager(self):\\n        \\\"\\\"\\\"Test that the function checks the service manager directly.\\\"\\\"\\\"\\n        from langflow.services.deps import is_settings_service_initialized\\n        from langflow.services.schema import ServiceType\\n        from lfx.services.manager import get_service_manager\\n\\n        # Clear services\\n        service_manager = get_service_manager()\\n        service_manager.services.clear()\\n\\n        # Manually add a mock service to the manager\\n        mock_service = MagicMock()\\n        service_manager.services[ServiceType.SETTINGS_SERVICE] = mock_service\\n\\n        # Should return True\\n        assert is_settings_service_initialized() is True\\n\\n        # Clean up\\n        del service_manager.services[ServiceType.SETTINGS_SERVICE]\\n\\n    def test_dotenv_loading_before_settings_init(self, tmp_path):\\n        \\\"\\\"\\\"Test the complete flow: load .env, then initialize settings.\\\"\\\"\\\"\\n        from dotenv import load_dotenv\\n        from langflow.services.deps import get_settings_service, is_settings_service_initialized\\n        from lfx.services.manager import get_service_manager\\n\\n        # Clear services\\n        service_manager = get_service_manager()\\n        service_manager.services.clear()\\n\\n        # Create .env file\\n        env_file = tmp_path / \\\".env.test\\\"\\n        env_file.write_text(\\\"LANGFLOW_SAVE_DB_IN_CONFIG_DIR=true\\\\n\\\")\\n\\n        # Step 1: Check settings not initialized\\n        assert is_settings_service_initialized() is False\\n\\n        # Step 2: Load .env file\\n        load_dotenv(env_file, override=True)\\n\\n        # Step 3: Settings still not initialized\\n        assert is_settings_service_initialized() is False\\n\\n        # Step 4: Env var is available\\n        assert os.environ.get(\\\"LANGFLOW_SAVE_DB_IN_CONFIG_DIR\\\") == \\\"true\\\"\\n\\n        # Step 5: Initialize settings\\n        settings = get_settings_service()\\n\\n        # Step 6: Settings is initialized\\n        assert is_settings_service_initialized() is True\\n        assert settings is not None\\n\\n        # Clean up\\n        if \\\"LANGFLOW_SAVE_DB_IN_CONFIG_DIR\\\" in os.environ:\\n            del os.environ[\\\"LANGFLOW_SAVE_DB_IN_CONFIG_DIR\\\"]\\n\\n    def test_cli_check_pattern_success_case(self, tmp_path):\\n        \\\"\\\"\\\"Test the CLI check pattern when settings are NOT initialized (success case).\\\"\\\"\\\"\\n        from dotenv import load_dotenv\\n        from langflow.services.deps import is_settings_service_initialized\\n        from lfx.services.manager import get_service_manager\\n\\n        # Clear services to ensure settings are NOT initialized\\n        service_manager = get_service_manager()\\n        service_manager.services.clear()\\n\\n        env_file = tmp_path / \\\".env.cli\\\"\\n        env_file.write_text(\\\"LANGFLOW_DATABASE_URL=sqlite:///./test.db\\\\n\\\")\\n\\n        # Verify settings are not initialized\\n        assert is_settings_service_initialized() is False\\n\\n        # Simulate the CLI check pattern\\n        if env_file:\\n            # Check if settings service is already initialized\\n            if is_settings_service_initialized():\\n                pytest.fail(\\\"Settings should not be initialized yet\\\")\\n            else:\\n                # This is the success case - load the env file\\n                load_dotenv(env_file, override=True)\\n                assert os.environ.get(\\\"LANGFLOW_DATABASE_URL\\\") == \\\"sqlite:///./test.db\\\"\\n\\n        # Clean up\\n        if \\\"LANGFLOW_DATABASE_URL\\\" in os.environ:\\n            del os.environ[\\\"LANGFLOW_DATABASE_URL\\\"]\\n\\n    def test_cli_check_pattern_error_case(self, tmp_path):\\n        \\\"\\\"\\\"Test the CLI check pattern when settings ARE initialized (error case).\\\"\\\"\\\"\\n        from langflow.services.deps import get_settings_service, is_settings_service_initialized\\n        from lfx.services.manager import get_service_manager\\n\\n        # Clear services\\n        service_manager = get_service_manager()\\n        service_manager.services.clear()\\n\\n        # Initialize settings FIRST\\n        get_settings_service()\\n        assert is_settings_service_initialized() is True\\n\\n        env_file = tmp_path / \\\".env.cli\\\"\\n        env_file.write_text(\\\"LANGFLOW_DATABASE_URL=sqlite:///./test.db\\\\n\\\")\\n\\n        # Simulate the CLI check pattern\\n        if env_file:\\n            # Check if settings service is already initialized\\n            if is_settings_service_initialized():\\n                # This is the error case - settings already initialized\\n                # Should raise an error\\n                msg = \\\"Settings service is already initialized. Please do not set the env file via the CLI.\\\"\\n                with pytest.raises(\\n                    ValueError,\\n                    match=\\\"Settings service is already initialized\\\",\\n                ):\\n                    raise ValueError(msg)\\n            else:\\n                pytest.fail(\\\"Settings should be initialized, but check returned False\\\")\\n\\n    def test_error_message_when_settings_already_initialized(self, tmp_path):\\n        \\\"\\\"\\\"Test that we get a clear error when trying to load .env after settings init.\\\"\\\"\\\"\\n        from langflow.services.deps import get_settings_service, is_settings_service_initialized\\n        from lfx.services.manager import get_service_manager\\n\\n        # Clear services\\n        service_manager = get_service_manager()\\n        service_manager.services.clear()\\n\\n        # Initialize settings FIRST\\n        get_settings_service()\\n\\n        env_file = tmp_path / \\\".env.late\\\"\\n        env_file.write_text(\\\"LANGFLOW_DATABASE_URL=sqlite:///./test.db\\\\n\\\")\\n\\n        # Now try to use the CLI pattern\\n        if env_file:\\n            if is_settings_service_initialized():\\n                # Should detect that settings are already initialized\\n                error_msg = (\\n                    \\\"Settings service is already initialized. \\\"\\n                    \\\"This indicates potential race conditions with settings initialization. \\\"\\n                    \\\"Ensure the settings service is not created during module loading.\\\"\\n                )\\n                with pytest.raises(ValueError, match=\\\"Settings service is already initialized\\\"):\\n                    raise ValueError(error_msg)\\n            else:\\n                # Should not reach here\\n                pytest.fail(\\\"Should have detected initialized settings\\\")\\n\\n\\nclass TestSettingsServiceSingleton:\\n    \\\"\\\"\\\"Test that settings service maintains singleton behavior.\\\"\\\"\\\"\\n\\n    def test_settings_service_is_singleton(self):\\n        \\\"\\\"\\\"Test that multiple calls return the same instance.\\\"\\\"\\\"\\n        from langflow.services.deps import get_settings_service\\n\\n        service1 = get_settings_service()\\n        service2 = get_settings_service()\\n\\n        # Should be the exact same instance\\n        assert service1 is service2\\n\\n    def test_settings_service_singleton_across_imports(self):\\n        \\\"\\\"\\\"Test singleton behavior across different import paths.\\\"\\\"\\\"\\n        from langflow.services.deps import get_settings_service\\n        from langflow.services.schema import ServiceType\\n        from lfx.services.manager import get_service_manager\\n\\n        service1 = get_settings_service()\\n        service_manager = get_service_manager()\\n        service2 = service_manager.get(ServiceType.SETTINGS_SERVICE)\\n\\n        # Should be the same instance\\n        assert service1 is service2\\n\\n\\nclass TestCLISubprocessIntegration:\\n    \\\"\\\"\\\"Test CLI with subprocess to verify real-world startup with .env files.\\\"\\\"\\\"\\n\\n    @pytest.mark.skipif(sys.platform == \\\"win32\\\", reason=\\\"Shell script test not compatible with Windows\\\")\\n    def test_cli_env_file_values_actually_used(self, tmp_path):\\n        \\\"\\\"\\\"Test that values from --env-file are actually used by verifying server startup behavior.\\n\\n        This is a full integration test that briefly starts the server to verify env file loading.\\n        \\\"\\\"\\\"\\n        # Create an env file with a unique database path we can verify\\n        unique_db_name = f\\\"test_env_integration_{os.getpid()}.db\\\"\\n        db_path = tmp_path / unique_db_name\\n\\n        env_file = tmp_path / \\\"integration_test.env\\\"\\n        env_file.write_text(\\n            f\\\"\\\"\\\"\\nLANGFLOW_DATABASE_URL=sqlite:///{db_path}\\nLANGFLOW_AUTO_SAVING=false\\nLANGFLOW_AUTO_LOGIN=false\\nLANGFLOW_SUPERUSER=langflow\\nLANGFLOW_SUPERUSER_PASSWORD=test-superuser-password\\nLANGFLOW_LOG_LEVEL=ERROR\\n        \\\"\\\"\\\".strip()\\n        )\\n\\n        # Create a test script that starts langflow and checks if the database was created\\n        # at the location specified in the env file\\n        test_script = tmp_path / \\\"verify_startup.py\\\"\\n        test_script.write_text(\\n            f\\\"\\\"\\\"\\nimport sys\\nimport time\\nimport subprocess\\nimport signal\\nfrom pathlib import Path\\n\\n# Start langflow run with --env-file in background\\ndb_path = Path(r\\\"{db_path}\\\")\\nenv_file = Path(r\\\"{env_file}\\\")\\n\\n# Start the server\\nproc = subprocess.Popen(\\n    [\\n        sys.executable, \\\"-m\\\", \\\"langflow\\\", \\\"run\\\", \\\"--env-file\\\", str(env_file),\\n        \\\"--host\\\", \\\"127.0.0.1\\\", \\\"--port\\\", \\\"17860\\\", \\\"--backend-only\\\"\\n    ],\\n    stdout=subprocess.PIPE,\\n    stderr=subprocess.PIPE,\\n    text=True,\\n)\\n\\ntry:\\n    # Poll for database file with timeout (more reliable in CI)\\n    max_wait = 45  # Increased timeout for CI\\n    poll_interval = 2\\n    elapsed = 0\\n\\n    while elapsed < max_wait:\\n        # Check if process has died\\n        if proc.poll() is not None:\\n            stdout, stderr = proc.communicate()\\n            print(f\\\"ERROR: Server process died unexpectedly\\\")\\n            print(f\\\"STDOUT: {{stdout}}\\\")\\n            print(f\\\"STDERR: {{stderr}}\\\")\\n            sys.exit(1)\\n\\n        if db_path.exists():\\n            print(f\\\"SUCCESS: Database created at env file location: {{db_path}}\\\")\\n            sys.exit(0)\\n\\n        time.sleep(poll_interval)\\n        elapsed += poll_interval\\n\\n    # If we get here, database was not created\\n    print(f\\\"ERROR: Database NOT created at env file location: {{db_path}}\\\")\\n    print(f\\\"This means env file values were not used\\\")\\n    sys.exit(1)\\nfinally:\\n    # Clean up: kill the server if still running\\n    if proc.poll() is None:\\n        proc.terminate()\\n        try:\\n            proc.wait(timeout=5)\\n        except subprocess.TimeoutExpired:\\n            proc.kill()\\n        \\\"\\\"\\\".strip()\\n        )\\n\\n        # Run the integration test (increased timeout for CI)\\n        result = subprocess.run(  # noqa: S603\\n            [sys.executable, str(test_script)],\\n            check=False,\\n            capture_output=True,\\n            text=True,\\n            timeout=90,\\n        )\\n\\n        # Clean up database file if created\\n        if db_path.exists():\\n            db_path.unlink()\\n\\n        # Verify the test passed\\n        assert result.returncode == 0, (\\n            f\\\"Integration test failed - env file values not used\\\\nSTDOUT: {result.stdout}\\\\nSTDERR: {result.stderr}\\\"\\n        )\\n        assert \\\"SUCCESS\\\" in result.stdout, f\\\"Database not created at env file location\\\\n{result.stdout}\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_setup_superuser.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fd611f972a879356a551cfc735ff6c4fe788847d245e74ac8561d2759ef6d67a\",\"content\":\"import asyncio\\nfrom unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom langflow.services.auth.service import AuthService\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.utils import teardown_superuser\\nfrom lfx.services.settings.constants import (\\n    DEFAULT_SUPERUSER,\\n    DEFAULT_SUPERUSER_PASSWORD,\\n)\\nfrom sqlalchemy.exc import IntegrityError\\n\\n\\n@pytest.fixture\\ndef auth_service() -> AuthService:\\n    return AuthService(MagicMock())\\n\\n\\n# @patch(\\\"langflow.services.deps.get_session\\\")\\n# @patch(\\\"langflow.services.utils.create_super_user\\\")\\n# @patch(\\\"langflow.services.deps.get_settings_service\\\")\\n# # @patch(\\\"langflow.services.utils.verify_password\\\")\\n# def test_setup_superuser(\\n#     mock_get_session, mock_create_super_user, mock_get_settings_service\\n# ):\\n#     # Test when AUTO_LOGIN is True\\n#     calls = []\\n#     mock_settings_service = Mock()\\n#     mock_settings_service.auth_settings.AUTO_LOGIN = True\\n#     mock_settings_service.auth_settings.SUPERUSER = DEFAULT_SUPERUSER\\n#     mock_settings_service.auth_settings.SUPERUSER_PASSWORD = DEFAULT_SUPERUSER_PASSWORD\\n#     mock_get_settings_service.return_value = mock_settings_service\\n#     mock_session = Mock()\\n#     mock_session.query.return_value.filter.return_value.first.return_value = (\\n#         mock_session\\n#     )\\n#     # return value of get_session is a generator\\n#     mock_get_session.return_value = iter([mock_session, mock_session, mock_session])\\n#     setup_superuser(mock_settings_service, mock_session)\\n#     mock_session.query.assert_called_once_with(User)\\n#     # Set return value of filter to be None\\n#     mock_session.query.return_value.filter.return_value.first.return_value = None\\n#     actual_expr = mock_session.query.return_value.filter.call_args[0][0]\\n#     expected_expr = User.username == DEFAULT_SUPERUSER\\n\\n#     assert str(actual_expr) == str(expected_expr)\\n#     create_call = call(\\n#         db=mock_session, username=DEFAULT_SUPERUSER, password=DEFAULT_SUPERUSER_PASSWORD\\n#     )\\n#     calls.append(create_call)\\n#     # mock_create_super_user.assert_has_calls(calls)\\n#     assert 1 == mock_create_super_user.call_count\\n\\n#     def reset_mock_credentials():\\n#         mock_settings_service.auth_settings.SUPERUSER = DEFAULT_SUPERUSER\\n#         mock_settings_service.auth_settings.SUPERUSER_PASSWORD = (\\n#             DEFAULT_SUPERUSER_PASSWORD\\n#         )\\n\\n#     ADMIN_USER_NAME = \\\"admin_user\\\"\\n#     # Test when username and password are default\\n#     mock_settings_service.auth_settings = Mock()\\n#     mock_settings_service.auth_settings.AUTO_LOGIN = False\\n#     mock_settings_service.auth_settings.SUPERUSER = ADMIN_USER_NAME\\n#     mock_settings_service.auth_settings.SUPERUSER_PASSWORD = \\\"password\\\"\\n#     mock_settings_service.auth_settings.reset_credentials = Mock(\\n#         side_effect=reset_mock_credentials\\n#     )\\n\\n#     mock_get_settings_service.return_value = mock_settings_service\\n\\n#     setup_superuser(mock_settings_service, mock_session)\\n#     mock_session.query.assert_called_with(User)\\n#     actual_expr = mock_session.query.return_value.filter.call_args[0][0]\\n#     expected_expr = User.username == ADMIN_USER_NAME\\n\\n#     assert str(actual_expr) == str(expected_expr)\\n#     create_call = call(db=mock_session, username=ADMIN_USER_NAME, password=\\\"password\\\")\\n#     calls.append(create_call)\\n#     # mock_create_super_user.assert_has_calls(calls)\\n#     assert 2 == mock_create_super_user.call_count\\n#     # Test that superuser credentials are reset\\n#     mock_settings_service.auth_settings.reset_credentials.assert_called_once()\\n#     assert mock_settings_service.auth_settings.SUPERUSER != ADMIN_USER_NAME\\n#     assert mock_settings_service.auth_settings.SUPERUSER_PASSWORD != \\\"password\\\"\\n\\n#     # Test when superuser already exists\\n#     mock_settings_service.auth_settings.AUTO_LOGIN = False\\n#     mock_settings_service.auth_settings.SUPERUSER = ADMIN_USER_NAME\\n#     mock_settings_service.auth_settings.SUPERUSER_PASSWORD = \\\"password\\\"\\n#     mock_user = Mock()\\n#     mock_user.is_superuser = True\\n#     mock_session.query.return_value.filter.return_value.first.return_value = mock_user\\n#     setup_superuser(mock_settings_service, mock_session)\\n#     mock_session.query.assert_called_with(User)\\n#     actual_expr = mock_session.query.return_value.filter.call_args[0][0]\\n#     expected_expr = User.username == ADMIN_USER_NAME\\n\\n#     assert str(actual_expr) == str(expected_expr)\\n\\n\\n@patch(\\\"langflow.services.deps.get_settings_service\\\")\\n@patch(\\\"langflow.services.deps.get_session\\\")\\nasync def test_teardown_superuser_default_superuser(mock_get_session, mock_get_settings_service):\\n    mock_settings_service = MagicMock()\\n    mock_settings_service.auth_settings.AUTO_LOGIN = True\\n    mock_settings_service.auth_settings.SUPERUSER = DEFAULT_SUPERUSER\\n    mock_settings_service.auth_settings.SUPERUSER_PASSWORD = DEFAULT_SUPERUSER_PASSWORD\\n    mock_get_settings_service.return_value = mock_settings_service\\n\\n    mock_session = MagicMock()\\n    mock_user = MagicMock()\\n    mock_user.is_superuser = True\\n    mock_session.query.return_value.filter.return_value.first.return_value = mock_user\\n    mock_get_session.return_value = iter([mock_session])\\n\\n    await teardown_superuser(mock_settings_service, mock_session)\\n\\n    mock_session.query.assert_not_called()\\n\\n\\nasync def test_teardown_superuser_no_default_superuser():\\n    admin_user_name = \\\"admin_user\\\"\\n    mock_settings_service = MagicMock()\\n    mock_settings_service.auth_settings.AUTO_LOGIN = False\\n    mock_settings_service.auth_settings.SUPERUSER = admin_user_name\\n    mock_settings_service.auth_settings.SUPERUSER_PASSWORD = \\\"password\\\"  # noqa: S105\\n\\n    mock_session = AsyncMock(return_value=asyncio.Future())\\n    mock_user = MagicMock()\\n    mock_user.is_superuser = False\\n    mock_user.last_login_at = None\\n\\n    mock_result = MagicMock()\\n    mock_result.first.return_value = mock_user\\n    mock_session.exec.return_value = mock_result\\n\\n    await teardown_superuser(mock_settings_service, mock_session)\\n\\n    mock_session.delete.assert_not_awaited()\\n    mock_session.commit.assert_not_awaited()\\n\\n\\n@pytest.mark.asyncio\\nasync def test_create_super_user_race_condition(auth_service: AuthService):\\n    \\\"\\\"\\\"Test create_super_user handles race conditions gracefully when multiple workers try to create the same user.\\\"\\\"\\\"\\n    # Mock the database session\\n    mock_session = AsyncMock()\\n    mock_session.add = MagicMock()\\n\\n    # Create a mock user that will be \\\"created\\\" by the first worker\\n    mock_user = MagicMock(spec=User)\\n    mock_user.username = \\\"testuser\\\"\\n    mock_user.is_superuser = True\\n\\n    # Mock get_password_hash to return a fixed value\\n    mock_get_password_hash = MagicMock(return_value=\\\"hashed_password\\\")\\n\\n    # Set up the race condition scenario:\\n    # 1. First call to get_user_by_username returns None (user doesn't exist)\\n    # 2. commit() raises IntegrityError (simulating race condition)\\n    # 3. After rollback, second call to get_user_by_username returns the existing user\\n    mock_get_user_by_username = AsyncMock()\\n    mock_get_user_by_username.side_effect = [None, mock_user]  # None first, then existing user\\n\\n    mock_session.commit.side_effect = IntegrityError(\\\"statement\\\", \\\"params\\\", Exception(\\\"orig\\\"))\\n    with (\\n        patch(\\\"langflow.services.auth.service.get_user_by_username\\\", mock_get_user_by_username),\\n        patch.object(auth_service, \\\"get_password_hash\\\", mock_get_password_hash),\\n        patch(\\\"langflow.services.auth.service.User\\\") as mock_user_class,\\n    ):\\n        # Configure the User class mock to return our mock_user when instantiated\\n        mock_user_class.return_value = mock_user\\n\\n        result = await auth_service.create_super_user(\\\"testuser\\\", \\\"password\\\", mock_session)\\n\\n    # Verify that the function handled the race condition correctly\\n    assert result == mock_user\\n    assert mock_session.add.call_count == 1  # User was added to session\\n    assert mock_session.commit.call_count == 1  # Commit was attempted once (and failed)\\n    assert mock_session.rollback.call_count == 1  # Session was rolled back after IntegrityError\\n    assert mock_get_user_by_username.call_count == 2  # Called twice: initial check + after rollback\\n\\n\\n@pytest.mark.asyncio\\nasync def test_create_super_user_race_condition_no_user_found(auth_service: AuthService):\\n    \\\"\\\"\\\"Test that create_super_user re-raises exception if no user is found after IntegrityError.\\\"\\\"\\\"\\n    # Mock the database session\\n    mock_session = AsyncMock()\\n    mock_session.add = MagicMock()\\n\\n    # Mock get_user_by_username to always return None (even after rollback)\\n    mock_get_user_by_username = AsyncMock()\\n    mock_get_user_by_username.side_effect = [None, None]  # None for initial check and after rollback\\n\\n    # Mock other dependencies\\n    mock_get_password_hash = MagicMock(return_value=\\\"hashed_password\\\")\\n    mock_user = MagicMock(spec=User)\\n\\n    # Set up scenario where IntegrityError occurs but no user is found afterward\\n    integrity_error = IntegrityError(\\\"statement\\\", \\\"params\\\", Exception(\\\"orig\\\"))\\n    mock_session.commit.side_effect = integrity_error\\n\\n    with (\\n        patch(\\\"langflow.services.auth.service.get_user_by_username\\\", mock_get_user_by_username),\\n        patch.object(auth_service, \\\"get_password_hash\\\", mock_get_password_hash),\\n        patch(\\\"langflow.services.auth.service.User\\\", return_value=mock_user),\\n        pytest.raises(IntegrityError),\\n    ):\\n        await auth_service.create_super_user(\\\"testuser\\\", \\\"password\\\", mock_session)\\n\\n    # Verify rollback was called but exception was re-raised\\n    assert mock_session.rollback.call_count == 1\\n    assert mock_get_user_by_username.call_count == 2  # Initial + after rollback\\n\\n\\n@pytest.mark.asyncio\\nasync def test_create_super_user_concurrent_workers(auth_service: AuthService):\\n    \\\"\\\"\\\"Test multiple concurrent calls to create_super_user with the same username.\\\"\\\"\\\"\\n    # This would require a real database to properly test, but we can simulate\\n    # the behavior with mocks to verify the logic works correctly\\n\\n    mock_session1 = AsyncMock()\\n    mock_session2 = AsyncMock()\\n    mock_session1.add = MagicMock()\\n    mock_session2.add = MagicMock()\\n\\n    # Create mock users\\n    mock_user = MagicMock(spec=User)\\n    mock_user.username = \\\"admin\\\"\\n    mock_user.is_superuser = True\\n\\n    mock_get_user_by_username = AsyncMock()\\n\\n    # Worker 1 succeeds, Worker 2 gets IntegrityError then finds existing user\\n    mock_session1.commit.return_value = None  # Success\\n    mock_session2.commit.side_effect = IntegrityError(\\\"statement\\\", \\\"params\\\", Exception(\\\"orig\\\"))  # Race condition\\n\\n    # get_user_by_username returns None initially, then the created user for worker 2\\n    mock_get_user_by_username.side_effect = [None, None, mock_user]\\n\\n    with (\\n        patch(\\\"langflow.services.auth.service.get_user_by_username\\\", mock_get_user_by_username),\\n        patch.object(auth_service, \\\"get_password_hash\\\", return_value=\\\"hashed_password\\\"),\\n    ):\\n        # Simulate concurrent execution using asyncio.gather\\n        result1, result2 = await asyncio.gather(\\n            auth_service.create_super_user(\\\"admin\\\", \\\"password\\\", mock_session1),\\n            auth_service.create_super_user(\\\"admin\\\", \\\"password\\\", mock_session2),\\n        )\\n\\n    # Both workers should end up with a user (worker 1 creates, worker 2 finds existing)\\n    assert result1 is not None\\n    assert result2 == mock_user\\n\\n    # Worker 2 should have rolled back and fetched existing user\\n    assert mock_session2.rollback.call_count == 1\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_simple_agent_in_lfx_run.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"82f9b6df03caffb01a8055b112a84e039d2a33a4894e2a2cbacc2d2861450ae5\",\"content\":\"\\\"\\\"\\\"Tests for the simple agent workflow that can be executed via `lfx run`.\\n\\nThis module tests the agent workflow by:\\n1. Creating and validating the agent script\\n2. Testing component instantiation and configuration\\n3. Testing direct graph execution without CLI\\n4. Verifying the workflow works with langflow's dependencies\\n\\\"\\\"\\\"\\n\\nimport os\\nfrom pathlib import Path\\n\\nimport pytest\\nfrom lfx.utils.async_helpers import run_until_complete\\n\\nfrom tests.api_keys import has_api_key\\n\\n\\nclass TestAgentInLfxRun:\\n    \\\"\\\"\\\"Test the agent workflow that demonstrates lfx run functionality.\\\"\\\"\\\"\\n\\n    @pytest.fixture\\n    def simple_agent_script_content(self):\\n        \\\"\\\"\\\"The simple_agent.py script content for testing lfx run.\\\"\\\"\\\"\\n        return '''\\\"\\\"\\\"A simple agent flow example for Langflow.\\n\\nThis script demonstrates how to set up a conversational agent using Langflow's\\nAgent component with proper async handling.\\n\\nFeatures:\\n- Uses the new flattened component access (cp.AgentComponent instead of deep imports)\\n- Configures logging to 'langflow.log' at INFO level\\n- Creates an agent with OpenAI GPT model\\n- Connects ChatInput \u2192 Agent \u2192 ChatOutput\\n- Uses async get_graph() function for proper async handling\\n- Demonstrates the new async script loading pattern\\n\\nUsage:\\n    uv run lfx run simple_agent.py \\\"How are you?\\\"\\n\\\"\\\"\\\"\\n\\nimport os\\nfrom pathlib import Path\\n\\n# Using the new flattened component access\\nfrom lfx import components as cp\\nfrom lfx.graph import Graph\\nfrom lfx.log.logger import LogConfig\\n\\n\\nasync def get_graph() -> Graph:\\n    \\\"\\\"\\\"Create and return the graph with async component initialization.\\n\\n    This function properly handles async component initialization without\\n    blocking the module loading process. The script loader will detect this\\n    async function and handle it appropriately using run_until_complete.\\n\\n    Returns:\\n        Graph: The configured graph with ChatInput \u2192 Agent \u2192 ChatOutput flow\\n    \\\"\\\"\\\"\\n    log_config = LogConfig(\\n        log_level=\\\"INFO\\\",\\n        log_file=Path(\\\"langflow.log\\\"),\\n    )\\n\\n    # Showcase the new flattened component access - no need for deep imports!\\n    chat_input = cp.ChatInput()\\n    agent = cp.AgentComponent()\\n\\n    # Use URLComponent for web search capabilities\\n    url_component = cp.URLComponent()\\n\\n    # Properly handle async component initialization\\n    tools = await url_component.to_toolkit()\\n\\n    agent.set(\\n        model_name=\\\"gpt-4o-mini\\\",\\n        agent_llm=\\\"OpenAI\\\",\\n        api_key=os.getenv(\\\"OPENAI_API_KEY\\\"),\\n        input_value=chat_input.message_response,\\n        tools=tools,\\n    )\\n    chat_output = cp.ChatOutput().set(input_value=agent.message_response)\\n\\n    return Graph(chat_input, chat_output, log_config=log_config)\\n'''\\n\\n    @pytest.fixture\\n    def simple_agent_script_file(self):\\n        \\\"\\\"\\\"Get the path to the agent script in tests/data.\\\"\\\"\\\"\\n        # Use the script file we created in tests/data\\n        script_path = Path(__file__).parent.parent / \\\"data\\\" / \\\"simple_agent.py\\\"\\n        assert script_path.exists(), f\\\"Script file not found: {script_path}\\\"\\n\\n        yield script_path\\n\\n        # Cleanup any log file that might be created\\n        log_file = Path(\\\"langflow.log\\\")\\n        if log_file.exists():\\n            log_file.unlink(missing_ok=True)\\n\\n    def test_agent_script_structure_and_syntax(self, simple_agent_script_content):\\n        \\\"\\\"\\\"Test that the agent script has correct structure and valid syntax.\\\"\\\"\\\"\\n        import ast\\n\\n        # Test syntax is valid\\n        try:\\n            ast.parse(simple_agent_script_content)\\n        except SyntaxError as e:\\n            pytest.fail(f\\\"Script has invalid syntax: {e}\\\")\\n\\n        # Test key components are present\\n        assert \\\"from lfx import components as cp\\\" in simple_agent_script_content\\n        assert \\\"cp.ChatInput()\\\" in simple_agent_script_content\\n        assert \\\"cp.AgentComponent()\\\" in simple_agent_script_content\\n        assert \\\"cp.URLComponent()\\\" in simple_agent_script_content\\n        assert \\\"cp.ChatOutput()\\\" in simple_agent_script_content\\n        assert \\\"async def get_graph()\\\" in simple_agent_script_content\\n        assert \\\"await url_component.to_toolkit()\\\" in simple_agent_script_content\\n        assert 'model_name=\\\"gpt-4o-mini\\\"' in simple_agent_script_content\\n        assert 'agent_llm=\\\"OpenAI\\\"' in simple_agent_script_content\\n        assert \\\"return Graph(chat_input, chat_output\\\" in simple_agent_script_content\\n\\n    def test_agent_script_file_validation(self, simple_agent_script_file):\\n        \\\"\\\"\\\"Test that the agent script file exists and has valid content.\\\"\\\"\\\"\\n        # Since we don't have direct CLI access in langflow tests,\\n        # verify the script file exists and has correct content\\n        assert simple_agent_script_file.exists(), \\\"Script file should exist in tests/data\\\"\\n\\n        # Verify script content has expected structure\\n        content = simple_agent_script_file.read_text()\\n        assert \\\"from lfx import components as cp\\\" in content\\n        assert \\\"cp.AgentComponent()\\\" in content\\n        assert \\\"async def get_graph()\\\" in content\\n        assert \\\"return Graph(chat_input, chat_output\\\" in content\\n\\n    def test_agent_script_supports_formats(self, simple_agent_script_file):\\n        \\\"\\\"\\\"Test that the script supports logging configuration.\\\"\\\"\\\"\\n        # Verify script file exists and contains the expected structure\\n        assert simple_agent_script_file.exists()\\n\\n        # Test that the script mentions the format options in its docstring\\n        content = simple_agent_script_file.read_text()\\n        assert \\\"Usage:\\\" in content, \\\"Script should have usage documentation\\\"\\n\\n        # Verify the key logging components are present\\n        assert \\\"LogConfig\\\" in content, \\\"Script should configure logging properly\\\"\\n\\n    @pytest.mark.skipif(not has_api_key(\\\"OPENAI_API_KEY\\\"), reason=\\\"OPENAI_API_KEY required for full execution test\\\")\\n    def test_agent_script_api_configuration(self, simple_agent_script_file):\\n        \\\"\\\"\\\"Test that the script is properly configured for API usage.\\\"\\\"\\\"\\n        # Verify the script file exists and has API key configuration\\n        assert simple_agent_script_file.exists()\\n\\n        content = simple_agent_script_file.read_text()\\n\\n        # Should use environment variable for API key\\n        assert 'os.getenv(\\\"OPENAI_API_KEY\\\")' in content\\n\\n        # Should use the recommended model\\n        assert 'model_name=\\\"gpt-4o-mini\\\"' in content\\n\\n    async def test_agent_workflow_direct_execution(self):\\n        \\\"\\\"\\\"Test the agent workflow by executing the graph directly.\\\"\\\"\\\"\\n        # Import the components for direct execution\\n        try:\\n            from lfx.graph import Graph\\n            from lfx.log.logger import LogConfig\\n\\n            from lfx import components as cp\\n        except ImportError as e:\\n            pytest.skip(f\\\"LFX components not available: {e}\\\")\\n\\n        # Create the agent workflow\\n        log_config = LogConfig(\\n            log_level=\\\"INFO\\\",\\n            log_file=Path(\\\"langflow.log\\\"),\\n        )\\n\\n        chat_input = cp.ChatInput()\\n        agent = cp.AgentComponent()\\n        url_component = cp.URLComponent()\\n\\n        # Configure URL component for tools\\n        url_component.set(urls=[\\\"https://httpbin.org/json\\\"])\\n        tools = run_until_complete(url_component.to_toolkit())\\n\\n        # Configure agent\\n        agent.set(\\n            model_name=\\\"gpt-4o-mini\\\",\\n            agent_llm=\\\"OpenAI\\\",\\n            api_key=os.getenv(\\\"OPENAI_API_KEY\\\", \\\"test-key\\\"),  # Use test key if not available\\n            input_value=\\\"Hello, how are you?\\\",  # Direct input instead of chat_input.message_response\\n            tools=tools,\\n        )\\n\\n        chat_output = cp.ChatOutput()\\n\\n        # Create graph\\n        graph = Graph(chat_input, chat_output, log_config=log_config)\\n\\n        # Verify graph was created successfully\\n        assert graph is not None\\n        # The Graph object exists and has the expected structure\\n        assert str(graph), \\\"Graph should have string representation\\\"\\n\\n        # Cleanup log file\\n        log_file = Path(\\\"langflow.log\\\")\\n        if log_file.exists():\\n            log_file.unlink(missing_ok=True)\\n\\n    def test_flattened_component_access_pattern(self):\\n        \\\"\\\"\\\"Test that the flattened component access pattern works.\\\"\\\"\\\"\\n        try:\\n            from lfx import components as cp\\n        except ImportError as e:\\n            pytest.skip(f\\\"LFX components not available: {e}\\\")\\n\\n        # Test that all required components are accessible via flattened access\\n        components_to_test = [\\\"ChatInput\\\", \\\"AgentComponent\\\", \\\"URLComponent\\\", \\\"ChatOutput\\\"]\\n\\n        for component_name in components_to_test:\\n            assert hasattr(cp, component_name), f\\\"Component {component_name} not available via flattened access\\\"\\n\\n            # Test that we can instantiate each component\\n            component_class = getattr(cp, component_name)\\n            try:\\n                instance = component_class()\\n                assert instance is not None\\n            except Exception as e:\\n                pytest.fail(f\\\"Failed to instantiate {component_name}: {e}\\\")\\n\\n    async def test_url_component_to_toolkit_functionality(self):\\n        \\\"\\\"\\\"Test that URLComponent.to_toolkit() works properly.\\\"\\\"\\\"\\n        try:\\n            from lfx.utils.async_helpers import run_until_complete\\n\\n            from lfx import components as cp\\n        except ImportError as e:\\n            pytest.skip(f\\\"LFX components not available: {e}\\\")\\n\\n        url_component = cp.URLComponent()\\n\\n        # Configure with test URL\\n        url_component.set(urls=[\\\"https://httpbin.org/json\\\"])\\n\\n        # Test to_toolkit functionality\\n        tools = run_until_complete(url_component.to_toolkit())\\n\\n        # Should return some kind of tools object/list\\n        assert tools is not None\\n        # Should be iterable (list, tuple, or similar)\\n        assert hasattr(tools, \\\"__iter__\\\"), \\\"Tools should be iterable\\\"\\n\\n    def test_agent_configuration_workflow(self):\\n        \\\"\\\"\\\"Test agent configuration in the workflow.\\\"\\\"\\\"\\n        try:\\n            from lfx import components as cp\\n        except ImportError as e:\\n            pytest.skip(f\\\"LFX components not available: {e}\\\")\\n\\n        agent = cp.AgentComponent()\\n\\n        # Test the agent.set() configuration\\n        agent.set(\\n            model_name=\\\"gpt-4o-mini\\\",\\n            agent_llm=\\\"OpenAI\\\",\\n            api_key=\\\"test-key\\\",  # pragma: allowlist secret\\n            input_value=\\\"Test message\\\",\\n            tools=[],  # Empty tools for this test\\n        )\\n\\n        # Verify configuration was applied\\n        assert agent.model_name == \\\"gpt-4o-mini\\\"\\n        assert agent.agent_llm == \\\"OpenAI\\\"\\n        assert agent.api_key == \\\"test-key\\\"  # pragma: allowlist secret\\n        assert agent.input_value == \\\"Test message\\\"\\n\\n    def test_chat_output_chaining_pattern(self):\\n        \\\"\\\"\\\"Test the chat output chaining pattern.\\\"\\\"\\\"\\n        try:\\n            from lfx.schema.message import Message\\n\\n            from lfx import components as cp\\n        except ImportError as e:\\n            pytest.skip(f\\\"LFX components not available: {e}\\\")\\n\\n        chat_output = cp.ChatOutput()\\n\\n        # Test the chaining pattern: cp.ChatOutput().set(input_value=agent.message_response)\\n        mock_message = Message(text=\\\"Test response\\\")\\n        result = chat_output.set(input_value=mock_message)\\n\\n        # Should return the chat_output instance for chaining\\n        assert result is chat_output\\n        assert chat_output.input_value == mock_message\\n\\n    def test_logging_configuration(self):\\n        \\\"\\\"\\\"Test LogConfig setup for the workflow.\\\"\\\"\\\"\\n        try:\\n            from lfx.log.logger import LogConfig\\n        except ImportError as e:\\n            pytest.skip(f\\\"LFX logging not available: {e}\\\")\\n\\n        # Test LogConfig creation for the workflow\\n        log_config = LogConfig(\\n            log_level=\\\"INFO\\\",\\n            log_file=Path(\\\"langflow.log\\\"),\\n        )\\n\\n        assert log_config is not None\\n        # LogConfig may be a dict or object, verify it contains the expected data\\n        if isinstance(log_config, dict):\\n            assert log_config.get(\\\"log_level\\\") == \\\"INFO\\\"\\n            assert log_config.get(\\\"log_file\\\") == Path(\\\"langflow.log\\\")\\n        else:\\n            assert hasattr(log_config, \\\"log_level\\\") or hasattr(log_config, \\\"__dict__\\\")\\n\\n        # Cleanup\\n        log_file = Path(\\\"langflow.log\\\")\\n        if log_file.exists():\\n            log_file.unlink(missing_ok=True)\\n\\n    def test_environment_variable_handling(self):\\n        \\\"\\\"\\\"Test that environment variable handling works properly.\\\"\\\"\\\"\\n        # Test os.getenv(\\\"OPENAI_API_KEY\\\") pattern\\n        import os\\n\\n        # This should not raise an error even if the env var is not set\\n        api_key = os.getenv(\\\"OPENAI_API_KEY\\\")\\n\\n        # Should return None if not set, string if set\\n        assert api_key is None or isinstance(api_key, str)\\n\\n    @pytest.mark.skipif(not has_api_key(\\\"OPENAI_API_KEY\\\"), reason=\\\"OPENAI_API_KEY required for integration test\\\")\\n    def test_complete_workflow_integration(self):\\n        \\\"\\\"\\\"Test the complete agent workflow integration.\\\"\\\"\\\"\\n        try:\\n            from lfx.graph import Graph\\n            from lfx.log.logger import LogConfig\\n\\n            from lfx import components as cp\\n        except ImportError as e:\\n            pytest.skip(f\\\"LFX components not available: {e}\\\")\\n\\n        # Set up the complete workflow\\n        log_config = LogConfig(\\n            log_level=\\\"INFO\\\",\\n            log_file=Path(\\\"langflow.log\\\"),\\n        )\\n\\n        chat_input = cp.ChatInput()\\n        agent = cp.AgentComponent()\\n        url_component = cp.URLComponent()\\n\\n        # Configure URL component\\n        url_component.set(urls=[\\\"https://httpbin.org/json\\\"])\\n        tools = run_until_complete(url_component.to_toolkit())\\n\\n        # Configure agent with real API key\\n        agent.set(\\n            model_name=\\\"gpt-4o-mini\\\",\\n            agent_llm=\\\"OpenAI\\\",\\n            api_key=os.getenv(\\\"OPENAI_API_KEY\\\"),\\n            input_value=\\\"What is 2 + 2?\\\",  # Simple math question\\n            tools=tools,\\n        )\\n\\n        chat_output = cp.ChatOutput()\\n\\n        # Create and verify graph\\n        graph = Graph(chat_input, chat_output, log_config=log_config)\\n        assert graph is not None\\n\\n        # The actual execution would happen when the graph is run\\n        # For now, just verify the setup completed without errors\\n\\n        # Cleanup\\n        log_file = Path(\\\"langflow.log\\\")\\n        if log_file.exists():\\n            log_file.unlink(missing_ok=True)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_sso_models.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"7261a6fe784f6b4bebbbb5502fe74425d29566082504b6ba5ca49960ce44ba14\",\"content\":\"\\\"\\\"\\\"Tests for SSO plugin models against a real database.\\n\\nNo mocks: uses in-memory SQLite with foreign keys enabled to verify\\nCASCADE delete, unique constraints, and default values.\\n\\\"\\\"\\\"\\n\\nfrom datetime import datetime, timezone\\nfrom types import SimpleNamespace\\nfrom uuid import uuid4\\n\\nimport pytest\\nfrom langflow.services.database.models.auth import (\\n    SSOConfigCreate,\\n    SSOConfigRead,\\n    SSOConfigUpdate,\\n    decrypt_sso_client_secret,\\n    encrypt_sso_client_secret,\\n)\\nfrom langflow.services.database.models.auth.sso import (\\n    LegacyProviderSettings,\\n    OIDCProviderSettings,\\n    SSOConfig,\\n    SSOSettings,\\n    SSOUserProfile,\\n)\\nfrom langflow.services.database.models.user.model import User\\nfrom pydantic import SecretStr, ValidationError\\nfrom sqlalchemy import event, func, literal, update\\nfrom sqlalchemy.exc import IntegrityError, StatementError\\nfrom sqlalchemy.ext.asyncio import create_async_engine\\nfrom sqlalchemy.pool import StaticPool\\nfrom sqlmodel import SQLModel, select\\nfrom sqlmodel.ext.asyncio.session import AsyncSession\\n\\n# Placeholder for User.password in tests (not a real secret)\\n_TEST_PASSWORD = \\\"hashed\\\"  # noqa: S105\\n_TEST_PLAINTEXT_SECRET = \\\"oidc-client-secret\\\"  # noqa: S105  # pragma: allowlist secret\\n\\n\\n@pytest.fixture(name=\\\"sso_secret_settings\\\")\\ndef sso_secret_settings_fixture():\\n    return SimpleNamespace(\\n        auth_settings=SimpleNamespace(SECRET_KEY=SecretStr(\\\"unit-test-langflow-secret-key-material\\\"))\\n    )\\n\\n\\n@pytest.fixture(name=\\\"sso_db_engine\\\")\\ndef sso_db_engine():\\n    \\\"\\\"\\\"Async engine with SQLite and foreign keys enabled (real DB, no mocks).\\\"\\\"\\\"\\n    engine = create_async_engine(\\n        \\\"sqlite+aiosqlite://\\\",\\n        connect_args={\\\"check_same_thread\\\": False},\\n        poolclass=StaticPool,\\n    )\\n\\n    @event.listens_for(engine.sync_engine, \\\"connect\\\")\\n    def set_sqlite_pragma(dbapi_connection, connection_record):  # noqa: ARG001\\n        cursor = dbapi_connection.cursor()\\n        cursor.execute(\\\"PRAGMA foreign_keys=ON\\\")\\n        cursor.close()\\n\\n    return engine\\n\\n\\n@pytest.fixture(name=\\\"sso_async_session\\\")\\nasync def sso_async_session(sso_db_engine):\\n    \\\"\\\"\\\"Async session with SSO and User tables created (real DB).\\\"\\\"\\\"\\n    async with sso_db_engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.create_all)\\n    async with AsyncSession(sso_db_engine, expire_on_commit=False) as session:\\n        yield session\\n    async with sso_db_engine.begin() as conn:\\n        await conn.run_sync(SQLModel.metadata.drop_all)\\n    await sso_db_engine.dispose()\\n\\n\\n@pytest.mark.asyncio\\nclass TestSSOUserProfile:\\n    \\\"\\\"\\\"SSOUserProfile model tests against real database.\\\"\\\"\\\"\\n\\n    async def test_create_and_read_sso_user_profile(self, sso_async_session):\\n        \\\"\\\"\\\"Create and read SSOUserProfile records.\\\"\\\"\\\"\\n        user = User(username=\\\"sso_user\\\", password=_TEST_PASSWORD)\\n        sso_async_session.add(user)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(user)\\n\\n        profile = SSOUserProfile(\\n            user_id=user.id,\\n            sso_provider=\\\"oidc\\\",\\n            sso_user_id=\\\"sub-123\\\",\\n            email=\\\"user@example.com\\\",\\n            first_name=\\\"Deon\\\",\\n            last_name=\\\"Sanchez\\\",\\n            picture=\\\"https://idp.example.com/Deon.png\\\",\\n        )\\n        sso_async_session.add(profile)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(profile)\\n\\n        assert profile.id is not None\\n        assert profile.user_id == user.id\\n        assert profile.sso_provider == \\\"oidc\\\"\\n        assert profile.sso_user_id == \\\"sub-123\\\"\\n        assert profile.email == \\\"user@example.com\\\"\\n        assert profile.first_name == \\\"Deon\\\"\\n        assert profile.last_name == \\\"Sanchez\\\"\\n        assert profile.picture == \\\"https://idp.example.com/Deon.png\\\"\\n        assert profile.created_at is not None\\n        assert profile.updated_at is not None\\n\\n    async def test_identity_details_default_to_none(self, sso_async_session):\\n        user = User(username=\\\"legacy_sso_user\\\", password=_TEST_PASSWORD)\\n        sso_async_session.add(user)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(user)\\n\\n        profile = SSOUserProfile(\\n            user_id=user.id,\\n            sso_provider=\\\"oidc\\\",\\n            sso_user_id=\\\"legacy-subject\\\",\\n        )\\n        sso_async_session.add(profile)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(profile)\\n\\n        assert profile.first_name is None\\n        assert profile.last_name is None\\n        assert profile.picture is None\\n\\n    async def test_user_can_have_profiles_for_distinct_providers(self, sso_async_session):\\n        \\\"\\\"\\\"One user can have one SSO profile for each distinct provider.\\\"\\\"\\\"\\n        user = User(username=\\\"multi_provider_user\\\", password=_TEST_PASSWORD)\\n        sso_async_session.add(user)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(user)\\n\\n        profiles = [\\n            SSOUserProfile(user_id=user.id, sso_provider=\\\"oidc-primary\\\", sso_user_id=\\\"sub-1\\\"),\\n            SSOUserProfile(user_id=user.id, sso_provider=\\\"oidc-secondary\\\", sso_user_id=\\\"sub-2\\\"),\\n            SSOUserProfile(user_id=user.id, sso_provider=\\\"saml\\\", sso_user_id=\\\"sub-3\\\"),\\n        ]\\n        sso_async_session.add_all(profiles)\\n        await sso_async_session.commit()\\n\\n        result = await sso_async_session.exec(\\n            select(SSOUserProfile).where(SSOUserProfile.user_id == user.id).order_by(SSOUserProfile.sso_provider)\\n        )\\n        assert [profile.sso_provider for profile in result.all()] == [\\\"oidc-primary\\\", \\\"oidc-secondary\\\", \\\"saml\\\"]\\n\\n    async def test_composite_unique_user_id_sso_provider(self, sso_async_session):\\n        \\\"\\\"\\\"A user cannot have two SSO profiles for the same provider.\\\"\\\"\\\"\\n        user = User(username=\\\"unique_user_provider\\\", password=_TEST_PASSWORD)\\n        sso_async_session.add(user)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(user)\\n\\n        sso_async_session.add(SSOUserProfile(user_id=user.id, sso_provider=\\\"oidc-primary\\\", sso_user_id=\\\"sub-1\\\"))\\n        await sso_async_session.commit()\\n\\n        duplicate = SSOUserProfile(user_id=user.id, sso_provider=\\\"oidc-primary\\\", sso_user_id=\\\"sub-2\\\")\\n        sso_async_session.add(duplicate)\\n        with pytest.raises(IntegrityError, match=r\\\"UNIQUE constraint failed|unique constraint\\\"):\\n            await sso_async_session.commit()\\n\\n    async def test_composite_unique_sso_provider_sso_user_id(self, sso_async_session):\\n        \\\"\\\"\\\"Same (sso_provider, sso_user_id) cannot be used for two different users.\\\"\\\"\\\"\\n        user1 = User(username=\\\"user1\\\", password=_TEST_PASSWORD)\\n        user2 = User(username=\\\"user2\\\", password=_TEST_PASSWORD)\\n        sso_async_session.add(user1)\\n        sso_async_session.add(user2)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(user1)\\n        await sso_async_session.refresh(user2)\\n\\n        sso_async_session.add(SSOUserProfile(user_id=user1.id, sso_provider=\\\"oidc\\\", sso_user_id=\\\"sub-123\\\"))\\n        await sso_async_session.commit()\\n\\n        duplicate = SSOUserProfile(user_id=user2.id, sso_provider=\\\"oidc\\\", sso_user_id=\\\"sub-123\\\")\\n        sso_async_session.add(duplicate)\\n        with pytest.raises(IntegrityError, match=r\\\"UNIQUE constraint failed|unique constraint\\\"):\\n            await sso_async_session.commit()\\n\\n    async def test_cascade_delete_when_user_deleted(self, sso_async_session):\\n        \\\"\\\"\\\"Deleting user deletes associated SSOUserProfile (CASCADE).\\\"\\\"\\\"\\n        user = User(username=\\\"cascade_user\\\", password=_TEST_PASSWORD)\\n        sso_async_session.add(user)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(user)\\n\\n        profile = SSOUserProfile(user_id=user.id, sso_provider=\\\"oidc\\\", sso_user_id=\\\"sub-cascade\\\")\\n        sso_async_session.add(profile)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(profile)\\n        profile_id = profile.id\\n\\n        await sso_async_session.delete(user)\\n        await sso_async_session.commit()\\n\\n        result = await sso_async_session.exec(select(SSOUserProfile).where(SSOUserProfile.id == profile_id))\\n        assert result.first() is None\\n\\n    async def test_default_timestamps_set(self, sso_async_session):\\n        \\\"\\\"\\\"created_at and updated_at are set on create.\\\"\\\"\\\"\\n        user = User(username=\\\"ts_user\\\", password=_TEST_PASSWORD)\\n        sso_async_session.add(user)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(user)\\n\\n        profile = SSOUserProfile(user_id=user.id, sso_provider=\\\"oidc\\\", sso_user_id=\\\"sub-ts\\\")\\n        sso_async_session.add(profile)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(profile)\\n\\n        assert profile.created_at is not None\\n        assert profile.updated_at is not None\\n\\n\\n@pytest.mark.asyncio\\nclass TestSSOConfig:\\n    \\\"\\\"\\\"SSOConfig model tests against real database.\\\"\\\"\\\"\\n\\n    async def test_create_and_read_sso_config(self, sso_async_session, sso_secret_settings):\\n        \\\"\\\"\\\"Create and read SSOConfig.\\\"\\\"\\\"\\n        encrypted_secret = encrypt_sso_client_secret(_TEST_PLAINTEXT_SECRET, sso_secret_settings)\\n        config = SSOConfig(\\n            protocol=\\\"oidc\\\",\\n            display_name=\\\"Test OIDC\\\",\\n            client_secret_encrypted=encrypted_secret,\\n            provider_settings={\\n                \\\"protocol\\\": \\\"oidc\\\",\\n                \\\"client_id\\\": \\\"client-id\\\",\\n                \\\"discovery_url\\\": \\\"https://idp.example.com/.well-known/openid-configuration\\\",\\n                \\\"redirect_uri\\\": \\\"/api/v1/login/callback\\\",\\n                \\\"scopes\\\": \\\"openid email profile groups\\\",\\n                \\\"token_endpoint\\\": \\\"https://idp.example.com/token\\\",\\n                \\\"authorization_endpoint\\\": \\\"https://idp.example.com/authorize\\\",\\n                \\\"jwks_uri\\\": \\\"https://idp.example.com/jwks\\\",\\n                \\\"issuer\\\": \\\"https://idp.example.com\\\",\\n            },\\n        )\\n        sso_async_session.add(config)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(config)\\n\\n        assert config.id is not None\\n        assert config.protocol == \\\"oidc\\\"\\n        assert config.display_name == \\\"Test OIDC\\\"\\n        assert config.slug.startswith(\\\"sso-\\\")\\n        assert isinstance(config.provider_settings, OIDCProviderSettings)\\n        assert config.provider_settings.client_id == \\\"client-id\\\"\\n        assert config.provider_settings.discovery_url == \\\"https://idp.example.com/.well-known/openid-configuration\\\"\\n        assert config.provider_settings.scopes == \\\"openid email profile groups\\\"\\n        assert config.client_secret_encrypted == encrypted_secret\\n        assert config.enabled is False\\n        assert config.sort_order == 0\\n        assert config.email_claim == \\\"email\\\"\\n        assert config.username_claim == \\\"preferred_username\\\"\\n        assert config.user_id_claim == \\\"sub\\\"\\n        assert config.created_at is not None\\n        assert config.updated_at is not None\\n        assert config.updated_by is None\\n\\n    async def test_default_values(self, sso_async_session):\\n        \\\"\\\"\\\"Default values are applied when not specified.\\\"\\\"\\\"\\n        config = SSOConfig(protocol=\\\"oidc\\\", display_name=\\\"Default Test\\\")\\n        sso_async_session.add(config)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(config)\\n\\n        assert config.protocol == \\\"oidc\\\"\\n        assert config.provider_settings == OIDCProviderSettings()\\n        assert config.enabled is False\\n        assert config.sort_order == 0\\n        assert config.email_claim == \\\"email\\\"\\n        assert config.username_claim == \\\"preferred_username\\\"\\n        assert config.user_id_claim == \\\"sub\\\"\\n        assert config.created_by is None\\n        assert config.updated_by is None\\n\\n    async def test_multiple_enabled_configs_have_deterministic_sort_order_and_one_instance_policy(\\n        self, sso_async_session, sso_secret_settings\\n    ):\\n        settings = SSOSettings(enforce_sso=True)\\n        encrypted_secret = encrypt_sso_client_secret(_TEST_PLAINTEXT_SECRET, sso_secret_settings)\\n        provider_settings = OIDCProviderSettings(\\n            client_id=\\\"client-id\\\",\\n            discovery_url=\\\"https://idp.example.com/.well-known/openid-configuration\\\",\\n        )\\n        configs = [\\n            SSOConfig(\\n                display_name=\\\"Second\\\",\\n                enabled=True,\\n                sort_order=20,\\n                client_secret_encrypted=encrypted_secret,\\n                provider_settings=provider_settings,\\n            ),\\n            SSOConfig(\\n                display_name=\\\"First\\\",\\n                enabled=True,\\n                sort_order=10,\\n                client_secret_encrypted=encrypted_secret,\\n                provider_settings=provider_settings,\\n            ),\\n        ]\\n        sso_async_session.add_all([settings, *configs])\\n        await sso_async_session.commit()\\n\\n        result = await sso_async_session.exec(\\n            select(SSOConfig).where(SSOConfig.enabled.is_(True)).order_by(SSOConfig.sort_order, SSOConfig.id)\\n        )\\n        assert [config.display_name for config in result.all()] == [\\\"First\\\", \\\"Second\\\"]\\n        assert (await sso_async_session.get(SSOSettings, 1)).enforce_sso is True\\n        assert \\\"enforce_sso\\\" not in SSOConfig.__table__.columns\\n\\n        sso_async_session.add(SSOSettings(id=2, enforce_sso=False))\\n        with pytest.raises(IntegrityError, match=r\\\"CHECK constraint failed|check constraint\\\"):\\n            await sso_async_session.commit()\\n\\n    async def test_updated_at_and_updated_by_are_maintained(self, sso_async_session):\\n        updater = User(username=\\\"sso_config_updater\\\", password=_TEST_PASSWORD)\\n        config = SSOConfig(display_name=\\\"Audited connection\\\")\\n        sso_async_session.add_all([updater, config])\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(updater)\\n        await sso_async_session.refresh(config)\\n\\n        old_timestamp = datetime(2000, 1, 1, tzinfo=timezone.utc)\\n        config.updated_at = old_timestamp\\n        await sso_async_session.commit()\\n\\n        config.display_name = \\\"Updated connection\\\"\\n        config.updated_by = updater.id\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(config)\\n        assert config.updated_at.replace(tzinfo=timezone.utc) > old_timestamp\\n        assert config.updated_by == updater.id\\n\\n        await sso_async_session.delete(updater)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(config)\\n        assert config.updated_by is None\\n\\n    async def test_client_secret_is_stored_as_ciphertext_envelope(self, sso_async_session, sso_secret_settings):\\n        encrypted = encrypt_sso_client_secret(_TEST_PLAINTEXT_SECRET, sso_secret_settings)\\n        config = SSOConfig(\\n            display_name=\\\"Encrypted secret connection\\\",\\n            client_secret_encrypted=encrypted,\\n        )\\n        sso_async_session.add(config)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(config)\\n\\n        stored_value = config.client_secret_encrypted\\n        assert stored_value is not None\\n        assert _TEST_PLAINTEXT_SECRET not in stored_value\\n        assert decrypt_sso_client_secret(stored_value, sso_secret_settings) == _TEST_PLAINTEXT_SECRET\\n\\n    async def test_client_secret_rejects_plaintext_model_writes(self):\\n        with pytest.raises(ValueError, match=\\\"versioned SSO secret envelope\\\"):\\n            SSOConfig(\\n                display_name=\\\"Plaintext secret connection\\\",\\n                client_secret_encrypted=_TEST_PLAINTEXT_SECRET,\\n            )\\n\\n    async def test_client_secret_rejects_plaintext_core_updates(self, sso_async_session):\\n        config = SSOConfig(display_name=\\\"Core update connection\\\")\\n        sso_async_session.add(config)\\n        await sso_async_session.commit()\\n\\n        with pytest.raises(StatementError, match=\\\"versioned SSO secret envelope\\\"):\\n            await sso_async_session.execute(\\n                update(SSOConfig)\\n                .where(SSOConfig.id == config.id)\\n                .values(client_secret_encrypted=_TEST_PLAINTEXT_SECRET)\\n            )\\n\\n    async def test_client_secret_rejects_plaintext_core_expression_updates(self, sso_async_session):\\n        config = SSOConfig(display_name=\\\"Core expression update connection\\\")\\n        sso_async_session.add(config)\\n        await sso_async_session.commit()\\n\\n        with pytest.raises(IntegrityError, match=r\\\"client_secret_envelope|CHECK constraint failed\\\"):\\n            await sso_async_session.execute(\\n                update(SSOConfig)\\n                .where(SSOConfig.id == config.id)\\n                .values(client_secret_encrypted=literal(_TEST_PLAINTEXT_SECRET))\\n            )\\n\\n    async def test_client_secret_is_excluded_from_serialization_and_repr(self, sso_secret_settings):\\n        encrypted = encrypt_sso_client_secret(_TEST_PLAINTEXT_SECRET, sso_secret_settings)\\n        config = SSOConfig(display_name=\\\"Safe output\\\", client_secret_encrypted=encrypted)\\n\\n        assert \\\"client_secret_encrypted\\\" not in config.model_dump()\\n        assert encrypted not in config.model_dump_json()\\n        assert encrypted not in repr(config)\\n\\n        read_config = SSOConfigRead.model_validate(config)\\n        assert \\\"client_secret_encrypted\\\" not in SSOConfigRead.model_fields\\n        assert encrypted not in read_config.model_dump_json()\\n\\n    async def test_create_schema_accepts_plaintext_secret_and_encrypts_for_persistence(self, sso_secret_settings):\\n        create = SSOConfigCreate(\\n            display_name=\\\"Created safely\\\",\\n            client_secret=SecretStr(_TEST_PLAINTEXT_SECRET),\\n        )\\n\\n        assert \\\"client_secret\\\" not in create.model_dump()\\n        config = create.to_model(sso_secret_settings)\\n        assert config.client_secret_encrypted is not None\\n        assert config.client_secret_encrypted != _TEST_PLAINTEXT_SECRET\\n        assert decrypt_sso_client_secret(config.client_secret_encrypted, sso_secret_settings) == _TEST_PLAINTEXT_SECRET\\n\\n    async def test_update_schema_encrypts_secret_and_validates_merged_enabled_state(self, sso_secret_settings):\\n        config = SSOConfig(display_name=\\\"Update safely\\\")\\n        update_schema = SSOConfigUpdate(\\n            enabled=True,\\n            client_secret=SecretStr(_TEST_PLAINTEXT_SECRET),\\n            provider_settings=OIDCProviderSettings(\\n                client_id=\\\"client-id\\\",\\n                discovery_url=\\\"https://idp.example.com/.well-known/openid-configuration\\\",\\n            ),\\n        )\\n\\n        update_schema.apply_to(config, sso_secret_settings)\\n\\n        assert config.enabled is True\\n        assert config.client_secret_encrypted is not None\\n        assert decrypt_sso_client_secret(config.client_secret_encrypted, sso_secret_settings) == _TEST_PLAINTEXT_SECRET\\n\\n    async def test_update_schema_preserves_actor_when_omitted_and_updates_explicit_actor(self):\\n        original_actor_id = uuid4()\\n        config = SSOConfig(display_name=\\\"Actor attribution\\\", updated_by=original_actor_id)\\n\\n        SSOConfigUpdate(display_name=\\\"No new actor\\\").apply_to(config)\\n        assert config.updated_by == original_actor_id\\n\\n        replacement_actor_id = uuid4()\\n        SSOConfigUpdate(display_name=\\\"Replacement actor\\\").apply_to(config, actor_id=replacement_actor_id)\\n        assert config.updated_by == replacement_actor_id\\n\\n    async def test_update_schema_atomically_converts_legacy_config_to_oidc(self, sso_secret_settings):\\n        config = SSOConfig(\\n            display_name=\\\"Legacy connection\\\",\\n            protocol=\\\"saml\\\",\\n            provider_settings=LegacyProviderSettings(protocol=\\\"saml\\\"),\\n        )\\n        oidc_settings = OIDCProviderSettings(\\n            client_id=\\\"client-id\\\",\\n            discovery_url=\\\"https://idp.example.com/.well-known/openid-configuration\\\",\\n        )\\n\\n        SSOConfigUpdate(\\n            protocol=\\\"oidc\\\",\\n            enabled=True,\\n            client_secret=SecretStr(_TEST_PLAINTEXT_SECRET),\\n            provider_settings=oidc_settings,\\n        ).apply_to(config, sso_secret_settings)\\n\\n        assert config.protocol == \\\"oidc\\\"\\n        assert config.provider_settings == oidc_settings\\n        assert config.enabled is True\\n        assert decrypt_sso_client_secret(config.client_secret_encrypted, sso_secret_settings) == _TEST_PLAINTEXT_SECRET\\n\\n    async def test_incomplete_config_cannot_be_enabled(self, sso_async_session):\\n        with pytest.raises(ValueError, match=\\\"require a client_id\\\"):\\n            SSOConfig(display_name=\\\"Incomplete\\\", enabled=True)\\n\\n        config = SSOConfig(display_name=\\\"Initially disabled\\\")\\n        sso_async_session.add(config)\\n        await sso_async_session.commit()\\n\\n        with pytest.raises(ValueError, match=\\\"require a client_id\\\"):\\n            config.enabled = True\\n        assert config.enabled is False\\n\\n    async def test_create_schema_rejects_incomplete_enabled_config(self):\\n        with pytest.raises(ValidationError, match=\\\"require a client_id\\\"):\\n            SSOConfigCreate(display_name=\\\"Incomplete\\\", enabled=True)\\n\\n    async def test_provider_credentials_reject_blank_values_and_non_http_urls(self):\\n        with pytest.raises(ValidationError, match=\\\"client_id must not be blank\\\"):\\n            OIDCProviderSettings(client_id=\\\" \\\\t \\\")\\n\\n        for field_name in (\\\"discovery_url\\\", \\\"token_endpoint\\\", \\\"authorization_endpoint\\\", \\\"jwks_uri\\\", \\\"issuer\\\"):\\n            with pytest.raises(ValidationError, match=\\\"absolute HTTP\\\"):\\n                OIDCProviderSettings(**{field_name: \\\"file:///etc/passwd\\\"})\\n\\n        with pytest.raises(ValidationError, match=\\\"client secret must not be blank\\\"):\\n            SSOConfigCreate(display_name=\\\"Blank secret\\\", client_secret=SecretStr(\\\"  \\\"))\\n        with pytest.raises(ValidationError, match=\\\"client secret must not be blank\\\"):\\n            SSOConfigUpdate(client_secret=SecretStr(\\\"\\\"))\\n\\n    @pytest.mark.parametrize(\\n        \\\"malformed_url\\\",\\n        [\\n            \\\"http:// example.com\\\",\\n            \\\"http://example.com:bad\\\",\\n            \\\"https://exa mple.com\\\",\\n            \\\"https://%zz\\\",\\n            \\\"https://example.com/%zz\\\",\\n            \\\"http:///etc/passwd\\\",\\n        ],\\n    )\\n    async def test_provider_credentials_reject_malformed_http_urls(self, malformed_url):\\n        with pytest.raises(ValidationError, match=\\\"absolute HTTP\\\"):\\n            OIDCProviderSettings(discovery_url=malformed_url)\\n\\n    async def test_external_schemas_do_not_accept_audit_actor_fields(self, sso_secret_settings):\\n        actor_id = uuid4()\\n        with pytest.raises(ValidationError, match=\\\"created_by\\\"):\\n            SSOConfigCreate(display_name=\\\"Caller attributed\\\", created_by=actor_id)\\n        with pytest.raises(ValidationError, match=\\\"updated_by\\\"):\\n            SSOConfigUpdate(updated_by=actor_id)\\n\\n        config = SSOConfigCreate(display_name=\\\"Server attributed\\\").to_model(\\n            sso_secret_settings,\\n            actor_id=actor_id,\\n        )\\n        assert config.created_by == actor_id\\n        assert config.updated_by == actor_id\\n\\n        new_actor_id = uuid4()\\n        SSOConfigUpdate(display_name=\\\"Updated\\\").apply_to(\\n            config,\\n            sso_secret_settings,\\n            actor_id=new_actor_id,\\n        )\\n        assert config.updated_by == new_actor_id\\n\\n    async def test_standard_model_validation_is_safe_and_strict(self):\\n        config = SSOConfig.model_validate({\\\"display_name\\\": \\\"Validated\\\"})\\n        assert config.display_name == \\\"Validated\\\"\\n        assert config.enabled is False\\n\\n        with pytest.raises(ValidationError, match=\\\"display_name\\\"):\\n            SSOConfig.model_validate({})\\n        with pytest.raises(ValidationError, match=\\\"valid string\\\"):\\n            SSOConfig.model_validate({\\\"display_name\\\": 123})\\n        with pytest.raises(ValidationError, match=\\\"extra_forbidden\\\"):\\n            SSOConfig.model_validate(\\n                {\\n                    \\\"display_name\\\": \\\"Malformed\\\",\\n                    \\\"provider_settings\\\": {\\\"protocol\\\": \\\"oidc\\\", \\\"unexpected\\\": True},\\n                }\\n            )\\n\\n    async def test_display_name_update_preserves_profile_connection(self, sso_async_session):\\n        \\\"\\\"\\\"Changing the label does not change the profile's stable connection identity.\\\"\\\"\\\"\\n        user = User(username=\\\"stable_connection_user\\\", password=_TEST_PASSWORD)\\n        config = SSOConfig(display_name=\\\"Original connection name\\\")\\n        sso_async_session.add_all([user, config])\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(user)\\n        await sso_async_session.refresh(config)\\n\\n        original_slug = config.slug\\n        profile = SSOUserProfile(\\n            user_id=user.id,\\n            sso_provider=original_slug,\\n            sso_user_id=\\\"stable-subject\\\",\\n        )\\n        sso_async_session.add(profile)\\n        await sso_async_session.commit()\\n\\n        config.display_name = \\\"Renamed connection\\\"\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(profile)\\n\\n        result = await sso_async_session.exec(select(SSOConfig).where(SSOConfig.slug == profile.sso_provider))\\n        resolved_config = result.one()\\n        assert config.slug == original_slug\\n        assert profile.sso_provider == original_slug\\n        assert resolved_config.display_name == \\\"Renamed connection\\\"\\n\\n    async def test_slug_is_url_safe_unique_and_immutable(self, sso_async_session):\\n        config = SSOConfig(display_name=\\\"Primary connection\\\")\\n        sso_async_session.add(config)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(config)\\n\\n        assert config.slug.replace(\\\"-\\\", \\\"\\\").isalnum()\\n        assert config.slug == config.slug.lower()\\n\\n        config.slug = \\\"sso-replacement\\\"\\n        with pytest.raises(ValueError, match=\\\"immutable after insert\\\"):\\n            await sso_async_session.commit()\\n\\n    async def test_core_update_cannot_enable_an_incomplete_config(self, sso_async_session):\\n        config = SSOConfig(display_name=\\\"Core incomplete\\\")\\n        sso_async_session.add(config)\\n        await sso_async_session.commit()\\n\\n        with pytest.raises(IntegrityError, match=r\\\"enabled_complete|CHECK constraint failed\\\"):\\n            await sso_async_session.execute(update(SSOConfig).where(SSOConfig.id == config.id).values(enabled=True))\\n\\n    async def test_core_expression_cannot_install_invalid_url_on_enabled_config(\\n        self, sso_async_session, sso_secret_settings\\n    ):\\n        encrypted_secret = encrypt_sso_client_secret(_TEST_PLAINTEXT_SECRET, sso_secret_settings)\\n        config = SSOConfig(\\n            display_name=\\\"Core URL expression\\\",\\n            enabled=True,\\n            client_secret_encrypted=encrypted_secret,\\n            provider_settings=OIDCProviderSettings(\\n                client_id=\\\"client-id\\\",\\n                discovery_url=\\\"https://idp.example.com/.well-known/openid-configuration\\\",\\n            ),\\n        )\\n        sso_async_session.add(config)\\n        await sso_async_session.commit()\\n\\n        with pytest.raises(IntegrityError, match=r\\\"enabled_complete|CHECK constraint failed\\\"):\\n            await sso_async_session.execute(\\n                update(SSOConfig)\\n                .where(SSOConfig.id == config.id)\\n                .values(\\n                    provider_settings=func.json_set(\\n                        SSOConfig.provider_settings,\\n                        \\\"$.discovery_url\\\",\\n                        \\\"http:///etc/passwd\\\",\\n                    )\\n                )\\n            )\\n\\n    async def test_core_update_cannot_change_protocol(self, sso_async_session):\\n        config = SSOConfig(display_name=\\\"Core protocol\\\")\\n        sso_async_session.add(config)\\n        await sso_async_session.commit()\\n\\n        with pytest.raises(IntegrityError, match=r\\\"protocol_consistency|CHECK constraint failed\\\"):\\n            await sso_async_session.execute(update(SSOConfig).where(SSOConfig.id == config.id).values(protocol=\\\"saml\\\"))\\n\\n    async def test_core_update_cannot_change_slug(self, sso_async_session):\\n        config = SSOConfig(display_name=\\\"Core slug\\\")\\n        sso_async_session.add(config)\\n        await sso_async_session.commit()\\n\\n        with pytest.raises(IntegrityError, match=\\\"immutable after insert\\\"):\\n            await sso_async_session.execute(\\n                update(SSOConfig).where(SSOConfig.id == config.id).values(slug=\\\"sso-replacement\\\")\\n            )\\n\\n    async def test_duplicate_slug_is_rejected(self, sso_async_session):\\n        slug = \\\"sso-fixed-connection\\\"\\n        sso_async_session.add(SSOConfig(slug=slug, display_name=\\\"First connection\\\"))\\n        await sso_async_session.commit()\\n\\n        sso_async_session.add(SSOConfig(slug=slug, display_name=\\\"Second connection\\\"))\\n        with pytest.raises(IntegrityError, match=r\\\"UNIQUE constraint failed|unique constraint\\\"):\\n            await sso_async_session.commit()\\n\\n    async def test_invalid_slug_is_rejected(self):\\n        with pytest.raises(ValueError, match=\\\"lowercase letters\\\"):\\n            SSOConfig(slug=\\\"Not URL safe!\\\", display_name=\\\"Invalid\\\")\\n\\n    async def test_invalid_slug_assignment_is_rejected_before_insert(self):\\n        config = SSOConfig(display_name=\\\"Pending\\\")\\n        with pytest.raises(ValueError, match=\\\"lowercase letters\\\"):\\n            config.slug = \\\"INVALID!\\\"\\n\\n    async def test_provider_settings_reject_protocol_mismatch(self):\\n        with pytest.raises(ValueError, match=\\\"does not match\\\"):\\n            SSOConfig(\\n                protocol=\\\"saml\\\",\\n                display_name=\\\"Invalid\\\",\\n                provider_settings={\\\"protocol\\\": \\\"oidc\\\"},\\n            )\\n\\n    @pytest.mark.parametrize(\\\"protocol\\\", [\\\"saml\\\", \\\"ldap\\\"])\\n    async def test_disabled_legacy_provider_settings_can_load(self, protocol, sso_async_session):\\n        config = SSOConfig(\\n            protocol=protocol,\\n            display_name=f\\\"Legacy {protocol}\\\",\\n            enabled=False,\\n            provider_settings={\\\"protocol\\\": protocol, \\\"client_id\\\": \\\"legacy-client\\\"},\\n        )\\n        sso_async_session.add(config)\\n        await sso_async_session.commit()\\n        await sso_async_session.refresh(config)\\n\\n        assert config.protocol == protocol\\n        assert config.provider_settings.protocol == protocol\\n        assert config.provider_settings.client_id == \\\"legacy-client\\\"\\n\\n    @pytest.mark.parametrize(\\\"protocol\\\", [\\\"saml\\\", \\\"ldap\\\"])\\n    async def test_legacy_provider_settings_cannot_be_enabled(self, protocol):\\n        with pytest.raises(ValueError, match=\\\"Only OIDC configurations can be enabled\\\"):\\n            SSOConfig(\\n                protocol=protocol,\\n                display_name=f\\\"Legacy {protocol}\\\",\\n                enabled=True,\\n                provider_settings={\\\"protocol\\\": protocol},\\n            )\\n\\n    @pytest.mark.parametrize(\\\"protocol\\\", [\\\"saml\\\", \\\"ldap\\\"])\\n    async def test_disabled_legacy_provider_settings_cannot_be_enabled_by_assignment(self, protocol):\\n        config = SSOConfig(\\n            protocol=protocol,\\n            display_name=f\\\"Legacy {protocol}\\\",\\n            enabled=False,\\n            provider_settings={\\\"protocol\\\": protocol},\\n        )\\n\\n        with pytest.raises(ValueError, match=\\\"Only OIDC configurations can be enabled\\\"):\\n            config.enabled = True\\n\\n        assert config.enabled is False\\n\\n    @pytest.mark.parametrize(\\\"protocol\\\", [\\\"saml\\\", \\\"ldap\\\"])\\n    async def test_database_preserves_enabled_legacy_provider_settings(self, protocol, sso_async_session):\\n        config_id = uuid4()\\n        timestamp = datetime.now(timezone.utc)\\n\\n        await sso_async_session.execute(\\n            SSOConfig.__table__.insert().values(\\n                id=config_id,\\n                slug=f\\\"sso-legacy-{protocol}-{uuid4().hex}\\\",\\n                display_name=f\\\"Legacy enabled {protocol}\\\",\\n                protocol=protocol,\\n                enabled=True,\\n                sort_order=0,\\n                client_secret_encrypted=None,\\n                provider_settings={\\\"protocol\\\": protocol},\\n                email_claim=\\\"email\\\",\\n                username_claim=\\\"preferred_username\\\",\\n                user_id_claim=\\\"sub\\\",\\n                created_at=timestamp,\\n                updated_at=timestamp,\\n            )\\n        )\\n        await sso_async_session.commit()\\n\\n        config = await sso_async_session.get(SSOConfig, config_id)\\n        assert config is not None\\n        assert config.enabled is True\\n        assert config.provider_settings.protocol == protocol\\n\\n    async def test_protocol_assignment_rejects_mismatch_with_provider_settings(self):\\n        config = SSOConfig(protocol=\\\"oidc\\\", display_name=\\\"Valid\\\")\\n        with pytest.raises(ValueError, match=\\\"does not match\\\"):\\n            config.protocol = \\\"saml\\\"\\n\\n    async def test_provider_settings_assignment_rejects_protocol_mismatch(self):\\n        config = SSOConfig(protocol=\\\"oidc\\\", display_name=\\\"Valid\\\")\\n        # Bypass validates so we can exercise the provider_settings assignment check.\\n        config.__dict__[\\\"protocol\\\"] = \\\"saml\\\"\\n        with pytest.raises(ValueError, match=\\\"does not match\\\"):\\n            config.provider_settings = OIDCProviderSettings()\\n\\n    async def test_provider_settings_reject_invalid_oidc_payload(self):\\n        with pytest.raises(ValidationError, match=\\\"saml_metadata_url\\\"):\\n            SSOConfig(\\n                protocol=\\\"oidc\\\",\\n                display_name=\\\"Invalid\\\",\\n                provider_settings={\\n                    \\\"protocol\\\": \\\"oidc\\\",\\n                    \\\"saml_metadata_url\\\": \\\"https://idp.example.com/metadata\\\",\\n                },\\n            )\\n\\n    async def test_protocol_specific_settings_are_only_in_json_column(self):\\n        columns = SSOConfig.__table__.columns\\n        assert {\\\"protocol\\\", \\\"provider_settings\\\", \\\"client_secret_encrypted\\\"} <= set(columns.keys())\\n        assert {\\n            \\\"provider\\\",\\n            \\\"client_id\\\",\\n            \\\"discovery_url\\\",\\n            \\\"redirect_uri\\\",\\n            \\\"scopes\\\",\\n            \\\"token_endpoint\\\",\\n            \\\"authorization_endpoint\\\",\\n            \\\"jwks_uri\\\",\\n            \\\"issuer\\\",\\n        }.isdisjoint(columns.keys())\\n\\n    async def test_nested_provider_settings_are_immutable(self):\\n        config = SSOConfig(display_name=\\\"Immutable settings\\\")\\n        with pytest.raises(ValidationError, match=\\\"frozen_instance\\\"):\\n            config.provider_settings.client_id = \\\"new-client-id\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_sso_secrets.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"27dd29c231cd70b73451eab2800cf0edfa4e5d2d784da2ea1a3a96253f4094a2\",\"content\":\"\\\"\\\"\\\"Tests for the versioned SSO client-secret encryption contract.\\\"\\\"\\\"\\n\\nfrom types import SimpleNamespace\\n\\nimport pytest\\nfrom langflow.services.database.models import (\\n    SSOSecretError,\\n    decrypt_sso_client_secret,\\n    encrypt_sso_client_secret,\\n    is_sso_client_secret_envelope,\\n)\\nfrom pydantic import SecretStr\\n\\n_PLAINTEXT = \\\"downstream-oidc-client-secret\\\"\\n_DEFAULT_SECRET_KEY = \\\"unit-test-langflow-secret-key-material\\\"  # noqa: S105  # pragma: allowlist secret\\n\\n\\ndef _settings(secret_key: str | None = None):\\n    return SimpleNamespace(auth_settings=SimpleNamespace(SECRET_KEY=SecretStr(secret_key or _DEFAULT_SECRET_KEY)))\\n\\n\\ndef test_sso_client_secret_round_trip_uses_versioned_envelope():\\n    encrypted = encrypt_sso_client_secret(_PLAINTEXT, _settings())\\n\\n    assert decrypt_sso_client_secret(encrypted, _settings()) == _PLAINTEXT\\n    assert _PLAINTEXT not in encrypted\\n    assert encrypted.startswith(\\\"lf-sso:v1:hkdf-sha256-v1:aes-256-gcm:\\\")\\n\\n\\ndef test_sso_client_secret_defaults_to_existing_langflow_secret_key(monkeypatch):\\n    from langflow.services import deps\\n\\n    settings = _settings()\\n    monkeypatch.setattr(deps, \\\"get_settings_service\\\", lambda: settings)\\n\\n    encrypted = encrypt_sso_client_secret(_PLAINTEXT)\\n\\n    assert decrypt_sso_client_secret(encrypted) == _PLAINTEXT\\n\\n\\ndef test_sso_client_secret_encryption_uses_random_nonces():\\n    first = encrypt_sso_client_secret(_PLAINTEXT, _settings())\\n    second = encrypt_sso_client_secret(_PLAINTEXT, _settings())\\n\\n    assert first != second\\n    assert decrypt_sso_client_secret(first, _settings()) == _PLAINTEXT\\n    assert decrypt_sso_client_secret(second, _settings()) == _PLAINTEXT\\n\\n\\ndef test_sso_client_secret_rejects_wrong_langflow_secret_key():\\n    encrypted = encrypt_sso_client_secret(_PLAINTEXT, _settings(\\\"original-langflow-secret-key\\\"))\\n\\n    with pytest.raises(SSOSecretError, match=\\\"LANGFLOW_SECRET_KEY\\\"):\\n        decrypt_sso_client_secret(encrypted, _settings(\\\"different-langflow-secret-key\\\"))\\n\\n\\n@pytest.mark.parametrize(\\\"client_secret\\\", [\\\"\\\", \\\" \\\", \\\"\\\\t\\\\n\\\"])\\ndef test_sso_client_secret_rejects_blank_plaintext(client_secret):\\n    with pytest.raises(SSOSecretError, match=\\\"must not be blank\\\"):\\n        encrypt_sso_client_secret(client_secret, _settings())\\n\\n\\ndef test_sso_client_secret_rejects_unknown_envelope_version():\\n    encrypted = encrypt_sso_client_secret(_PLAINTEXT, _settings())\\n    unknown_version = encrypted.replace(\\\":v1:\\\", \\\":v2:\\\", 1)\\n\\n    with pytest.raises(SSOSecretError, match=\\\"version\\\"):\\n        decrypt_sso_client_secret(unknown_version, _settings())\\n\\n\\n@pytest.mark.parametrize(\\\"invalid_character\\\", [\\\"!\\\", \\\"+\\\", \\\"/\\\", \\\"=\\\"])\\n@pytest.mark.parametrize(\\\"payload_index\\\", [4, 5], ids=[\\\"nonce\\\", \\\"ciphertext\\\"])\\ndef test_sso_client_secret_rejects_non_base64url_payload_characters(invalid_character, payload_index):\\n    encrypted = encrypt_sso_client_secret(_PLAINTEXT, _settings())\\n    parts = encrypted.split(\\\":\\\")\\n    parts[payload_index] = f\\\"{invalid_character}{parts[payload_index][1:]}\\\"\\n    malformed = \\\":\\\".join(parts)\\n\\n    assert not is_sso_client_secret_envelope(malformed)\\n    with pytest.raises(SSOSecretError, match=\\\"Invalid base64url data\\\"):\\n        decrypt_sso_client_secret(malformed, _settings())\\n\\n\\n@pytest.mark.parametrize(\\\"payload_index\\\", [4, 5], ids=[\\\"nonce\\\", \\\"ciphertext\\\"])\\ndef test_sso_client_secret_rejects_empty_payload(payload_index):\\n    encrypted = encrypt_sso_client_secret(_PLAINTEXT, _settings())\\n    parts = encrypted.split(\\\":\\\")\\n    parts[payload_index] = \\\"\\\"\\n    malformed = \\\":\\\".join(parts)\\n\\n    assert not is_sso_client_secret_envelope(malformed)\\n    with pytest.raises(SSOSecretError, match=\\\"Invalid base64url data\\\"):\\n        decrypt_sso_client_secret(malformed, _settings())\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_strip_dynamic_fields.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f553752910be3b866657778081693ecb2f94876f516d155dfaffd05eed6c3ef0\",\"content\":\"\\\"\\\"\\\"Tests for the _strip_dynamic_fields function in build_component_index.py.\\\"\\\"\\\"\\n\\nimport sys\\nfrom pathlib import Path\\n\\nimport pytest\\n\\n\\n@pytest.fixture(scope=\\\"session\\\")\\ndef strip_dynamic_fields_func():\\n    \\\"\\\"\\\"Fixture to import and provide the _strip_dynamic_fields function.\\\"\\\"\\\"\\n    script_path = Path(__file__).parent.parent.parent.parent.parent / \\\"scripts\\\" / \\\"build_component_index.py\\\"\\n\\n    if not script_path.exists():\\n        pytest.skip(f\\\"build_component_index.py not found at {script_path}\\\")\\n\\n    import importlib.util\\n\\n    spec = importlib.util.spec_from_file_location(\\\"build_component_index\\\", script_path)\\n    build_module = importlib.util.module_from_spec(spec)\\n    sys.modules[\\\"build_component_index\\\"] = build_module\\n    spec.loader.exec_module(build_module)\\n\\n    return build_module._strip_dynamic_fields\\n\\n\\nclass TestStripDynamicFields:\\n    \\\"\\\"\\\"Test cases for _strip_dynamic_fields function.\\\"\\\"\\\"\\n\\n    def test_removes_timestamp_from_dict(self, strip_dynamic_fields_func):\\n        \\\"\\\"\\\"Test that timestamp field is removed from a dictionary.\\\"\\\"\\\"\\n        data = {\\\"name\\\": \\\"test\\\", \\\"timestamp\\\": \\\"2025-12-18 10:00:00\\\", \\\"value\\\": 42}\\n        result = strip_dynamic_fields_func(data)\\n        assert \\\"timestamp\\\" not in result\\n        assert result[\\\"name\\\"] == \\\"test\\\"\\n        assert result[\\\"value\\\"] == 42\\n\\n    def test_preserves_non_dynamic_fields(self, strip_dynamic_fields_func):\\n        \\\"\\\"\\\"Test that non-dynamic fields are preserved.\\\"\\\"\\\"\\n        data = {\\\"name\\\": \\\"component\\\", \\\"version\\\": \\\"1.0.0\\\", \\\"metadata\\\": {\\\"key\\\": \\\"value\\\"}, \\\"options\\\": [\\\"a\\\", \\\"b\\\"]}\\n        result = strip_dynamic_fields_func(data)\\n        assert result[\\\"name\\\"] == \\\"component\\\"\\n        assert result[\\\"version\\\"] == \\\"1.0.0\\\"\\n        assert result[\\\"metadata\\\"] == {\\\"key\\\": \\\"value\\\"}\\n\\n    def test_removes_timestamp_from_nested_dict(self, strip_dynamic_fields_func):\\n        \\\"\\\"\\\"Test that timestamp is removed from nested dictionaries.\\\"\\\"\\\"\\n        data = {\\\"level1\\\": {\\\"level2\\\": {\\\"timestamp\\\": \\\"2025-12-18 10:00:00\\\", \\\"data\\\": \\\"important\\\"}}}\\n        result = strip_dynamic_fields_func(data)\\n        assert \\\"timestamp\\\" not in result[\\\"level1\\\"][\\\"level2\\\"]\\n        assert result[\\\"level1\\\"][\\\"level2\\\"][\\\"data\\\"] == \\\"important\\\"\\n\\n    def test_removes_timestamp_from_list_items(self, strip_dynamic_fields_func):\\n        \\\"\\\"\\\"Test that timestamp is removed from items in a list.\\\"\\\"\\\"\\n        data = [\\n            {\\\"timestamp\\\": \\\"2025-12-18 10:00:00\\\", \\\"id\\\": 1},\\n            {\\\"timestamp\\\": \\\"2025-12-18 10:00:01\\\", \\\"id\\\": 2},\\n            {\\\"id\\\": 3},\\n        ]\\n        result = strip_dynamic_fields_func(data)\\n        assert all(\\\"timestamp\\\" not in item for item in result)\\n        assert result[0][\\\"id\\\"] == 1\\n        assert result[1][\\\"id\\\"] == 2\\n        assert result[2][\\\"id\\\"] == 3\\n\\n    def test_handles_empty_dict(self, strip_dynamic_fields_func):\\n        \\\"\\\"\\\"Test that empty dictionary is handled correctly.\\\"\\\"\\\"\\n        result = strip_dynamic_fields_func({})\\n        assert result == {}\\n\\n    def test_handles_empty_list(self, strip_dynamic_fields_func):\\n        \\\"\\\"\\\"Test that empty list is handled correctly.\\\"\\\"\\\"\\n        result = strip_dynamic_fields_func([])\\n        assert result == []\\n\\n    def test_handles_primitives(self, strip_dynamic_fields_func):\\n        \\\"\\\"\\\"Test that primitive types are returned unchanged.\\\"\\\"\\\"\\n        assert strip_dynamic_fields_func(\\\"string\\\") == \\\"string\\\"\\n        assert strip_dynamic_fields_func(42) == 42\\n        assert strip_dynamic_fields_func(3.14) == 3.14\\n        assert strip_dynamic_fields_func(None) is None\\n\\n    def test_complex_nested_structure(self, strip_dynamic_fields_func):\\n        \\\"\\\"\\\"Test with a complex nested structure similar to component metadata.\\\"\\\"\\\"\\n        data = {\\n            \\\"version\\\": \\\"1.7.0\\\",\\n            \\\"metadata\\\": {\\\"num_modules\\\": 95, \\\"num_components\\\": 355},\\n            \\\"entries\\\": [\\n                [\\n                    \\\"Model\\\",\\n                    {\\n                        \\\"ExampleComponent\\\": {\\n                            \\\"display_name\\\": \\\"Example Component\\\",\\n                            \\\"template\\\": {\\n                                \\\"model_name\\\": {\\n                                    \\\"value\\\": {\\\"data\\\": {\\\"timestamp\\\": \\\"2025-12-18 20:55:52 UTC\\\"}},\\n                                    \\\"options\\\": [\\\"gpt-4\\\", \\\"gpt-3.5-turbo\\\"],\\n                                }\\n                            },\\n                        }\\n                    },\\n                ]\\n            ],\\n        }\\n        result = strip_dynamic_fields_func(data)\\n        assert result[\\\"version\\\"] == \\\"1.7.0\\\"\\n        assert result[\\\"metadata\\\"][\\\"num_modules\\\"] == 95\\n        model_value = result[\\\"entries\\\"][0][1][\\\"ExampleComponent\\\"][\\\"template\\\"][\\\"model_name\\\"][\\\"value\\\"][\\\"data\\\"]\\n        assert \\\"timestamp\\\" not in model_value\\n        assert result[\\\"entries\\\"][0][0] == \\\"Model\\\"\\n\\n    def test_mixed_list_with_dicts_and_primitives(self, strip_dynamic_fields_func):\\n        \\\"\\\"\\\"Test list containing both dictionaries and primitives.\\\"\\\"\\\"\\n        data = [\\n            {\\\"timestamp\\\": \\\"2025-12-18\\\", \\\"value\\\": 1},\\n            \\\"string_item\\\",\\n            42,\\n            {\\\"id\\\": 2},\\n        ]\\n        result = strip_dynamic_fields_func(data)\\n        assert \\\"timestamp\\\" not in result[0]\\n        assert result[0][\\\"value\\\"] == 1\\n        assert result[1] == \\\"string_item\\\"\\n        assert result[2] == 42\\n        assert result[3] == {\\\"id\\\": 2}\\n\\n    def test_multiple_timestamps_in_structure(self, strip_dynamic_fields_func):\\n        \\\"\\\"\\\"Test that all timestamp fields at all levels are removed.\\\"\\\"\\\"\\n        data = {\\n            \\\"timestamp\\\": \\\"2025-12-18 10:00:00\\\",\\n            \\\"nested\\\": {\\n                \\\"timestamp\\\": \\\"2025-12-18 10:00:01\\\",\\n                \\\"deep\\\": {\\\"timestamp\\\": \\\"2025-12-18 10:00:02\\\", \\\"value\\\": \\\"keep_this\\\"},\\n            },\\n            \\\"items\\\": [{\\\"timestamp\\\": \\\"2025-12-18 10:00:03\\\", \\\"id\\\": 1}],\\n        }\\n        result = strip_dynamic_fields_func(data)\\n        assert \\\"timestamp\\\" not in result\\n        assert \\\"timestamp\\\" not in result[\\\"nested\\\"]\\n        assert \\\"timestamp\\\" not in result[\\\"nested\\\"][\\\"deep\\\"]\\n        assert \\\"timestamp\\\" not in result[\\\"items\\\"][0]\\n        assert result[\\\"nested\\\"][\\\"deep\\\"][\\\"value\\\"] == \\\"keep_this\\\"\\n        assert result[\\\"items\\\"][0][\\\"id\\\"] == 1\\n\\n    def test_preserves_field_order_in_dict(self, strip_dynamic_fields_func):\\n        \\\"\\\"\\\"Test that dictionary key order is preserved (Python 3.7+).\\\"\\\"\\\"\\n        data = {\\\"aaa\\\": 1, \\\"bbb\\\": 2, \\\"timestamp\\\": \\\"remove_me\\\", \\\"ccc\\\": 3}\\n        result = strip_dynamic_fields_func(data)\\n        keys = list(result.keys())\\n        assert \\\"timestamp\\\" not in keys\\n        assert keys == [\\\"aaa\\\", \\\"bbb\\\", \\\"ccc\\\"]\\n\\n    def test_deeply_nested_list_of_dicts(self, strip_dynamic_fields_func):\\n        \\\"\\\"\\\"Test deeply nested list containing dictionaries with timestamps.\\\"\\\"\\\"\\n        data = {\\n            \\\"items\\\": [\\n                {\\n                    \\\"nested_items\\\": [\\n                        {\\\"timestamp\\\": \\\"2025-12-18\\\", \\\"value\\\": 1},\\n                        {\\\"timestamp\\\": \\\"2025-12-18\\\", \\\"value\\\": 2},\\n                    ]\\n                }\\n            ]\\n        }\\n        result = strip_dynamic_fields_func(data)\\n        nested_dicts = result[\\\"items\\\"][0][\\\"nested_items\\\"]\\n        assert all(\\\"timestamp\\\" not in d for d in nested_dicts)\\n        assert nested_dicts[0][\\\"value\\\"] == 1\\n        assert nested_dicts[1][\\\"value\\\"] == 2\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_telemetry.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"60f47a623a2712b09ce1c5c2887354bb8dfa9459e83fe68fa44a6309c40d528e\",\"content\":\"import re\\nimport subprocess\\nimport sys\\nimport threading\\nfrom concurrent.futures import ThreadPoolExecutor, as_completed\\n\\nimport pytest\\nfrom langflow.services.telemetry.opentelemetry import (\\n    MetricType,\\n    OpenTelemetry,\\n    ThreadSafeSingletonMetaUsingWeakref,\\n)\\nfrom langflow.services.telemetry.schema import DeploymentPayload\\nfrom langflow.services.telemetry.service import TelemetryService\\n\\n\\n@pytest.fixture\\ndef mock_settings_service(mocker):\\n    settings = mocker.MagicMock()\\n    settings.settings.telemetry_base_url = \\\"http://test.telemetry\\\"\\n    settings.settings.prometheus_enabled = False\\n    settings.settings.do_not_track = False\\n    return settings\\n\\n\\n@pytest.fixture\\ndef telemetry_service(mock_settings_service):\\n    return TelemetryService(mock_settings_service)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_log_package_deployment(telemetry_service):\\n    payload = DeploymentPayload(\\n        deployment_action=\\\"deployment.create\\\",\\n        deployment_provider=\\\"test_provider\\\",\\n        deployment_seconds=1.0,\\n        deployment_success=True,\\n    )\\n    await telemetry_service.log_package_deployment(payload)\\n    func, queued_payload, path = await telemetry_service.telemetry_queue.get()\\n    assert func == telemetry_service.send_telemetry_data\\n    assert queued_payload == payload\\n    assert path == \\\"deployment\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_log_package_deployment_provider(telemetry_service):\\n    payload = DeploymentPayload(\\n        deployment_action=\\\"provider.create\\\",\\n        deployment_provider=\\\"test_provider\\\",\\n        deployment_seconds=1.0,\\n        deployment_success=True,\\n    )\\n    await telemetry_service.log_package_deployment_provider(payload)\\n    func, queued_payload, path = await telemetry_service.telemetry_queue.get()\\n    assert func == telemetry_service.send_telemetry_data\\n    assert queued_payload == payload\\n    assert path == \\\"deployment_provider\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_log_package_deployment_run(telemetry_service):\\n    payload = DeploymentPayload(\\n        deployment_action=\\\"deployment.run\\\",\\n        deployment_provider=\\\"test_provider\\\",\\n        deployment_seconds=1.0,\\n        deployment_success=True,\\n    )\\n    await telemetry_service.log_package_deployment_run(payload)\\n    func, queued_payload, path = await telemetry_service.telemetry_queue.get()\\n    assert func == telemetry_service.send_telemetry_data\\n    assert queued_payload == payload\\n    assert path == \\\"deployment_run\\\"\\n\\n\\n@pytest.mark.asyncio\\nasync def test_log_package_deployment_do_not_track(telemetry_service):\\n    telemetry_service.do_not_track = True\\n    payload = DeploymentPayload(\\n        deployment_action=\\\"deployment.create\\\",\\n        deployment_provider=\\\"test_provider\\\",\\n        deployment_seconds=1.0,\\n        deployment_success=True,\\n    )\\n    await telemetry_service.log_package_deployment(payload)\\n    await telemetry_service.log_package_deployment_provider(payload)\\n    await telemetry_service.log_package_deployment_run(payload)\\n    assert telemetry_service.telemetry_queue.empty()\\n\\n\\nfixed_labels = {\\\"flow_id\\\": \\\"this_flow_id\\\", \\\"service\\\": \\\"this\\\", \\\"user\\\": \\\"that\\\"}\\n\\n\\n@pytest.fixture\\ndef opentelemetry_instance():\\n    # Force a fresh, fully initialized singleton. pytest-split can schedule this module\\n    # without the sibling tests that would otherwise build it, and TelemetryService\\n    # teardowns elsewhere in the same worker call OpenTelemetry().shutdown(), which empties\\n    # the instrument dict while the metric definitions survive. Grabbing the singleton\\n    # as-is in that state fails with \\\"Metric '...' is not a counter\\\".\\n    ThreadSafeSingletonMetaUsingWeakref._instances.pop(OpenTelemetry, None)\\n    OpenTelemetry._initialized = False\\n    return OpenTelemetry()\\n\\n\\n@pytest.fixture(scope=\\\"session\\\", autouse=True)\\ndef cleanup_telemetry():\\n    yield\\n    OpenTelemetry().shutdown()\\n\\n\\ndef test_init(opentelemetry_instance):\\n    expected_metrics = {\\n        \\\"file_uploads\\\",\\n        \\\"num_files_uploaded\\\",\\n        \\\"langflow_job_queue_cancel_events_total\\\",\\n        \\\"langflow_job_queue_active_jobs\\\",\\n    }\\n\\n    assert isinstance(opentelemetry_instance, OpenTelemetry)\\n    assert set(opentelemetry_instance._metrics) == expected_metrics\\n    assert set(opentelemetry_instance._metrics_registry) == expected_metrics\\n    cancel_events = opentelemetry_instance._metrics_registry[\\\"langflow_job_queue_cancel_events_total\\\"]\\n    assert cancel_events.type is MetricType.COUNTER\\n    assert cancel_events.labels == {\\\"event_type\\\": True}\\n    active_jobs = opentelemetry_instance._metrics_registry[\\\"langflow_job_queue_active_jobs\\\"]\\n    assert active_jobs.type is MetricType.UP_DOWN_COUNTER\\n    assert active_jobs.labels == {\\\"backend\\\": True}\\n\\n\\ndef test_prometheus_exports_job_queue_metrics():\\n    script = \\\"\\\"\\\"\\nfrom langflow.services.telemetry.opentelemetry import OpenTelemetry\\nfrom prometheus_client import generate_latest\\n\\notel = OpenTelemetry(prometheus_enabled=True)\\notel.increment_counter(\\\"langflow_job_queue_cancel_events_total\\\", {\\\"event_type\\\": \\\"published\\\"})\\notel.up_down_counter(\\\"langflow_job_queue_active_jobs\\\", 1, {\\\"backend\\\": \\\"redis\\\"})\\nmetrics = generate_latest().decode()\\nassert \\\"langflow_job_queue_cancel_events_total\\\" in metrics\\nassert 'event_type=\\\"published\\\"' in metrics\\nassert \\\"langflow_job_queue_active_jobs\\\" in metrics\\nassert 'backend=\\\"redis\\\"' in metrics\\n\\\"\\\"\\\"\\n    result = subprocess.run(  # noqa: S603\\n        [sys.executable, \\\"-c\\\", script],\\n        check=False,\\n        capture_output=True,\\n        text=True,\\n    )\\n\\n    assert result.returncode == 0, result.stderr\\n\\n\\ndef test_gauge(opentelemetry_instance):\\n    opentelemetry_instance.update_gauge(\\\"file_uploads\\\", 1024, fixed_labels)\\n\\n\\ndef test_gauge_with_counter_method(opentelemetry_instance):\\n    with pytest.raises(TypeError, match=\\\"Metric 'file_uploads' is not a counter\\\"):\\n        opentelemetry_instance.increment_counter(metric_name=\\\"file_uploads\\\", value=1, labels=fixed_labels)\\n\\n\\ndef test_gauge_with_historgram_method(opentelemetry_instance):\\n    with pytest.raises(TypeError, match=\\\"Metric 'file_uploads' is not a histogram\\\"):\\n        opentelemetry_instance.observe_histogram(\\\"file_uploads\\\", 1, fixed_labels)\\n\\n\\ndef test_gauge_with_up_down_counter_method(opentelemetry_instance):\\n    with pytest.raises(TypeError, match=\\\"Metric 'file_uploads' is not an up down counter\\\"):\\n        opentelemetry_instance.up_down_counter(\\\"file_uploads\\\", 1, labels=fixed_labels)\\n\\n\\ndef test_increment_counter(opentelemetry_instance):\\n    opentelemetry_instance.increment_counter(metric_name=\\\"num_files_uploaded\\\", value=5, labels=fixed_labels)\\n\\n\\ndef test_increment_counter_empty_label(opentelemetry_instance):\\n    with pytest.raises(ValueError, match=\\\"Labels must be provided for the metric\\\"):\\n        opentelemetry_instance.increment_counter(metric_name=\\\"num_files_uploaded\\\", value=5, labels={})\\n\\n\\ndef test_increment_counter_missing_mandatory_label(opentelemetry_instance):\\n    with pytest.raises(ValueError, match=re.escape(\\\"Missing required labels: {'flow_id'}\\\")):\\n        opentelemetry_instance.increment_counter(metric_name=\\\"num_files_uploaded\\\", value=5, labels={\\\"service\\\": \\\"one\\\"})\\n\\n\\ndef test_increment_counter_unregisted_metric(opentelemetry_instance):\\n    with pytest.raises(ValueError, match=\\\"Metric 'num_files_uploaded_1' is not registered\\\"):\\n        opentelemetry_instance.increment_counter(metric_name=\\\"num_files_uploaded_1\\\", value=5, labels=fixed_labels)\\n\\n\\ndef test_opentelementry_singleton(opentelemetry_instance):\\n    opentelemetry_instance_2 = OpenTelemetry()\\n    assert opentelemetry_instance is opentelemetry_instance_2\\n\\n    opentelemetry_instance_3 = OpenTelemetry(prometheus_enabled=False)\\n    assert opentelemetry_instance is opentelemetry_instance_3\\n    assert opentelemetry_instance.prometheus_enabled == opentelemetry_instance_3.prometheus_enabled\\n\\n\\ndef test_recovers_when_instruments_are_missing():\\n    \\\"\\\"\\\"Rebuild instruments when definitions survive but instruments are gone.\\n\\n    Nightly CI regression: a TelemetryService teardown reached shutdown() while the\\n    instance stayed referenced, and the next construction had to rebuild the instruments\\n    instead of raising \\\"Metric 'num_files_uploaded' is not a counter\\\".\\n    \\\"\\\"\\\"\\n    stale = OpenTelemetry()\\n    stale._metrics.clear()\\n    OpenTelemetry._initialized = True\\n    ThreadSafeSingletonMetaUsingWeakref._instances.pop(OpenTelemetry, None)\\n\\n    healed = OpenTelemetry()\\n    healed.increment_counter(metric_name=\\\"num_files_uploaded\\\", value=1, labels=fixed_labels)\\n\\n\\ndef test_new_instance_after_shutdown_recovers(opentelemetry_instance):\\n    \\\"\\\"\\\"shutdown() must not leave a live-but-gutted singleton behind.\\n\\n    The next OpenTelemetry() call builds a fresh instance with working instruments even\\n    while a reference to the shut-down one is still alive.\\n    \\\"\\\"\\\"\\n    opentelemetry_instance.shutdown()\\n\\n    replacement = OpenTelemetry()\\n    assert replacement is not opentelemetry_instance\\n    replacement.increment_counter(metric_name=\\\"num_files_uploaded\\\", value=1, labels=fixed_labels)\\n\\n\\ndef test_missing_labels(opentelemetry_instance):\\n    with pytest.raises(ValueError, match=\\\"Labels must be provided for the metric\\\"):\\n        opentelemetry_instance.increment_counter(metric_name=\\\"num_files_uploaded\\\", labels=None, value=1.0)\\n    with pytest.raises(ValueError, match=\\\"Labels must be provided for the metric\\\"):\\n        opentelemetry_instance.up_down_counter(\\\"num_files_uploaded\\\", 1, None)\\n    with pytest.raises(ValueError, match=\\\"Labels must be provided for the metric\\\"):\\n        opentelemetry_instance.update_gauge(metric_name=\\\"num_files_uploaded\\\", value=1.0, labels={})\\n    with pytest.raises(ValueError, match=\\\"Labels must be provided for the metric\\\"):\\n        opentelemetry_instance.observe_histogram(\\\"num_files_uploaded\\\", 1, {})\\n\\n\\ndef test_multithreaded_singleton():\\n    def create_instance():\\n        return OpenTelemetry()\\n\\n    # Create instances in multiple threads\\n    with ThreadPoolExecutor(max_workers=10) as executor:\\n        futures = [executor.submit(create_instance) for _ in range(100)]\\n        instances = [future.result() for future in as_completed(futures)]\\n\\n    # Check that all instances are the same\\n    first_instance = instances[0]\\n    for instance in instances[1:]:\\n        assert instance is first_instance\\n\\n\\ndef test_multithreaded_singleton_race_condition():\\n    # This test simulates a potential race condition\\n    start_event = threading.Event()\\n\\n    def create_instance():\\n        start_event.wait()  # Wait for all threads to be ready\\n        return OpenTelemetry()\\n\\n    # Create instances in multiple threads, all starting at the same time\\n    with ThreadPoolExecutor(max_workers=100) as executor:\\n        futures = [executor.submit(create_instance) for _ in range(100)]\\n        start_event.set()  # Start all threads simultaneously\\n        instances = [future.result() for future in as_completed(futures)]\\n\\n    # Check that all instances are the same\\n    first_instance = instances[0]\\n    for instance in instances[1:]:\\n        assert instance is first_instance\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_template.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a1e03ea5bdbd0f8d6e5b177863e3930f879da6a118ada5d2de79947f0320580f\",\"content\":\"import importlib\\n\\nimport pytest\\nfrom lfx.utils.util import build_template_from_function, get_base_classes, get_default_factory\\nfrom pydantic import BaseModel\\n\\n\\n# Dummy classes for testing purposes\\nclass Parent(BaseModel):\\n    \\\"\\\"\\\"Parent Class.\\\"\\\"\\\"\\n\\n    parent_field: str\\n\\n\\nclass Child(Parent):\\n    \\\"\\\"\\\"Child Class.\\\"\\\"\\\"\\n\\n    child_field: int\\n\\n\\nclass ExampleClass1(BaseModel):\\n    \\\"\\\"\\\"Example class 1.\\\"\\\"\\\"\\n\\n    def __init__(self, data: list[int] | None = None):\\n        self.data = data or [1, 2, 3]\\n\\n\\nclass ExampleClass2(BaseModel):\\n    \\\"\\\"\\\"Example class 2.\\\"\\\"\\\"\\n\\n    def __init__(self, data: dict[str, int] | None = None):\\n        self.data = data or {\\\"a\\\": 1, \\\"b\\\": 2, \\\"c\\\": 3}\\n\\n\\ndef example_loader_1() -> ExampleClass1:\\n    \\\"\\\"\\\"Example loader function 1.\\\"\\\"\\\"\\n    return ExampleClass1()\\n\\n\\ndef example_loader_2() -> ExampleClass2:\\n    \\\"\\\"\\\"Example loader function 2.\\\"\\\"\\\"\\n    return ExampleClass2()\\n\\n\\ndef test_build_template_from_function():\\n    type_to_loader_dict = {\\n        \\\"example1\\\": example_loader_1,\\n        \\\"example2\\\": example_loader_2,\\n    }\\n\\n    # Test with valid name\\n    result = build_template_from_function(\\\"ExampleClass1\\\", type_to_loader_dict)\\n\\n    assert result is not None\\n    assert \\\"template\\\" in result\\n    assert \\\"description\\\" in result\\n    assert \\\"base_classes\\\" in result\\n\\n    # Test with add_function=True\\n    result_with_function = build_template_from_function(\\\"ExampleClass1\\\", type_to_loader_dict, add_function=True)\\n    assert result_with_function is not None\\n    assert \\\"Callable\\\" in result_with_function[\\\"base_classes\\\"]\\n\\n    # Test with invalid name\\n    with pytest.raises(ValueError, match=r\\\".* not found\\\"):\\n        build_template_from_function(\\\"NonExistent\\\", type_to_loader_dict)\\n\\n\\n# Test get_base_classes\\ndef test_get_base_classes():\\n    base_classes_parent = get_base_classes(Parent)\\n    base_classes_child = get_base_classes(Child)\\n\\n    assert \\\"Parent\\\" in base_classes_parent\\n    assert \\\"Child\\\" in base_classes_child\\n    assert \\\"Parent\\\" in base_classes_child\\n\\n\\n# Test get_default_factory\\ndef test_get_default_factory():\\n    module_name = \\\"lfx.utils.util\\\"\\n    function_repr = \\\"<function dummy_function>\\\"\\n\\n    def dummy_function():\\n        return \\\"default_value\\\"\\n\\n    # Add dummy_function to your_module\\n    importlib.import_module(module_name).dummy_function = dummy_function\\n\\n    default_value = get_default_factory(module_name, function_repr)\\n\\n    assert default_value == \\\"default_value\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_unified_models.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"eb3d44af85d71544edebe93be1f2b583057cd1ccd8bab26ede0402f71298c8fc\",\"content\":\"from unittest.mock import AsyncMock, MagicMock, patch\\n\\nimport pytest\\nfrom lfx.base.embeddings.embeddings_class import EmbeddingsWithModels\\nfrom lfx.base.models import models_dev_catalog\\nfrom lfx.base.models.unified_models import (\\n    _get_all_provider_mapped_fields,\\n    apply_provider_variable_config_to_build_config,\\n    get_embedding_model_options,\\n    get_embeddings,\\n    get_unified_models_detailed,\\n    handle_model_input_update,\\n    update_model_options_in_build_config,\\n)\\nfrom lfx.base.models.unified_models.build_config import _resolve_dropdown_provider_values\\nfrom lfx.base.models.unified_models.provider_queries import get_models_detailed\\nfrom lfx.services.variable.request_scope import activate_no_env_fallback, reset_no_env_fallback\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _clear_models_dev_snapshot():\\n    \\\"\\\"\\\"Isolate every test in this file from any active models.dev snapshot.\\n\\n    The backend ``client`` fixture's lifespan installs a snapshot via\\n    ``set_active_snapshot`` and never resets it on teardown, so tests that\\n    expect the static bundled catalog (e.g. ``test_filter_by_model_name``,\\n    which relies on ``gpt-4`` not being auto-deprecated by the age-based\\n    rule in ``_translate_model_entry``) would otherwise fail when run in\\n    the same xdist worker as a fixture-using test.\\n    \\\"\\\"\\\"\\n    prior = models_dev_catalog.get_active_snapshot()\\n    try:\\n        models_dev_catalog.set_active_snapshot(None)\\n        get_models_detailed.cache_clear()\\n        yield\\n    finally:\\n        models_dev_catalog.set_active_snapshot(prior)\\n        get_models_detailed.cache_clear()\\n\\n\\ndef _flatten_models(result):\\n    \\\"\\\"\\\"Helper to flatten result to list of model dicts.\\\"\\\"\\\"\\n    for provider_dict in result:\\n        yield from provider_dict[\\\"models\\\"]\\n\\n\\ndef test_default_providers_present():\\n    result = get_unified_models_detailed()\\n    providers = {entry[\\\"provider\\\"] for entry in result}\\n    assert \\\"OpenAI\\\" in providers\\n    assert \\\"Anthropic\\\" in providers\\n    assert \\\"Google Generative AI\\\" in providers\\n\\n\\ndef test_default_excludes_not_supported():\\n    result = get_unified_models_detailed()\\n    for model in _flatten_models(result):\\n        # By default, models flagged not_supported should be absent\\n        assert model[\\\"metadata\\\"].get(\\\"not_supported\\\", False) is False\\n\\n\\ndef test_default_excludes_deprecated():\\n    result = get_unified_models_detailed()\\n    for model in _flatten_models(result):\\n        # By default, models flagged deprecated should be absent\\n        assert model[\\\"metadata\\\"].get(\\\"deprecated\\\", False) is False\\n\\n\\ndef test_include_deprecated_parameter_returns_deprecated_models():\\n    # When explicitly requested, at least one deprecated model should be present.\\n    result = get_unified_models_detailed(include_deprecated=True)\\n    deprecated_models = [m for m in _flatten_models(result) if m[\\\"metadata\\\"].get(\\\"deprecated\\\", False)]\\n    assert deprecated_models, \\\"Expected at least one deprecated model when include_deprecated=True\\\"\\n\\n    # Sanity check: restricting by provider that is known to have deprecated entries (e.g., Anthropic)\\n    result_anthropic = get_unified_models_detailed(providers=[\\\"Anthropic\\\"], include_deprecated=True)\\n    anthropic_deprecated = [m for m in _flatten_models(result_anthropic) if m[\\\"metadata\\\"].get(\\\"deprecated\\\", False)]\\n    assert anthropic_deprecated, \\\"Expected deprecated Anthropic models when include_deprecated=True\\\"\\n\\n\\ndef test_filter_by_provider():\\n    result = get_unified_models_detailed(providers=[\\\"Anthropic\\\"])\\n    # Only one provider should be returned\\n    assert len(result) == 1\\n    assert result[0][\\\"provider\\\"] == \\\"Anthropic\\\"\\n    # Ensure all models are from that provider\\n    for _model in _flatten_models(result):\\n        assert result[0][\\\"provider\\\"] == \\\"Anthropic\\\"\\n\\n\\ndef test_filter_by_model_name():\\n    target = \\\"gpt-4\\\"\\n    result = get_unified_models_detailed(model_name=target)\\n    # Should only include OpenAI provider with the single model\\n    assert len(result) == 1\\n    provider_dict = result[0]\\n    assert provider_dict[\\\"provider\\\"] == \\\"OpenAI\\\"\\n    assert len(provider_dict[\\\"models\\\"]) == 1\\n    assert provider_dict[\\\"models\\\"][0][\\\"model_name\\\"] == target\\n\\n\\ndef test_filter_by_metadata():\\n    # Require tool_calling support\\n    result = get_unified_models_detailed(tool_calling=True)\\n    assert result, \\\"Expected at least one model supporting tool calling\\\"\\n    for model in _flatten_models(result):\\n        assert model[\\\"metadata\\\"].get(\\\"tool_calling\\\", False) is True\\n\\n\\ndef test_filter_by_model_type_embeddings():\\n    result = get_unified_models_detailed(model_type=\\\"embeddings\\\")\\n    models = list(_flatten_models(result))\\n    assert models, \\\"Expected at least one embedding model\\\"\\n    for model in models:\\n        assert model[\\\"metadata\\\"].get(\\\"model_type\\\", \\\"llm\\\") == \\\"embeddings\\\"\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.model_catalog._fetch_enabled_providers_for_user\\\", new_callable=AsyncMock)\\n@patch(\\\"lfx.base.models.unified_models.model_catalog._get_model_status\\\", new_callable=AsyncMock)\\ndef test_google_embedding_options_map_dimensions_to_output_dimensionality(mock_get_model_status, mock_fetch_providers):\\n    mock_get_model_status.return_value = (set(), set())\\n    mock_fetch_providers.return_value = {\\\"Google Generative AI\\\"}\\n\\n    options = get_embedding_model_options(user_id=\\\"test-user\\\")\\n\\n    google_embedding = next(\\n        option\\n        for option in options\\n        if option[\\\"provider\\\"] == \\\"Google Generative AI\\\" and option[\\\"name\\\"] == \\\"models/gemini-embedding-001\\\"\\n    )\\n    assert google_embedding[\\\"metadata\\\"][\\\"param_mapping\\\"][\\\"dimensions\\\"] == \\\"output_dimensionality\\\"\\n\\n\\ndef test_update_model_options_with_custom_field_name():\\n    \\\"\\\"\\\"Test that update_model_options_in_build_config works with custom field names.\\\"\\\"\\\"\\n    # Create mock component\\n    mock_component = MagicMock()\\n    mock_component.cache = {}\\n    mock_component.log = MagicMock()\\n\\n    # Create build_config with custom field name\\n    build_config = {\\n        \\\"embedding_model\\\": {\\n            \\\"options\\\": [],\\n            \\\"value\\\": \\\"\\\",\\n            \\\"input_types\\\": [\\\"Embeddings\\\"],\\n        }\\n    }\\n\\n    # Mock options function\\n    def mock_get_options(user_id=None):  # noqa: ARG001\\n        return [\\n            {\\\"name\\\": \\\"text-embedding-ada-002\\\", \\\"provider\\\": \\\"OpenAI\\\"},\\n            {\\\"name\\\": \\\"embed-english-v3.0\\\", \\\"provider\\\": \\\"Cohere\\\"},\\n        ]\\n\\n    # Call with custom field name\\n    result = update_model_options_in_build_config(\\n        component=mock_component,\\n        build_config=build_config,\\n        cache_key_prefix=\\\"test_embedding_options\\\",\\n        get_options_func=mock_get_options,\\n        field_name=None,\\n        field_value=\\\"\\\",\\n        model_field_name=\\\"embedding_model\\\",\\n    )\\n\\n    # Verify options were populated in the custom field\\n    assert \\\"embedding_model\\\" in result\\n    assert len(result[\\\"embedding_model\\\"][\\\"options\\\"]) == 2\\n    assert result[\\\"embedding_model\\\"][\\\"options\\\"][0][\\\"name\\\"] == \\\"text-embedding-ada-002\\\"\\n    assert result[\\\"embedding_model\\\"][\\\"options\\\"][1][\\\"provider\\\"] == \\\"Cohere\\\"\\n\\n    # A bare initial load must not guess a provider for the user (LE-2168)\\n    assert not result[\\\"embedding_model\\\"][\\\"value\\\"]\\n\\n\\ndef test_update_model_options_static_options_with_custom_field_name():\\n    \\\"\\\"\\\"Static pre-populated options should be detected using the custom field name, not 'model'.\\\"\\\"\\\"\\n    mock_component = MagicMock()\\n    mock_component.cache = {}\\n    mock_component.log = MagicMock()\\n\\n    static_opts = [{\\\"name\\\": \\\"embed-v1\\\", \\\"provider\\\": \\\"Custom\\\"}]\\n    build_config = {\\n        \\\"embedding_model\\\": {\\n            \\\"options\\\": static_opts,\\n            \\\"value\\\": \\\"\\\",\\n            \\\"input_types\\\": [\\\"Embeddings\\\"],\\n        }\\n    }\\n\\n    result = update_model_options_in_build_config(\\n        component=mock_component,\\n        build_config=build_config,\\n        cache_key_prefix=\\\"test_static_custom\\\",\\n        get_options_func=list,\\n        model_field_name=\\\"embedding_model\\\",\\n    )\\n\\n    # Static options should be preserved, not overwritten by the empty get_options_func result\\n    assert result[\\\"embedding_model\\\"][\\\"options\\\"] == static_opts\\n\\n\\ndef test_update_model_options_default_field_name():\\n    \\\"\\\"\\\"Test that update_model_options_in_build_config uses 'model' as default field name.\\\"\\\"\\\"\\n    # Create mock component\\n    mock_component = MagicMock()\\n    mock_component.cache = {}\\n    mock_component.log = MagicMock()\\n\\n    # Create build_config with default field name\\n    build_config = {\\n        \\\"model\\\": {\\n            \\\"options\\\": [],\\n            \\\"value\\\": \\\"\\\",\\n            \\\"input_types\\\": [\\\"LanguageModel\\\"],\\n        }\\n    }\\n\\n    # Mock options function\\n    def mock_get_options(user_id=None):  # noqa: ARG001\\n        return [{\\\"name\\\": \\\"gpt-4\\\", \\\"provider\\\": \\\"OpenAI\\\"}]\\n\\n    # Call without specifying model_field_name (should default to \\\"model\\\")\\n    result = update_model_options_in_build_config(\\n        component=mock_component,\\n        build_config=build_config,\\n        cache_key_prefix=\\\"test_model_options\\\",\\n        get_options_func=mock_get_options,\\n        field_name=None,\\n        field_value=\\\"\\\",\\n    )\\n\\n    # Verify options were populated in the default \\\"model\\\" field\\n    assert \\\"model\\\" in result\\n    assert len(result[\\\"model\\\"][\\\"options\\\"]) == 1\\n    assert result[\\\"model\\\"][\\\"options\\\"][0][\\\"name\\\"] == \\\"gpt-4\\\"\\n\\n\\ndef test_update_model_options_injects_saved_value_when_missing_from_options():\\n    \\\"\\\"\\\"Saved model selections missing from refreshed options should be re-injected with a marker.\\\"\\\"\\\"\\n    component = _make_mock_component()\\n    component.user_id = \\\"user-123\\\"\\n    saved_model = {\\n        \\\"name\\\": \\\"claude-3-5-sonnet\\\",\\n        \\\"provider\\\": \\\"Anthropic\\\",\\n        \\\"metadata\\\": {\\\"model_class\\\": \\\"ChatAnthropic\\\", \\\"existing_flag\\\": True},\\n    }\\n    fetched_options = [{\\\"name\\\": \\\"gpt-4o-mini\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {\\\"model_class\\\": \\\"ChatOpenAI\\\"}}]\\n    build_config = {\\n        \\\"model\\\": {\\n            \\\"options\\\": [],\\n            \\\"value\\\": [saved_model],\\n            \\\"input_types\\\": [\\\"LanguageModel\\\"],\\n        }\\n    }\\n\\n    result = update_model_options_in_build_config(\\n        component=component,\\n        build_config=build_config,\\n        cache_key_prefix=\\\"test_sticky_default_injection\\\",\\n        get_options_func=lambda user_id=None: fetched_options,  # noqa: ARG005\\n        field_name=None,\\n    )\\n\\n    assert result[\\\"model\\\"][\\\"value\\\"] == [saved_model]\\n    assert len(result[\\\"model\\\"][\\\"options\\\"]) == 2\\n    assert result[\\\"model\\\"][\\\"options\\\"][0] == fetched_options[0]\\n    assert result[\\\"model\\\"][\\\"options\\\"][1] == {\\n        \\\"name\\\": \\\"claude-3-5-sonnet\\\",\\n        \\\"provider\\\": \\\"Anthropic\\\",\\n        \\\"metadata\\\": {\\n            \\\"model_class\\\": \\\"ChatAnthropic\\\",\\n            \\\"existing_flag\\\": True,\\n            \\\"not_enabled_locally\\\": True,\\n        },\\n    }\\n\\n\\ndef test_update_model_options_does_not_duplicate_saved_value_already_in_options():\\n    \\\"\\\"\\\"Saved model selections already present in options should not be duplicated or marked.\\\"\\\"\\\"\\n    component = _make_mock_component()\\n    component.user_id = \\\"user-123\\\"\\n    saved_model = {\\n        \\\"name\\\": \\\"gpt-4o-mini\\\",\\n        \\\"provider\\\": \\\"OpenAI\\\",\\n        \\\"metadata\\\": {\\\"model_class\\\": \\\"ChatOpenAI\\\"},\\n    }\\n    build_config = {\\n        \\\"model\\\": {\\n            \\\"options\\\": [],\\n            \\\"value\\\": [saved_model],\\n            \\\"input_types\\\": [\\\"LanguageModel\\\"],\\n        }\\n    }\\n\\n    result = update_model_options_in_build_config(\\n        component=component,\\n        build_config=build_config,\\n        cache_key_prefix=\\\"test_sticky_default_no_duplicate\\\",\\n        get_options_func=lambda user_id=None: [saved_model],  # noqa: ARG005\\n        field_name=None,\\n    )\\n\\n    assert result[\\\"model\\\"][\\\"options\\\"] == [saved_model]\\n    assert result[\\\"model\\\"][\\\"options\\\"].count(saved_model) == 1\\n    assert \\\"not_enabled_locally\\\" not in result[\\\"model\\\"][\\\"options\\\"][0][\\\"metadata\\\"]\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"current_value\\\", \\\"expected_value\\\"),\\n    [\\n        ([], []),\\n        (\\\"gpt-4o-mini\\\", \\\"gpt-4o-mini\\\"),\\n        (\\n            [{\\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {\\\"model_class\\\": \\\"ChatOpenAI\\\"}}],\\n            [{\\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {\\\"model_class\\\": \\\"ChatOpenAI\\\"}}],\\n        ),\\n    ],\\n)\\ndef test_update_model_options_sticky_default_ignores_invalid_saved_value_shapes(current_value, expected_value):\\n    \\\"\\\"\\\"Sticky-default injection should ignore empty or malformed saved values.\\\"\\\"\\\"\\n    component = _make_mock_component()\\n    component.user_id = \\\"user-123\\\"\\n    fetched_options = [{\\\"name\\\": \\\"gpt-4o-mini\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {\\\"model_class\\\": \\\"ChatOpenAI\\\"}}]\\n    build_config = {\\n        \\\"model\\\": {\\n            \\\"options\\\": [],\\n            \\\"value\\\": current_value,\\n            \\\"input_types\\\": [\\\"LanguageModel\\\"],\\n        }\\n    }\\n\\n    result = update_model_options_in_build_config(\\n        component=component,\\n        build_config=build_config,\\n        cache_key_prefix=\\\"test_sticky_default_edge_cases\\\",\\n        get_options_func=lambda user_id=None: fetched_options,  # noqa: ARG005\\n        field_name=None,\\n    )\\n\\n    assert result[\\\"model\\\"][\\\"options\\\"] == fetched_options\\n    assert all(\\\"not_enabled_locally\\\" not in option.get(\\\"metadata\\\", {}) for option in result[\\\"model\\\"][\\\"options\\\"])\\n    assert result[\\\"model\\\"][\\\"value\\\"] == expected_value\\n\\n\\n# ---------------------------------------------------------------------------\\n# Helpers shared by new tests\\n# ---------------------------------------------------------------------------\\n\\n\\ndef _make_mock_component():\\n    component = MagicMock()\\n    component.cache = {}\\n    component.log = MagicMock()\\n    return component\\n\\n\\ndef _make_model_field(value=\\\"\\\", options=None, input_types=None):\\n    return {\\n        \\\"value\\\": value,\\n        \\\"options\\\": options or [],\\n        \\\"input_types\\\": input_types or [\\\"LanguageModel\\\"],\\n        \\\"show\\\": True,\\n    }\\n\\n\\ndef _make_openai_embedding_model(name=\\\"text-embedding-3-small\\\"):\\n    return {\\n        \\\"name\\\": name,\\n        \\\"provider\\\": \\\"OpenAI\\\",\\n        \\\"metadata\\\": {\\n            \\\"embedding_class\\\": \\\"OpenAIEmbeddings\\\",\\n            \\\"param_mapping\\\": {\\n                \\\"model\\\": \\\"model\\\",\\n                \\\"api_key\\\": \\\"api_key\\\",  # pragma: allowlist secret\\n                \\\"api_base\\\": \\\"base_url\\\",\\n                \\\"dimensions\\\": \\\"dimensions\\\",\\n                \\\"chunk_size\\\": \\\"chunk_size\\\",\\n                \\\"request_timeout\\\": \\\"request_timeout\\\",\\n                \\\"max_retries\\\": \\\"max_retries\\\",\\n                \\\"show_progress_bar\\\": \\\"show_progress_bar\\\",\\n                \\\"model_kwargs\\\": \\\"model_kwargs\\\",\\n            },\\n        },\\n    }\\n\\n\\n# ---------------------------------------------------------------------------\\n# _get_all_provider_mapped_fields tests\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_get_all_provider_mapped_fields_returns_set():\\n    fields = _get_all_provider_mapped_fields()\\n    assert isinstance(fields, set)\\n    assert len(fields) > 0\\n\\n\\ndef test_get_all_provider_mapped_fields_contains_expected_fields():\\n    fields = _get_all_provider_mapped_fields()\\n    expected = {\\\"base_url_ibm_watsonx\\\", \\\"project_id\\\", \\\"ollama_base_url\\\"}\\n    assert expected & fields, f\\\"Expected at least one of {expected} to be in provider mapped fields\\\"\\n\\n\\ndef test_get_all_provider_mapped_fields_is_cached():\\n    \\\"\\\"\\\"Calling twice returns the exact same object (lru_cache).\\\"\\\"\\\"\\n    fields1 = _get_all_provider_mapped_fields()\\n    fields2 = _get_all_provider_mapped_fields()\\n    assert fields1 is fields2\\n\\n\\ndef test_api_key_optional_provider_with_only_optional_variables_is_enabled_without_values():\\n    from lfx.base.models.unified_models import credentials\\n\\n    optional_variables = [\\n        {\\n            \\\"variable_key\\\": \\\"AMBIENT_ENDPOINT\\\",\\n            \\\"required\\\": False,\\n            \\\"is_secret\\\": False,\\n        }\\n    ]\\n    with (\\n        patch.object(credentials, \\\"get_provider_all_variables\\\", return_value=optional_variables),\\n        patch(\\\"lfx.base.models.provider_registry.is_api_key_optional\\\", return_value=True),\\n    ):\\n        enabled = credentials._validate_and_get_enabled_providers(\\n            {},\\n            {\\\"AmbientAuthCo\\\": \\\"AMBIENT_ENDPOINT\\\"},\\n        )\\n\\n    assert enabled == {\\\"AmbientAuthCo\\\"}\\n\\n\\n# ---------------------------------------------------------------------------\\n# get_embeddings tests\\n# ---------------------------------------------------------------------------\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _skip_available_models_catalog(monkeypatch):\\n    \\\"\\\"\\\"Keep existing get_embeddings tests focused on the primary instance.\\\"\\\"\\\"\\n    monkeypatch.setattr(\\n        \\\"lfx.base.models.unified_models.instantiation._get_provider_embedding_model_names\\\",\\n        lambda _provider, _user_id: [],\\n    )\\n\\n\\ndef test_get_embeddings_passthrough_embeddings_object():\\n    \\\"\\\"\\\"An already-instantiated Embeddings object should be returned as-is.\\\"\\\"\\\"\\n    from langchain_core.embeddings import Embeddings as BaseEmbeddings\\n\\n    mock_emb = MagicMock(spec=BaseEmbeddings)\\n    result = get_embeddings(mock_emb)\\n    assert result is mock_emb\\n\\n\\ndef test_get_embeddings_empty_list_raises():\\n    with pytest.raises(ValueError, match=\\\"An embedding model selection is required\\\"):\\n        get_embeddings([])\\n\\n\\ndef test_get_embeddings_none_raises():\\n    with pytest.raises(ValueError, match=\\\"An embedding model selection is required\\\"):\\n        get_embeddings(None)\\n\\n\\ndef test_get_embeddings_non_list_raises():\\n    with pytest.raises(ValueError, match=\\\"An embedding model selection is required\\\"):\\n        get_embeddings(\\\"gpt-4\\\")\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\ndef test_get_embeddings_missing_api_key_non_ollama_raises(mock_get_api_key):\\n    mock_get_api_key.return_value = None\\n    with pytest.raises(ValueError, match=\\\"OpenAI API key is required\\\"):\\n        get_embeddings([_make_openai_embedding_model()])\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\ndef test_get_embeddings_missing_model_name_raises(mock_get_api_key):\\n    mock_get_api_key.return_value = \\\"test-key\\\"\\n    model_dict = {\\n        \\\"name\\\": None,\\n        \\\"provider\\\": \\\"OpenAI\\\",\\n        \\\"metadata\\\": {\\\"embedding_class\\\": \\\"OpenAIEmbeddings\\\", \\\"param_mapping\\\": {\\\"model\\\": \\\"model\\\"}},\\n    }\\n    with pytest.raises(ValueError, match=\\\"Embedding model name is required\\\"):\\n        get_embeddings([model_dict])\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\ndef test_get_embeddings_missing_embedding_class_raises(mock_get_api_key):\\n    \\\"\\\"\\\"Unknown providers can't be looked up in EMBEDDING_PROVIDER_CLASS_MAPPING.\\n\\n    So missing ``embedding_class`` metadata still raises.\\n    \\\"\\\"\\\"\\n    mock_get_api_key.return_value = \\\"test-key\\\"\\n    model_dict = {\\n        \\\"name\\\": \\\"text-embedding-3-small\\\",\\n        \\\"provider\\\": \\\"Unknown\\\",\\n        \\\"metadata\\\": {\\\"param_mapping\\\": {\\\"model\\\": \\\"model\\\"}},\\n    }\\n    with pytest.raises(ValueError, match=\\\"No embedding class defined in metadata\\\"):\\n        get_embeddings([model_dict])\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\ndef test_get_embeddings_empty_param_mapping_raises(mock_get_api_key):\\n    \\\"\\\"\\\"Unknown providers can't be looked up in EMBEDDING_PARAM_MAPPINGS.\\n\\n    So empty ``param_mapping`` metadata still raises.\\n    \\\"\\\"\\\"\\n    mock_get_api_key.return_value = \\\"test-key\\\"\\n    model_dict = {\\n        \\\"name\\\": \\\"text-embedding-3-small\\\",\\n        \\\"provider\\\": \\\"Unknown\\\",\\n        \\\"metadata\\\": {\\\"embedding_class\\\": \\\"OpenAIEmbeddings\\\", \\\"param_mapping\\\": {}},\\n    }\\n    with pytest.raises(ValueError, match=\\\"Parameter mapping not found in metadata\\\"):\\n        get_embeddings([model_dict])\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_embedding_class\\\")\\ndef test_get_embeddings_falls_back_when_metadata_stripped(mock_get_class, mock_get_api_key):\\n    \\\"\\\"\\\"Selections persisted via the generic ``/models`` catalog lack enriched metadata.\\n\\n    ``embedding_class`` and ``param_mapping`` are missing in that case.\\n    Instantiation should derive both from ``EMBEDDING_PROVIDER_CLASS_MAPPING``\\n    and ``EMBEDDING_PARAM_MAPPINGS`` rather than failing \u2014 otherwise KB\\n    ingestion would error on every model picked through the KB upload modal.\\n    \\\"\\\"\\\"\\n    mock_get_api_key.return_value = \\\"sk-test\\\"\\n    fake_class = MagicMock(return_value=\\\"embeddings-instance\\\")\\n    mock_get_class.return_value = fake_class\\n\\n    model_dict = {\\n        \\\"name\\\": \\\"text-embedding-3-small\\\",\\n        \\\"provider\\\": \\\"OpenAI\\\",\\n        \\\"metadata\\\": {},  # No embedding_class, no param_mapping.\\n    }\\n    result = get_embeddings([model_dict])\\n\\n    mock_get_class.assert_called_once_with(\\\"OpenAIEmbeddings\\\")\\n    fake_class.assert_called_once()\\n    kwargs = fake_class.call_args.kwargs\\n    assert kwargs[\\\"model\\\"] == \\\"text-embedding-3-small\\\"\\n    assert kwargs[\\\"api_key\\\"] == \\\"sk-test\\\"\\n    assert isinstance(result, EmbeddingsWithModels)\\n    assert result.embeddings == \\\"embeddings-instance\\\"\\n    assert result.available_models == {\\\"text-embedding-3-small\\\": \\\"embeddings-instance\\\"}\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_embedding_class\\\")\\ndef test_get_embeddings_openai_basic(mock_get_class, mock_get_api_key):\\n    mock_get_api_key.return_value = \\\"sk-test\\\"\\n    mock_embedding_class = MagicMock()\\n    mock_instance = MagicMock()\\n    mock_embedding_class.return_value = mock_instance\\n    mock_get_class.return_value = mock_embedding_class\\n\\n    result = get_embeddings([_make_openai_embedding_model()], api_key=\\\"sk-test\\\")\\n\\n    assert isinstance(result, EmbeddingsWithModels)\\n    assert result.embeddings is mock_instance\\n    assert result.available_models == {\\\"text-embedding-3-small\\\": mock_instance}\\n    mock_get_class.assert_called_once_with(\\\"OpenAIEmbeddings\\\")\\n    kwargs = mock_embedding_class.call_args.kwargs\\n    assert kwargs[\\\"model\\\"] == \\\"text-embedding-3-small\\\"\\n    assert kwargs[\\\"api_key\\\"] == \\\"sk-test\\\"  # pragma: allowlist secret\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_embedding_class\\\")\\ndef test_get_embeddings_populates_available_models_from_all_configured_providers(\\n    mock_get_class, mock_get_api_key, monkeypatch\\n):\\n    monkeypatch.setattr(\\n        \\\"lfx.base.models.unified_models.instantiation._get_configured_embedding_providers\\\",\\n        lambda _user_id, _selected_provider: [\\\"OpenAI\\\", \\\"Google Generative AI\\\"],\\n    )\\n\\n    def _embedding_names_for_provider(provider, _user_id):\\n        if provider == \\\"OpenAI\\\":\\n            return [\\\"text-embedding-3-small\\\", \\\"text-embedding-3-large\\\"]\\n        if provider == \\\"Google Generative AI\\\":\\n            return [\\\"models/text-embedding-004\\\"]\\n        return []\\n\\n    monkeypatch.setattr(\\n        \\\"lfx.base.models.unified_models.instantiation._get_provider_embedding_model_names\\\",\\n        _embedding_names_for_provider,\\n    )\\n    mock_get_api_key.return_value = \\\"sk-test\\\"\\n    primary = MagicMock(name=\\\"primary\\\")\\n    openai_secondary = MagicMock(name=\\\"openai-secondary\\\")\\n    google_embedding = MagicMock(name=\\\"google-embedding\\\")\\n    mock_embedding_class = MagicMock(side_effect=[primary, openai_secondary, google_embedding])\\n    mock_get_class.return_value = mock_embedding_class\\n\\n    result = get_embeddings([_make_openai_embedding_model()], api_key=\\\"sk-test\\\")\\n\\n    assert isinstance(result, EmbeddingsWithModels)\\n    assert result.embeddings is primary\\n    assert set(result.available_models.keys()) == {\\n        \\\"text-embedding-3-small\\\",\\n        \\\"text-embedding-3-large\\\",\\n        \\\"models/text-embedding-004\\\",\\n    }\\n    assert result.available_models[\\\"text-embedding-3-small\\\"] is primary\\n    assert result.available_models[\\\"text-embedding-3-large\\\"] is openai_secondary\\n    assert result.available_models[\\\"models/text-embedding-004\\\"] is google_embedding\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_embedding_class\\\")\\ndef test_get_embeddings_skips_policy_denied_secondary_provider_before_lookup(\\n    mock_get_class, mock_get_api_key, monkeypatch\\n):\\n    from lfx.services.model_provider_policy import (\\n        ModelProviderPolicyContext,\\n        ModelProviderPolicyPurpose,\\n        ModelProviderPolicySnapshot,\\n    )\\n\\n    monkeypatch.setattr(\\n        \\\"lfx.base.models.unified_models.instantiation._get_configured_embedding_providers\\\",\\n        lambda _user_id, _selected_provider: [\\\"OpenAI\\\", \\\"Google Generative AI\\\"],\\n    )\\n    looked_up_providers = []\\n\\n    def _embedding_names_for_provider(provider, _user_id):\\n        looked_up_providers.append(provider)\\n        if provider == \\\"Google Generative AI\\\":\\n            pytest.fail(\\\"policy-denied provider catalog must not be read\\\")\\n        return [\\\"text-embedding-3-small\\\"]\\n\\n    monkeypatch.setattr(\\n        \\\"lfx.base.models.unified_models.instantiation._get_provider_embedding_model_names\\\",\\n        _embedding_names_for_provider,\\n    )\\n    mock_get_api_key.return_value = \\\"sk-test\\\"\\n    primary = MagicMock(name=\\\"primary\\\")\\n    mock_embedding_class = MagicMock(return_value=primary)\\n    mock_get_class.return_value = mock_embedding_class\\n    policy = ModelProviderPolicySnapshot(\\n        context=ModelProviderPolicyContext(user_id=\\\"user-1\\\"),\\n        purpose=ModelProviderPolicyPurpose.USE,\\n        candidate_provider_ids=frozenset({\\\"openai\\\", \\\"google-generative-ai\\\"}),\\n        allowed_provider_ids=frozenset({\\\"openai\\\"}),\\n    )\\n\\n    result = get_embeddings(\\n        [_make_openai_embedding_model()],\\n        api_key=\\\"sk-test\\\",  # pragma: allowlist secret\\n        provider_policy=policy,\\n    )\\n\\n    assert result.available_models == {\\\"text-embedding-3-small\\\": primary}\\n    assert looked_up_providers == [\\\"OpenAI\\\"]\\n    assert all(call.args[1] != \\\"Google Generative AI\\\" for call in mock_get_api_key.call_args_list)\\n\\n\\n@pytest.mark.parametrize(\\n    (\\\"env_values\\\", \\\"expected_base_url\\\"),\\n    [\\n        ({\\\"OPENAI_EMBEDDINGS_API_BASE\\\": \\\"http://embeddings.example/v1\\\"}, \\\"http://embeddings.example/v1\\\"),\\n        ({\\\"OPENAI_API_BASE\\\": \\\"http://openai-compatible.example/v1\\\"}, \\\"http://openai-compatible.example/v1\\\"),\\n        (\\n            {\\n                \\\"OPENAI_EMBEDDINGS_API_BASE\\\": \\\"http://embeddings.example/v1\\\",\\n                \\\"OPENAI_API_BASE\\\": \\\"http://openai-compatible.example/v1\\\",\\n            },\\n            \\\"http://embeddings.example/v1\\\",\\n        ),\\n    ],\\n)\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_embedding_class\\\")\\n@patch(\\\"lfx.base.models.unified_models.instantiation.ssrf_protected_openai_clients_for_url\\\")\\ndef test_get_embeddings_openai_api_base_env_fallback(\\n    mock_ssrf_protection,\\n    mock_get_class,\\n    mock_get_api_key,\\n    monkeypatch,\\n    env_values,\\n    expected_base_url,\\n):\\n    mock_ssrf_protection.return_value = {}\\n    mock_get_api_key.return_value = \\\"sk-test\\\"\\n    mock_embedding_class = MagicMock()\\n    mock_get_class.return_value = mock_embedding_class\\n    monkeypatch.delenv(\\\"OPENAI_EMBEDDINGS_API_BASE\\\", raising=False)\\n    monkeypatch.delenv(\\\"OPENAI_API_BASE\\\", raising=False)\\n    for name, value in env_values.items():\\n        monkeypatch.setenv(name, value)\\n\\n    get_embeddings([_make_openai_embedding_model()], api_key=\\\"sk-test\\\")\\n\\n    kwargs = mock_embedding_class.call_args.kwargs\\n    assert kwargs[\\\"base_url\\\"] == expected_base_url\\n    mock_ssrf_protection.assert_called_once_with(expected_base_url)\\n\\n\\n@pytest.mark.parametrize(\\\"variable_name\\\", [\\\"OPENAI_EMBEDDINGS_API_BASE\\\", \\\"OPENAI_API_BASE\\\"])\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_embedding_class\\\")\\ndef test_get_embeddings_openai_api_base_env_fallback_can_be_disabled(\\n    mock_get_class, mock_get_api_key, monkeypatch, variable_name\\n):\\n    mock_get_api_key.return_value = \\\"sk-test\\\"\\n    mock_embedding_class = MagicMock()\\n    mock_get_class.return_value = mock_embedding_class\\n    monkeypatch.setenv(variable_name, \\\"http://openai-compatible.example/v1\\\")\\n    token = activate_no_env_fallback(disabled=True)\\n\\n    try:\\n        get_embeddings([_make_openai_embedding_model()], api_key=\\\"sk-test\\\")\\n    finally:\\n        reset_no_env_fallback(token)\\n\\n    assert \\\"base_url\\\" not in mock_embedding_class.call_args.kwargs\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_embedding_class\\\")\\n@patch(\\\"lfx.base.models.unified_models.instantiation.ssrf_protected_openai_clients_for_url\\\")\\ndef test_get_embeddings_openai_explicit_api_base_overrides_env(\\n    mock_ssrf_protection, mock_get_class, mock_get_api_key, monkeypatch\\n):\\n    mock_ssrf_protection.return_value = {}\\n    mock_get_api_key.return_value = \\\"sk-test\\\"\\n    mock_embedding_class = MagicMock()\\n    mock_get_class.return_value = mock_embedding_class\\n    monkeypatch.setenv(\\\"OPENAI_EMBEDDINGS_API_BASE\\\", \\\"http://embeddings.example/v1\\\")\\n    monkeypatch.setenv(\\\"OPENAI_API_BASE\\\", \\\"http://openai-compatible.example/v1\\\")\\n\\n    get_embeddings(\\n        [_make_openai_embedding_model()],\\n        api_key=\\\"sk-test\\\",  # pragma: allowlist secret\\n        api_base=\\\"http://component.example/v1\\\",\\n    )\\n\\n    kwargs = mock_embedding_class.call_args.kwargs\\n    assert kwargs[\\\"base_url\\\"] == \\\"http://component.example/v1\\\"\\n    mock_ssrf_protection.assert_called_once_with(\\\"http://component.example/v1\\\")\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_embedding_class\\\")\\ndef test_get_embeddings_optional_params_only_added_when_mapped(mock_get_class, mock_get_api_key):\\n    \\\"\\\"\\\"Parameters only appear in kwargs if their key is in param_mapping.\\\"\\\"\\\"\\n    mock_get_api_key.return_value = \\\"sk-test\\\"\\n    mock_embedding_class = MagicMock()\\n    mock_get_class.return_value = mock_embedding_class\\n\\n    get_embeddings(\\n        [_make_openai_embedding_model()],\\n        api_key=\\\"sk-test\\\",  # pragma: allowlist secret\\n        chunk_size=500,\\n        max_retries=5,\\n    )\\n\\n    kwargs = mock_embedding_class.call_args.kwargs\\n    assert kwargs.get(\\\"chunk_size\\\") == 500\\n    assert kwargs.get(\\\"max_retries\\\") == 5\\n    # dimensions not provided - should not appear\\n    assert kwargs.get(\\\"dimensions\\\") is None\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_embedding_class\\\")\\ndef test_get_embeddings_google_timeout_wrapped_in_dict(mock_get_class, mock_get_api_key):\\n    \\\"\\\"\\\"For Google Generative AI, request_timeout is wrapped and dimensions are passed through.\\\"\\\"\\\"\\n    mock_get_api_key.return_value = \\\"google-key\\\"\\n    mock_embedding_class = MagicMock()\\n    mock_get_class.return_value = mock_embedding_class\\n\\n    google_model = {\\n        \\\"name\\\": \\\"models/text-embedding-004\\\",\\n        \\\"provider\\\": \\\"Google Generative AI\\\",\\n        \\\"metadata\\\": {\\n            \\\"embedding_class\\\": \\\"GoogleGenerativeAIEmbeddings\\\",\\n            \\\"param_mapping\\\": {\\n                \\\"model\\\": \\\"model\\\",\\n                \\\"api_key\\\": \\\"google_api_key\\\",  # pragma: allowlist secret\\n                \\\"dimensions\\\": \\\"output_dimensionality\\\",\\n                \\\"request_timeout\\\": \\\"request_options\\\",\\n            },\\n        },\\n    }\\n\\n    get_embeddings(\\n        [google_model],\\n        api_key=\\\"google-key\\\",  # pragma: allowlist secret\\n        dimensions=768,\\n        request_timeout=30.0,\\n    )\\n\\n    kwargs = mock_embedding_class.call_args.kwargs\\n    assert kwargs.get(\\\"output_dimensionality\\\") == 768\\n    assert kwargs.get(\\\"request_options\\\") == {\\\"timeout\\\": 30.0}\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_embedding_class\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_all_variables_for_provider\\\")\\ndef test_get_embeddings_ollama_defaults_to_localhost(mock_get_vars, mock_get_class, mock_get_api_key):\\n    mock_get_api_key.return_value = None  # Ollama doesn't need an API key\\n    mock_get_vars.return_value = {}\\n    mock_embedding_class = MagicMock()\\n    mock_get_class.return_value = mock_embedding_class\\n\\n    ollama_model = {\\n        \\\"name\\\": \\\"nomic-embed-text\\\",\\n        \\\"provider\\\": \\\"Ollama\\\",\\n        \\\"metadata\\\": {\\n            \\\"embedding_class\\\": \\\"OllamaEmbeddings\\\",\\n            \\\"param_mapping\\\": {\\\"model\\\": \\\"model\\\", \\\"base_url\\\": \\\"base_url\\\"},\\n        },\\n    }\\n\\n    get_embeddings([ollama_model])\\n\\n    kwargs = mock_embedding_class.call_args.kwargs\\n    assert kwargs.get(\\\"base_url\\\") == \\\"http://localhost:11434\\\"\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_embedding_class\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_all_variables_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.instantiation.ssrf_protected_httpx_client_kwargs_for_url\\\")\\ndef test_get_embeddings_ollama_custom_base_url(mock_ssrf_protection, mock_get_vars, mock_get_class, mock_get_api_key):\\n    mock_ssrf_protection.return_value = ({}, {})\\n    mock_get_api_key.return_value = None\\n    mock_get_vars.return_value = {}\\n    mock_embedding_class = MagicMock()\\n    mock_get_class.return_value = mock_embedding_class\\n\\n    ollama_model = {\\n        \\\"name\\\": \\\"nomic-embed-text\\\",\\n        \\\"provider\\\": \\\"Ollama\\\",\\n        \\\"metadata\\\": {\\n            \\\"embedding_class\\\": \\\"OllamaEmbeddings\\\",\\n            \\\"param_mapping\\\": {\\\"model\\\": \\\"model\\\", \\\"base_url\\\": \\\"base_url\\\"},\\n        },\\n    }\\n\\n    get_embeddings([ollama_model], ollama_base_url=\\\"http://custom-host:11434\\\")\\n\\n    kwargs = mock_embedding_class.call_args.kwargs\\n    assert kwargs.get(\\\"base_url\\\") == \\\"http://custom-host:11434\\\"\\n    mock_ssrf_protection.assert_called_once_with(\\\"http://custom-host:11434\\\")\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_embedding_class\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_all_variables_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.instantiation.validate_url_for_ssrf_or_raise\\\")\\ndef test_get_embeddings_watsonx_url_and_project_id(\\n    mock_ssrf_validation, mock_get_vars, mock_get_class, mock_get_api_key\\n):\\n    mock_get_api_key.return_value = \\\"ibm-key\\\"\\n    mock_get_vars.return_value = {}\\n    mock_embedding_class = MagicMock()\\n    mock_get_class.return_value = mock_embedding_class\\n\\n    watsonx_model = {\\n        \\\"name\\\": \\\"ibm/slate-125m-english-rtrvr\\\",\\n        \\\"provider\\\": \\\"IBM WatsonX\\\",\\n        \\\"metadata\\\": {\\n            \\\"embedding_class\\\": \\\"WatsonxEmbeddings\\\",\\n            \\\"param_mapping\\\": {\\n                \\\"model_id\\\": \\\"model_id\\\",\\n                \\\"api_key\\\": \\\"apikey\\\",  # pragma: allowlist secret\\n                \\\"url\\\": \\\"url\\\",\\n                \\\"project_id\\\": \\\"project_id\\\",\\n            },\\n        },\\n    }\\n\\n    get_embeddings(\\n        [watsonx_model],\\n        api_key=\\\"ibm-key\\\",  # pragma: allowlist secret\\n        watsonx_url=\\\"https://us-south.ml.cloud.ibm.com\\\",\\n        watsonx_project_id=\\\"proj-123\\\",\\n    )\\n\\n    kwargs = mock_embedding_class.call_args.kwargs\\n    assert kwargs.get(\\\"url\\\") == \\\"https://us-south.ml.cloud.ibm.com\\\"\\n    assert kwargs.get(\\\"project_id\\\") == \\\"proj-123\\\"\\n    mock_ssrf_validation.assert_called_once_with(\\\"https://us-south.ml.cloud.ibm.com\\\")\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_embedding_class\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_all_variables_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.instantiation.validate_url_for_ssrf_or_raise\\\")\\ndef test_get_embeddings_watsonx_truncate_and_input_text(\\n    mock_ssrf_validation, mock_get_vars, mock_get_class, mock_get_api_key\\n):\\n    \\\"\\\"\\\"truncate_input_tokens and input_text should be passed as WatsonX params dict.\\\"\\\"\\\"\\n    mock_get_api_key.return_value = \\\"ibm-key\\\"\\n    mock_get_vars.return_value = {}\\n    mock_embedding_class = MagicMock()\\n    mock_get_class.return_value = mock_embedding_class\\n\\n    watsonx_model = {\\n        \\\"name\\\": \\\"ibm/slate-125m-english-rtrvr\\\",\\n        \\\"provider\\\": \\\"IBM WatsonX\\\",\\n        \\\"metadata\\\": {\\n            \\\"embedding_class\\\": \\\"WatsonxEmbeddings\\\",\\n            \\\"param_mapping\\\": {\\n                \\\"model_id\\\": \\\"model_id\\\",\\n                \\\"api_key\\\": \\\"apikey\\\",  # pragma: allowlist secret\\n                \\\"url\\\": \\\"url\\\",\\n                \\\"project_id\\\": \\\"project_id\\\",\\n            },\\n        },\\n    }\\n\\n    get_embeddings(\\n        [watsonx_model],\\n        api_key=\\\"ibm-key\\\",  # pragma: allowlist secret\\n        watsonx_url=\\\"https://us-south.ml.cloud.ibm.com\\\",\\n        watsonx_project_id=\\\"proj-123\\\",\\n        watsonx_truncate_input_tokens=200,\\n        watsonx_input_text=True,\\n    )\\n\\n    kwargs = mock_embedding_class.call_args.kwargs\\n    assert \\\"params\\\" in kwargs\\n    params = kwargs[\\\"params\\\"]\\n    # Check truncate_input_tokens is present (key may be enum or string depending on ibm_watsonx_ai availability)\\n    truncate_values = [v for v in params.values() if v == 200]\\n    assert truncate_values, \\\"Expected truncate_input_tokens=200 in params\\\"\\n    # Check return_options contains input_text\\n    return_opts = [v for v in params.values() if isinstance(v, dict) and \\\"input_text\\\" in v]\\n    assert return_opts, \\\"Expected return_options with input_text in params\\\"\\n    assert return_opts[0][\\\"input_text\\\"] is True\\n    mock_ssrf_validation.assert_called_once_with(\\\"https://us-south.ml.cloud.ibm.com\\\")\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_embedding_class\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_all_variables_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.instantiation.validate_url_for_ssrf_or_raise\\\")\\ndef test_get_embeddings_watsonx_no_params_when_not_provided(\\n    mock_ssrf_validation, mock_get_vars, mock_get_class, mock_get_api_key\\n):\\n    \\\"\\\"\\\"When truncate_input_tokens and input_text are not provided, params should not be set.\\\"\\\"\\\"\\n    mock_get_api_key.return_value = \\\"ibm-key\\\"\\n    mock_get_vars.return_value = {}\\n    mock_embedding_class = MagicMock()\\n    mock_get_class.return_value = mock_embedding_class\\n\\n    watsonx_model = {\\n        \\\"name\\\": \\\"ibm/slate-125m-english-rtrvr\\\",\\n        \\\"provider\\\": \\\"IBM WatsonX\\\",\\n        \\\"metadata\\\": {\\n            \\\"embedding_class\\\": \\\"WatsonxEmbeddings\\\",\\n            \\\"param_mapping\\\": {\\n                \\\"model_id\\\": \\\"model_id\\\",\\n                \\\"api_key\\\": \\\"apikey\\\",  # pragma: allowlist secret\\n                \\\"url\\\": \\\"url\\\",\\n                \\\"project_id\\\": \\\"project_id\\\",\\n            },\\n        },\\n    }\\n\\n    get_embeddings(\\n        [watsonx_model],\\n        api_key=\\\"ibm-key\\\",  # pragma: allowlist secret\\n        watsonx_url=\\\"https://us-south.ml.cloud.ibm.com\\\",\\n        watsonx_project_id=\\\"proj-123\\\",\\n    )\\n\\n    kwargs = mock_embedding_class.call_args.kwargs\\n    assert \\\"params\\\" not in kwargs\\n    mock_ssrf_validation.assert_called_once_with(\\\"https://us-south.ml.cloud.ibm.com\\\")\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_api_key_for_provider\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_embedding_class\\\")\\n@patch(\\\"lfx.base.models.unified_models.get_all_variables_for_provider\\\")\\ndef test_get_embeddings_watsonx_error_wraps_message(mock_get_vars, mock_get_class, mock_get_api_key):\\n    \\\"\\\"\\\"IBM WatsonX instantiation errors mentioning url/project get wrapped in a friendlier ValueError.\\\"\\\"\\\"\\n    mock_get_api_key.return_value = \\\"ibm-key\\\"\\n    mock_get_vars.return_value = {}\\n    mock_embedding_class = MagicMock()\\n    mock_embedding_class.side_effect = RuntimeError(\\\"missing project id\\\")\\n    mock_get_class.return_value = mock_embedding_class\\n\\n    watsonx_model = {\\n        \\\"name\\\": \\\"ibm/slate-125m-english-rtrvr\\\",\\n        \\\"provider\\\": \\\"IBM WatsonX\\\",\\n        \\\"metadata\\\": {\\n            \\\"embedding_class\\\": \\\"WatsonxEmbeddings\\\",\\n            \\\"param_mapping\\\": {\\\"model_id\\\": \\\"model_id\\\", \\\"api_key\\\": \\\"apikey\\\"},\\n        },\\n    }\\n\\n    with pytest.raises(ValueError, match=\\\"IBM WatsonX requires additional configuration\\\"):\\n        get_embeddings([watsonx_model], api_key=\\\"ibm-key\\\")  # pragma: allowlist secret\\n\\n\\n# ---------------------------------------------------------------------------\\n# handle_model_input_update tests\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_handle_model_input_update_hides_all_provider_fields_by_default():\\n    \\\"\\\"\\\"Provider-specific fields should be hidden when no model is selected.\\\"\\\"\\\"\\n    component = _make_mock_component()\\n    provider_fields = _get_all_provider_mapped_fields()\\n\\n    build_config = {\\\"model\\\": _make_model_field()}\\n    for f in provider_fields:\\n        build_config[f] = {\\\"show\\\": True, \\\"required\\\": True}\\n\\n    def get_options(user_id=None):  # noqa: ARG001\\n        return []\\n\\n    result = handle_model_input_update(\\n        component, build_config, field_value=\\\"\\\", field_name=None, get_options_func=get_options\\n    )\\n\\n    for f in provider_fields:\\n        assert result[f][\\\"show\\\"] is False, f\\\"Field {f} should be hidden when no model is selected\\\"\\n        assert result[f][\\\"required\\\"] is False\\n\\n\\ndef test_handle_model_input_update_ollama_hides_and_clears_api_key():\\n    \\\"\\\"\\\"Selecting Ollama (which has no api_key variable) must hide AND clear api_key.\\n\\n    Regression test: api_key was previously forced visible for every provider,\\n    leaving a stale cross-provider credential (e.g. ``OPENAI_API_KEY``) sitting\\n    behind the hidden field when switching to Ollama.\\n    \\\"\\\"\\\"\\n    component = _make_mock_component()\\n    selected_model = [{\\\"name\\\": \\\"llama3\\\", \\\"provider\\\": \\\"Ollama\\\", \\\"metadata\\\": {}}]\\n    build_config = {\\n        \\\"model\\\": _make_model_field(value=selected_model),\\n        \\\"api_key\\\": {\\n            \\\"show\\\": True,\\n            \\\"required\\\": False,\\n            \\\"value\\\": \\\"OPENAI_API_KEY\\\",\\n            \\\"load_from_db\\\": True,\\n            \\\"_input_type\\\": \\\"SecretStrInput\\\",\\n        },\\n        \\\"ollama_base_url\\\": {\\n            \\\"show\\\": False,\\n            \\\"required\\\": False,\\n            \\\"value\\\": \\\"\\\",\\n            \\\"_input_type\\\": \\\"StrInput\\\",\\n        },\\n    }\\n\\n    result = handle_model_input_update(\\n        component,\\n        build_config,\\n        field_value=selected_model,\\n        field_name=\\\"model\\\",\\n        get_options_func=lambda user_id=None: selected_model,  # noqa: ARG005\\n    )\\n\\n    assert result[\\\"api_key\\\"][\\\"show\\\"] is False, \\\"api_key must be hidden for Ollama\\\"\\n    assert result[\\\"api_key\\\"][\\\"value\\\"] == \\\"\\\", \\\"stale cross-provider api_key must be cleared for Ollama\\\"\\n    assert result[\\\"api_key\\\"][\\\"load_from_db\\\"] is False, \\\"load_from_db must be reset when clearing api_key\\\"\\n    # Ollama's own variable is shown and configured.\\n    assert result[\\\"ollama_base_url\\\"][\\\"show\\\"] is True\\n\\n\\ndef test_handle_model_input_update_openai_keeps_api_key_visible():\\n    \\\"\\\"\\\"Providers that map a variable to api_key keep an empty field empty.\\\"\\\"\\\"\\n    component = _make_mock_component()\\n    selected_model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n    build_config = {\\n        \\\"model\\\": _make_model_field(value=selected_model),\\n        \\\"api_key\\\": {\\n            \\\"show\\\": False,  # start hidden to prove apply_provider_... re-shows it\\n            \\\"required\\\": False,\\n            \\\"value\\\": \\\"\\\",\\n            \\\"load_from_db\\\": False,\\n            \\\"_input_type\\\": \\\"SecretStrInput\\\",\\n        },\\n    }\\n\\n    result = handle_model_input_update(\\n        component,\\n        build_config,\\n        field_value=selected_model,\\n        field_name=\\\"model\\\",\\n        get_options_func=lambda user_id=None: selected_model,  # noqa: ARG005\\n    )\\n\\n    assert result[\\\"api_key\\\"][\\\"show\\\"] is True, \\\"api_key must stay visible for OpenAI\\\"\\n    assert result[\\\"api_key\\\"][\\\"value\\\"] == \\\"\\\"\\n    assert result[\\\"api_key\\\"][\\\"load_from_db\\\"] is False\\n\\n\\ndef test_handle_model_input_update_preserves_edited_field_when_initial_provider_is_selected():\\n    \\\"\\\"\\\"Auto-selecting the initial provider must not clear the provider field being edited.\\\"\\\"\\\"\\n    component = _make_mock_component()\\n    selected_model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n    build_config = {\\n        \\\"model\\\": _make_model_field(),\\n        \\\"api_key\\\": {\\n            \\\"show\\\": True,\\n            \\\"required\\\": False,\\n            \\\"value\\\": \\\"literal-api-key\\\",\\n            \\\"load_from_db\\\": False,\\n            \\\"_input_type\\\": \\\"SecretStrInput\\\",\\n        },\\n        \\\"project_id\\\": {\\n            \\\"show\\\": True,\\n            \\\"required\\\": False,\\n            \\\"value\\\": \\\"stale-project\\\",\\n            \\\"load_from_db\\\": False,\\n            \\\"_input_type\\\": \\\"StrInput\\\",\\n        },\\n    }\\n\\n    result = handle_model_input_update(\\n        component,\\n        build_config,\\n        field_value=\\\"literal-api-key\\\",\\n        field_name=\\\"api_key\\\",\\n        get_options_func=lambda user_id=None: selected_model,  # noqa: ARG005\\n    )\\n\\n    assert result[\\\"model\\\"][\\\"value\\\"] == selected_model\\n    assert result[\\\"api_key\\\"][\\\"value\\\"] == \\\"literal-api-key\\\"\\n    assert result[\\\"api_key\\\"][\\\"load_from_db\\\"] is False\\n    assert result[\\\"project_id\\\"][\\\"value\\\"] == \\\"\\\"\\n    assert result[\\\"project_id\\\"][\\\"load_from_db\\\"] is False\\n\\n\\ndef test_handle_model_input_update_clears_edited_field_not_used_by_initial_provider():\\n    \\\"\\\"\\\"Initial provider selection must clear an edited field that belongs to another provider.\\\"\\\"\\\"\\n    component = _make_mock_component()\\n    selected_model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n    build_config = {\\n        \\\"model\\\": _make_model_field(),\\n        \\\"project_id\\\": {\\n            \\\"show\\\": True,\\n            \\\"required\\\": False,\\n            \\\"value\\\": \\\"stale-project\\\",\\n            \\\"load_from_db\\\": False,\\n            \\\"_input_type\\\": \\\"StrInput\\\",\\n        },\\n    }\\n\\n    result = handle_model_input_update(\\n        component,\\n        build_config,\\n        field_value=\\\"stale-project\\\",\\n        field_name=\\\"project_id\\\",\\n        get_options_func=lambda user_id=None: selected_model,  # noqa: ARG005\\n    )\\n\\n    assert result[\\\"model\\\"][\\\"value\\\"] == selected_model\\n    assert result[\\\"project_id\\\"][\\\"show\\\"] is False\\n    assert result[\\\"project_id\\\"][\\\"value\\\"] == \\\"\\\"\\n    assert result[\\\"project_id\\\"][\\\"load_from_db\\\"] is False\\n\\n\\ndef test_handle_model_input_update_uses_language_model_options_by_default():\\n    \\\"\\\"\\\"When no get_options_func is provided, get_language_model_options is used.\\\"\\\"\\\"\\n    component = _make_mock_component()\\n    build_config = {\\\"model\\\": _make_model_field()}\\n\\n    with patch(\\\"lfx.base.models.unified_models.get_language_model_options\\\") as mock_opts:\\n        mock_opts.return_value = []\\n        handle_model_input_update(component, build_config, field_value=\\\"\\\", field_name=None)\\n        mock_opts.assert_called_once()\\n\\n\\ndef test_handle_model_input_update_calls_apply_provider_config_when_model_selected():\\n    \\\"\\\"\\\"Selecting a model should call apply_provider_variable_config_to_build_config.\\\"\\\"\\\"\\n    component = _make_mock_component()\\n    selected_model = [{\\\"name\\\": \\\"gpt-4\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n    build_config = {\\\"model\\\": _make_model_field(value=selected_model)}\\n\\n    with patch(\\\"lfx.base.models.unified_models.apply_provider_variable_config_to_build_config\\\") as mock_apply:\\n        mock_apply.side_effect = lambda cfg, provider, **kw: cfg  # noqa: ARG005\\n\\n        def get_options(user_id=None):  # noqa: ARG001\\n            return selected_model\\n\\n        handle_model_input_update(\\n            component, build_config, field_value=selected_model, field_name=\\\"model\\\", get_options_func=get_options\\n        )\\n\\n        mock_apply.assert_called_once_with(build_config, \\\"OpenAI\\\")\\n\\n\\ndef test_policy_refresh_clears_hidden_provider_fields_before_applying_allowed_default():\\n    from lfx.services.model_provider_policy import (\\n        ModelProviderPolicyContext,\\n        ModelProviderPolicyPurpose,\\n        ModelProviderPolicySnapshot,\\n    )\\n\\n    component = _make_mock_component()\\n    watsonx = [{\\\"name\\\": \\\"watsonx-test\\\", \\\"provider\\\": \\\"IBM WatsonX\\\", \\\"metadata\\\": {}}]\\n    openai = [{\\\"name\\\": \\\"gpt-test\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n    build_config = {\\n        \\\"model\\\": _make_model_field(value=watsonx),\\n        \\\"api_key\\\": {\\n            \\\"show\\\": True,\\n            \\\"required\\\": True,\\n            \\\"value\\\": \\\"WATSONX_APIKEY\\\",\\n            \\\"load_from_db\\\": True,\\n        },\\n        \\\"project_id\\\": {\\n            \\\"show\\\": True,\\n            \\\"required\\\": True,\\n            \\\"value\\\": \\\"WATSONX_PROJECT_ID\\\",\\n            \\\"load_from_db\\\": True,\\n        },\\n    }\\n    snapshot = ModelProviderPolicySnapshot(\\n        context=ModelProviderPolicyContext(user_id=component.user_id),\\n        purpose=ModelProviderPolicyPurpose.USE,\\n        candidate_provider_ids=frozenset({\\\"openai\\\", \\\"ibm-watsonx\\\"}),\\n        allowed_provider_ids=frozenset({\\\"openai\\\"}),\\n    )\\n\\n    with (\\n        patch(\\\"lfx.services.model_provider_policy.resolve_model_provider_policy\\\", return_value=snapshot),\\n        patch(\\\"lfx.base.models.unified_models.apply_provider_variable_config_to_build_config\\\") as mock_apply,\\n    ):\\n        mock_apply.side_effect = lambda config, _provider: config\\n        result = handle_model_input_update(\\n            component,\\n            build_config,\\n            field_value=\\\"WATSONX_APIKEY\\\",\\n            field_name=\\\"api_key\\\",\\n            get_options_func=lambda user_id=None: openai,  # noqa: ARG005\\n        )\\n\\n    assert result[\\\"model\\\"][\\\"value\\\"] == openai\\n    assert result[\\\"api_key\\\"][\\\"value\\\"] == \\\"\\\"\\n    assert result[\\\"api_key\\\"][\\\"load_from_db\\\"] is False\\n    assert result[\\\"project_id\\\"][\\\"value\\\"] == \\\"\\\"\\n    assert result[\\\"project_id\\\"][\\\"load_from_db\\\"] is False\\n    mock_apply.assert_called_once_with(build_config, \\\"OpenAI\\\")\\n\\n\\ndef test_initial_provider_default_preserves_directly_edited_provider_field():\\n    component = _make_mock_component()\\n    openai = [{\\\"name\\\": \\\"gpt-test\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n    build_config = {\\n        \\\"model\\\": _make_model_field(value=\\\"\\\"),\\n        \\\"api_key\\\": {\\n            \\\"show\\\": True,\\n            \\\"required\\\": True,\\n            \\\"value\\\": \\\"sk-new\\\",  # pragma: allowlist secret\\n            \\\"load_from_db\\\": False,\\n        },\\n    }\\n\\n    result = handle_model_input_update(\\n        component,\\n        build_config,\\n        field_value=\\\"sk-new\\\",  # pragma: allowlist secret\\n        field_name=\\\"api_key\\\",\\n        get_options_func=lambda user_id=None: openai,  # noqa: ARG005\\n    )\\n\\n    assert result[\\\"model\\\"][\\\"value\\\"] == openai\\n    assert result[\\\"api_key\\\"][\\\"value\\\"] == \\\"sk-new\\\"  # pragma: allowlist secret\\n    assert result[\\\"api_key\\\"][\\\"load_from_db\\\"] is False\\n\\n\\ndef test_api_key_refresh_preserves_edit_when_default_provider_is_auto_selected():\\n    component = _make_mock_component()\\n    openai = [{\\\"name\\\": \\\"gpt-test\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n    build_config = {\\n        \\\"model\\\": _make_model_field(),\\n        \\\"api_key\\\": {\\n            \\\"show\\\": True,\\n            \\\"required\\\": True,\\n            \\\"value\\\": \\\"sk-direct-edit\\\",\\n            # Callers outside the MCP path may leave SecretStrInput's default\\n            # database-loading state in place while assigning a literal.\\n            \\\"load_from_db\\\": True,\\n        },\\n        \\\"project_id\\\": {\\n            \\\"show\\\": True,\\n            \\\"required\\\": True,\\n            \\\"value\\\": \\\"STALE_PROJECT_ID\\\",\\n            \\\"load_from_db\\\": True,\\n        },\\n    }\\n\\n    result = handle_model_input_update(\\n        component,\\n        build_config,\\n        field_value=\\\"sk-direct-edit\\\",\\n        field_name=\\\"api_key\\\",\\n        get_options_func=lambda user_id=None: openai,  # noqa: ARG005\\n    )\\n\\n    assert result[\\\"model\\\"][\\\"value\\\"] == openai\\n    assert result[\\\"api_key\\\"][\\\"value\\\"] == \\\"sk-direct-edit\\\"\\n    assert result[\\\"api_key\\\"][\\\"load_from_db\\\"] is True\\n    assert result[\\\"project_id\\\"][\\\"value\\\"] == \\\"\\\"\\n    assert result[\\\"project_id\\\"][\\\"load_from_db\\\"] is False\\n\\n\\ndef test_default_provider_auto_selection_does_not_restore_an_unsupported_edited_field():\\n    component = _make_mock_component()\\n    openai = [{\\\"name\\\": \\\"gpt-test\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n    build_config = {\\n        \\\"model\\\": _make_model_field(),\\n        \\\"project_id\\\": {\\n            \\\"show\\\": True,\\n            \\\"required\\\": True,\\n            \\\"value\\\": \\\"WATSONX_PROJECT_ID\\\",\\n            \\\"load_from_db\\\": True,\\n        },\\n    }\\n\\n    result = handle_model_input_update(\\n        component,\\n        build_config,\\n        field_value=\\\"WATSONX_PROJECT_ID\\\",\\n        field_name=\\\"project_id\\\",\\n        get_options_func=lambda user_id=None: openai,  # noqa: ARG005\\n    )\\n\\n    assert result[\\\"model\\\"][\\\"value\\\"] == openai\\n    assert result[\\\"project_id\\\"][\\\"show\\\"] is False\\n    assert result[\\\"project_id\\\"][\\\"value\\\"] == \\\"\\\"\\n    assert result[\\\"project_id\\\"][\\\"load_from_db\\\"] is False\\n\\n\\ndef test_handle_model_input_update_watsonx_embedding_shows_special_fields():\\n    \\\"\\\"\\\"IBM WatsonX + embedding prefix should show truncate_input_tokens and input_text.\\\"\\\"\\\"\\n    component = _make_mock_component()\\n    selected_model = [{\\\"name\\\": \\\"ibm/slate-125m-english-rtrvr\\\", \\\"provider\\\": \\\"IBM WatsonX\\\", \\\"metadata\\\": {}}]\\n    build_config = {\\n        \\\"model\\\": _make_model_field(value=selected_model),\\n        \\\"truncate_input_tokens\\\": {\\\"show\\\": False},\\n        \\\"input_text\\\": {\\\"show\\\": False},\\n    }\\n\\n    with patch(\\\"lfx.base.models.unified_models.apply_provider_variable_config_to_build_config\\\") as mock_apply:\\n        mock_apply.side_effect = lambda cfg, provider, **kw: cfg  # noqa: ARG005\\n\\n        result = handle_model_input_update(\\n            component,\\n            build_config,\\n            field_value=selected_model,\\n            field_name=\\\"model\\\",\\n            cache_key_prefix=\\\"embedding_model_options\\\",\\n            get_options_func=lambda user_id=None: selected_model,  # noqa: ARG005\\n        )\\n\\n    assert result[\\\"truncate_input_tokens\\\"][\\\"show\\\"] is True\\n    assert result[\\\"input_text\\\"][\\\"show\\\"] is True\\n\\n\\ndef test_handle_model_input_update_non_watsonx_embedding_hides_special_fields():\\n    \\\"\\\"\\\"Non-WatsonX embedding should hide truncate_input_tokens and input_text.\\\"\\\"\\\"\\n    component = _make_mock_component()\\n    selected_model = [{\\\"name\\\": \\\"text-embedding-3-small\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n    build_config = {\\n        \\\"model\\\": _make_model_field(value=selected_model),\\n        \\\"truncate_input_tokens\\\": {\\\"show\\\": True},\\n        \\\"input_text\\\": {\\\"show\\\": True},\\n    }\\n\\n    with patch(\\\"lfx.base.models.unified_models.apply_provider_variable_config_to_build_config\\\") as mock_apply:\\n        mock_apply.side_effect = lambda cfg, provider, **kw: cfg  # noqa: ARG005\\n\\n        result = handle_model_input_update(\\n            component,\\n            build_config,\\n            field_value=selected_model,\\n            field_name=\\\"model\\\",\\n            cache_key_prefix=\\\"embedding_model_options\\\",\\n            get_options_func=lambda user_id=None: selected_model,  # noqa: ARG005\\n        )\\n\\n    assert result[\\\"truncate_input_tokens\\\"][\\\"show\\\"] is False\\n    assert result[\\\"input_text\\\"][\\\"show\\\"] is False\\n\\n\\ndef test_handle_model_input_update_language_model_prefix_skips_embedding_fields():\\n    \\\"\\\"\\\"Language model updates should not toggle truncate_input_tokens/input_text.\\\"\\\"\\\"\\n    component = _make_mock_component()\\n    selected_model = [{\\\"name\\\": \\\"gpt-4\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n    original_show = False\\n    build_config = {\\n        \\\"model\\\": _make_model_field(value=selected_model),\\n        \\\"truncate_input_tokens\\\": {\\\"show\\\": original_show},\\n        \\\"input_text\\\": {\\\"show\\\": original_show},\\n    }\\n\\n    with patch(\\\"lfx.base.models.unified_models.apply_provider_variable_config_to_build_config\\\") as mock_apply:\\n        mock_apply.side_effect = lambda cfg, provider, **kw: cfg  # noqa: ARG005\\n\\n        result = handle_model_input_update(\\n            component,\\n            build_config,\\n            field_value=selected_model,\\n            field_name=\\\"model\\\",\\n            cache_key_prefix=\\\"language_model_options\\\",\\n            get_options_func=lambda user_id=None: selected_model,  # noqa: ARG005\\n        )\\n\\n    # The embedding-specific block should not run for language_model_options\\n    assert result[\\\"truncate_input_tokens\\\"][\\\"show\\\"] is original_show\\n    assert result[\\\"input_text\\\"][\\\"show\\\"] is original_show\\n\\n\\ndef test_handle_model_input_update_returns_dict():\\n    component = _make_mock_component()\\n    build_config = {\\\"model\\\": _make_model_field()}\\n    result = handle_model_input_update(\\n        component,\\n        build_config,\\n        field_value=\\\"\\\",\\n        field_name=None,\\n        get_options_func=lambda user_id=None: [],  # noqa: ARG005\\n    )\\n    assert isinstance(result, dict)\\n\\n\\ndef test_handle_model_input_update_api_key_change_preserves_model_selection():\\n    \\\"\\\"\\\"Changing the api_key field must NOT reset the selected model value.\\n\\n    Regression test: previously, the default-model logic checked ``field_value``\\n    (the api_key text) instead of the model field's own value.  When the api_key\\n    was empty or falsy (e.g. selecting a global variable), the model was\\n    incorrectly reset to the first option.\\n    \\\"\\\"\\\"\\n    component = _make_mock_component()\\n    selected_model = [{\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n    options = [\\n        {\\\"name\\\": \\\"claude-3-opus\\\", \\\"provider\\\": \\\"Anthropic\\\", \\\"metadata\\\": {}},\\n        {\\\"name\\\": \\\"gpt-4o\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}},\\n    ]\\n    build_config = {\\n        \\\"model\\\": _make_model_field(value=selected_model, options=options),\\n        \\\"api_key\\\": {\\\"show\\\": True, \\\"required\\\": True, \\\"value\\\": \\\"old-key\\\"},\\n    }\\n\\n    # Simulate typing a new api_key (non-empty field_value)\\n    result = handle_model_input_update(\\n        component,\\n        build_config,\\n        field_value=\\\"sk-new-key\\\",\\n        field_name=\\\"api_key\\\",\\n        get_options_func=lambda user_id=None: options,  # noqa: ARG005\\n    )\\n    assert result[\\\"model\\\"][\\\"value\\\"] == selected_model, \\\"Model should be preserved when api_key is non-empty\\\"\\n\\n    # Simulate clearing the api_key / selecting a global variable (empty field_value)\\n    build_config2 = {\\n        \\\"model\\\": _make_model_field(value=selected_model, options=options),\\n        \\\"api_key\\\": {\\\"show\\\": True, \\\"required\\\": True, \\\"value\\\": \\\"\\\"},\\n    }\\n    result2 = handle_model_input_update(\\n        component,\\n        build_config2,\\n        field_value=\\\"\\\",\\n        field_name=\\\"api_key\\\",\\n        get_options_func=lambda user_id=None: options,  # noqa: ARG005\\n    )\\n    assert result2[\\\"model\\\"][\\\"value\\\"] == selected_model, \\\"Model should be preserved even when api_key is empty\\\"\\n\\n\\ndef test_handle_model_input_update_custom_model_field_name():\\n    \\\"\\\"\\\"handle_model_input_update should support a custom model_field_name.\\\"\\\"\\\"\\n    component = _make_mock_component()\\n    selected_model = [{\\\"name\\\": \\\"text-embedding-3-small\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n    build_config = {\\n        \\\"embedding_model\\\": {\\n            \\\"value\\\": selected_model,\\n            \\\"options\\\": [],\\n            \\\"input_types\\\": [\\\"Embeddings\\\"],\\n            \\\"show\\\": True,\\n        },\\n    }\\n\\n    with patch(\\\"lfx.base.models.unified_models.apply_provider_variable_config_to_build_config\\\") as mock_apply:\\n        mock_apply.side_effect = lambda cfg, provider, **kw: cfg  # noqa: ARG005\\n\\n        result = handle_model_input_update(\\n            component,\\n            build_config,\\n            field_value=selected_model,\\n            field_name=\\\"embedding_model\\\",\\n            cache_key_prefix=\\\"embedding_model_options\\\",\\n            get_options_func=lambda user_id=None: selected_model,  # noqa: ARG005\\n            model_field_name=\\\"embedding_model\\\",\\n        )\\n\\n        # Should call apply_provider_variable_config with the correct provider\\n        mock_apply.assert_called_once_with(result, \\\"OpenAI\\\")\\n\\n    # Should have updated the embedding_model field\\n    assert \\\"embedding_model\\\" in result\\n\\n\\ndef test_handle_model_input_update_custom_field_name_reads_default_from_correct_field():\\n    \\\"\\\"\\\"When field_name != model_field_name, step 3 should read current value from the custom field.\\\"\\\"\\\"\\n    component = _make_mock_component()\\n    selected_model = [{\\\"name\\\": \\\"gpt-4\\\", \\\"provider\\\": \\\"OpenAI\\\", \\\"metadata\\\": {}}]\\n    build_config = {\\n        \\\"my_model\\\": {\\n            \\\"value\\\": selected_model,\\n            \\\"options\\\": [],\\n            \\\"input_types\\\": [\\\"LanguageModel\\\"],\\n            \\\"show\\\": True,\\n        },\\n    }\\n\\n    with patch(\\\"lfx.base.models.unified_models.apply_provider_variable_config_to_build_config\\\") as mock_apply:\\n        mock_apply.side_effect = lambda cfg, provider, **kw: cfg  # noqa: ARG005\\n\\n        # field_name is \\\"temperature\\\" (not the model field and not a provider-mapped field)\\n        # \u2014 should read from build_config[\\\"my_model\\\"]\\n        result = handle_model_input_update(\\n            component,\\n            build_config,\\n            field_value=0.5,\\n            field_name=\\\"temperature\\\",\\n            get_options_func=lambda user_id=None: [],  # noqa: ARG005\\n            model_field_name=\\\"my_model\\\",\\n        )\\n\\n        mock_apply.assert_called_once_with(result, \\\"OpenAI\\\")\\n\\n\\n# ---------------------------------------------------------------------------\\n# DropdownInput / apply_provider_variable_config_to_build_config tests\\n# ---------------------------------------------------------------------------\\n\\n\\ndef test_apply_provider_config_does_not_populate_empty_fields():\\n    \\\"\\\"\\\"Provider metadata controls visibility without assigning global variables.\\\"\\\"\\\"\\n    build_config = {\\n        \\\"api_key\\\": {\\n            \\\"_input_type\\\": \\\"SecretStrInput\\\",\\n            \\\"value\\\": \\\"\\\",\\n            \\\"show\\\": False,\\n            \\\"required\\\": False,\\n            \\\"advanced\\\": False,\\n            \\\"load_from_db\\\": False,\\n        },\\n        \\\"project_id\\\": {\\n            \\\"_input_type\\\": \\\"StrInput\\\",\\n            \\\"value\\\": \\\"\\\",\\n            \\\"show\\\": False,\\n            \\\"required\\\": False,\\n            \\\"advanced\\\": False,\\n            \\\"load_from_db\\\": False,\\n        },\\n        \\\"base_url_ibm_watsonx\\\": {\\n            \\\"_input_type\\\": \\\"DropdownInput\\\",\\n            \\\"value\\\": \\\"\\\",\\n            \\\"options\\\": [\\n                \\\"https://us-south.ml.cloud.ibm.com\\\",\\n                \\\"https://eu-de.ml.cloud.ibm.com\\\",\\n            ],\\n            \\\"show\\\": False,\\n            \\\"required\\\": False,\\n            \\\"advanced\\\": False,\\n            \\\"load_from_db\\\": False,\\n        },\\n    }\\n\\n    result = apply_provider_variable_config_to_build_config(build_config, \\\"IBM WatsonX\\\")\\n\\n    assert result[\\\"api_key\\\"][\\\"load_from_db\\\"] is False\\n    assert result[\\\"api_key\\\"][\\\"value\\\"] == \\\"\\\"\\n\\n    assert result[\\\"project_id\\\"][\\\"load_from_db\\\"] is False\\n    assert result[\\\"project_id\\\"][\\\"value\\\"] == \\\"\\\"\\n\\n    # DropdownInput should NOT have load_from_db set\\n    assert result[\\\"base_url_ibm_watsonx\\\"][\\\"load_from_db\\\"] is False\\n    # Value should remain empty (not set to \\\"WATSONX_URL\\\")\\n    assert result[\\\"base_url_ibm_watsonx\\\"][\\\"value\\\"] == \\\"\\\"\\n    # But the field should still be shown\\n    assert result[\\\"base_url_ibm_watsonx\\\"][\\\"show\\\"] is True\\n\\n\\ndef test_apply_provider_config_preserves_explicit_global_variable():\\n    \\\"\\\"\\\"Provider refreshes must honor an explicitly assigned global variable.\\\"\\\"\\\"\\n    build_config = {\\n        \\\"api_key\\\": {\\n            \\\"_input_type\\\": \\\"SecretStrInput\\\",\\n            \\\"value\\\": \\\"ANTHROPIC_API_KEY\\\",\\n            \\\"show\\\": False,\\n            \\\"required\\\": False,\\n            \\\"advanced\\\": False,\\n            \\\"load_from_db\\\": True,\\n        },\\n    }\\n\\n    result = apply_provider_variable_config_to_build_config(build_config, \\\"OpenAI\\\")\\n\\n    assert result[\\\"api_key\\\"][\\\"value\\\"] == \\\"ANTHROPIC_API_KEY\\\"\\n    assert result[\\\"api_key\\\"][\\\"load_from_db\\\"] is True\\n    assert result[\\\"api_key\\\"][\\\"show\\\"] is True\\n\\n\\ndef test_apply_provider_config_preserves_user_typed_credential():\\n    \\\"\\\"\\\"User-typed credentials should survive provider config refreshes.\\\"\\\"\\\"\\n    build_config = {\\n        \\\"api_key\\\": {\\n            \\\"_input_type\\\": \\\"SecretStrInput\\\",\\n            \\\"value\\\": \\\"sk-raw-key-123\\\",\\n            \\\"show\\\": False,\\n            \\\"required\\\": False,\\n            \\\"advanced\\\": False,\\n            \\\"load_from_db\\\": False,\\n        },\\n    }\\n\\n    result = apply_provider_variable_config_to_build_config(build_config, \\\"OpenAI\\\")\\n\\n    assert result[\\\"api_key\\\"][\\\"value\\\"] == \\\"sk-raw-key-123\\\"\\n    assert result[\\\"api_key\\\"][\\\"load_from_db\\\"] is False\\n    assert result[\\\"api_key\\\"][\\\"show\\\"] is True\\n\\n\\ndef test_apply_provider_config_keeps_current_provider_variable_on_refresh():\\n    \\\"\\\"\\\"Refreshing the same provider should not rewrite an already-correct variable key.\\\"\\\"\\\"\\n    build_config = {\\n        \\\"api_key\\\": {\\n            \\\"_input_type\\\": \\\"SecretStrInput\\\",\\n            \\\"value\\\": \\\"OPENAI_API_KEY\\\",\\n            \\\"show\\\": False,\\n            \\\"required\\\": False,\\n            \\\"advanced\\\": False,\\n            \\\"load_from_db\\\": True,\\n        },\\n    }\\n\\n    result = apply_provider_variable_config_to_build_config(build_config, \\\"OpenAI\\\")\\n\\n    assert result[\\\"api_key\\\"][\\\"value\\\"] == \\\"OPENAI_API_KEY\\\"\\n    assert result[\\\"api_key\\\"][\\\"load_from_db\\\"] is True\\n    assert result[\\\"api_key\\\"][\\\"show\\\"] is True\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_all_variables_for_provider\\\")\\ndef test_resolve_dropdown_provider_values_sets_resolved_url(mock_get_vars):\\n    \\\"\\\"\\\"_resolve_dropdown_provider_values should set the resolved URL on dropdown fields.\\\"\\\"\\\"\\n    mock_get_vars.return_value = {\\\"WATSONX_URL\\\": \\\"https://eu-de.ml.cloud.ibm.com\\\"}\\n\\n    build_config = {\\n        \\\"base_url_ibm_watsonx\\\": {\\n            \\\"_input_type\\\": \\\"DropdownInput\\\",\\n            \\\"value\\\": \\\"\\\",\\n            \\\"options\\\": [\\n                \\\"https://us-south.ml.cloud.ibm.com\\\",\\n                \\\"https://eu-de.ml.cloud.ibm.com\\\",\\n            ],\\n            \\\"show\\\": True,\\n            \\\"load_from_db\\\": False,\\n        },\\n        \\\"api_key\\\": {\\n            \\\"_input_type\\\": \\\"SecretStrInput\\\",\\n            \\\"value\\\": \\\"WATSONX_APIKEY\\\",\\n            \\\"show\\\": True,\\n            \\\"load_from_db\\\": True,\\n        },\\n    }\\n\\n    _resolve_dropdown_provider_values(\\\"user-123\\\", build_config, \\\"IBM WatsonX\\\")\\n\\n    # Dropdown should get the resolved URL\\n    assert build_config[\\\"base_url_ibm_watsonx\\\"][\\\"value\\\"] == \\\"https://eu-de.ml.cloud.ibm.com\\\"\\n    assert build_config[\\\"base_url_ibm_watsonx\\\"][\\\"load_from_db\\\"] is False\\n\\n    # Non-dropdown fields should not be touched\\n    assert build_config[\\\"api_key\\\"][\\\"value\\\"] == \\\"WATSONX_APIKEY\\\"\\n    assert build_config[\\\"api_key\\\"][\\\"load_from_db\\\"] is True\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_all_variables_for_provider\\\")\\ndef test_resolve_dropdown_provider_values_falls_back_to_first_option(mock_get_vars):\\n    \\\"\\\"\\\"When the variable can't be resolved, fall back to the first dropdown option.\\\"\\\"\\\"\\n    mock_get_vars.return_value = {}  # No variables configured\\n\\n    build_config = {\\n        \\\"base_url_ibm_watsonx\\\": {\\n            \\\"_input_type\\\": \\\"DropdownInput\\\",\\n            \\\"value\\\": \\\"\\\",\\n            \\\"options\\\": [\\n                \\\"https://us-south.ml.cloud.ibm.com\\\",\\n                \\\"https://eu-de.ml.cloud.ibm.com\\\",\\n            ],\\n            \\\"show\\\": True,\\n            \\\"load_from_db\\\": False,\\n        },\\n    }\\n\\n    _resolve_dropdown_provider_values(\\\"user-123\\\", build_config, \\\"IBM WatsonX\\\")\\n\\n    # Should fall back to first option\\n    assert build_config[\\\"base_url_ibm_watsonx\\\"][\\\"value\\\"] == \\\"https://us-south.ml.cloud.ibm.com\\\"\\n    assert build_config[\\\"base_url_ibm_watsonx\\\"][\\\"load_from_db\\\"] is False\\n\\n\\n@patch(\\\"lfx.base.models.unified_models.get_all_variables_for_provider\\\")\\ndef test_resolve_dropdown_skips_non_dropdown_fields(mock_get_vars):\\n    \\\"\\\"\\\"Non-DropdownInput fields should not be touched by _resolve_dropdown_provider_values.\\\"\\\"\\\"\\n    mock_get_vars.return_value = {\\\"WATSONX_APIKEY\\\": \\\"secret-key\\\"}  # pragma: allowlist secret\\n\\n    build_config = {\\n        \\\"api_key\\\": {\\n            \\\"_input_type\\\": \\\"SecretStrInput\\\",\\n            \\\"value\\\": \\\"WATSONX_APIKEY\\\",\\n            \\\"show\\\": True,\\n            \\\"load_from_db\\\": True,\\n        },\\n    }\\n\\n    _resolve_dropdown_provider_values(\\\"user-123\\\", build_config, \\\"IBM WatsonX\\\")\\n\\n    # Should not modify non-dropdown fields\\n    assert build_config[\\\"api_key\\\"][\\\"value\\\"] == \\\"WATSONX_APIKEY\\\"\\n    assert build_config[\\\"api_key\\\"][\\\"load_from_db\\\"] is True\\n\\n\\ndef test_handle_model_input_update_resolves_watsonx_dropdown():\\n    \\\"\\\"\\\"End-to-end: selecting a WatsonX model should resolve the dropdown URL.\\\"\\\"\\\"\\n    component = _make_mock_component()\\n    component.user_id = \\\"test-user-id\\\"\\n    selected_model = [{\\\"name\\\": \\\"ibm/granite-3-8b-instruct\\\", \\\"provider\\\": \\\"IBM WatsonX\\\", \\\"metadata\\\": {}}]\\n    build_config = {\\n        \\\"model\\\": _make_model_field(value=selected_model),\\n        \\\"api_key\\\": {\\n            \\\"_input_type\\\": \\\"SecretStrInput\\\",\\n            \\\"value\\\": \\\"\\\",\\n            \\\"show\\\": False,\\n            \\\"required\\\": False,\\n            \\\"advanced\\\": False,\\n            \\\"load_from_db\\\": False,\\n        },\\n        \\\"project_id\\\": {\\n            \\\"_input_type\\\": \\\"StrInput\\\",\\n            \\\"value\\\": \\\"\\\",\\n            \\\"show\\\": False,\\n            \\\"required\\\": False,\\n            \\\"advanced\\\": False,\\n            \\\"load_from_db\\\": False,\\n        },\\n        \\\"base_url_ibm_watsonx\\\": {\\n            \\\"_input_type\\\": \\\"DropdownInput\\\",\\n            \\\"value\\\": \\\"https://us-south.ml.cloud.ibm.com\\\",\\n            \\\"options\\\": [\\n                \\\"https://us-south.ml.cloud.ibm.com\\\",\\n                \\\"https://eu-de.ml.cloud.ibm.com\\\",\\n            ],\\n            \\\"show\\\": False,\\n            \\\"required\\\": False,\\n            \\\"advanced\\\": False,\\n            \\\"load_from_db\\\": False,\\n        },\\n    }\\n\\n    with patch(\\\"lfx.base.models.unified_models.get_all_variables_for_provider\\\") as mock_get_vars:\\n        mock_get_vars.return_value = {\\\"WATSONX_URL\\\": \\\"https://eu-de.ml.cloud.ibm.com\\\"}\\n\\n        result = handle_model_input_update(\\n            component,\\n            build_config,\\n            field_value=selected_model,\\n            field_name=\\\"model\\\",\\n            get_options_func=lambda user_id=None: selected_model,  # noqa: ARG005\\n        )\\n\\n    # The dropdown should be resolved to the configured URL, not \\\"WATSONX_URL\\\"\\n    assert result[\\\"base_url_ibm_watsonx\\\"][\\\"value\\\"] == \\\"https://eu-de.ml.cloud.ibm.com\\\"\\n    assert result[\\\"base_url_ibm_watsonx\\\"][\\\"load_from_db\\\"] is False\\n    assert result[\\\"base_url_ibm_watsonx\\\"][\\\"show\\\"] is True\\n\\n    # Non-dropdown fields stay empty and resolve from Model Providers at runtime.\\n    assert result[\\\"api_key\\\"][\\\"value\\\"] == \\\"\\\"\\n    assert result[\\\"api_key\\\"][\\\"load_from_db\\\"] is False\\n    assert result[\\\"project_id\\\"][\\\"value\\\"] == \\\"\\\"\\n    assert result[\\\"project_id\\\"][\\\"load_from_db\\\"] is False\\n\\n\\ndef test_get_provider_for_model_name_backwards_compat():\\n    \\\"\\\"\\\"Ensure ``get_provider_for_model_name`` stays importable from the package root.\\n\\n    Flows exported from 1.8.x import this helper directly from\\n    ``lfx.base.models.unified_models``. The post-refactor package split broke\\n    that import; this test guards against reintroducing the regression.\\n    \\\"\\\"\\\"\\n    from lfx.base.models.unified_models import get_provider_for_model_name\\n\\n    # Known model round-trips to its provider.\\n    assert get_provider_for_model_name(\\\"gpt-4o\\\") == \\\"OpenAI\\\"\\n\\n    # Defensive inputs must not raise.\\n    assert get_provider_for_model_name(\\\"\\\") == \\\"\\\"\\n    assert get_provider_for_model_name(\\\"__definitely_not_a_real_model__\\\") == \\\"\\\"\\n    assert get_provider_for_model_name(None) == \\\"\\\"  # type: ignore[arg-type]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_user.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"892e0de6043fe01b58cd3c0f4bb3a45f44f21b09eab88e33fcb430599482daa2\",\"content\":\"from datetime import datetime, timezone\\n\\nimport pytest\\nfrom httpx import AsyncClient\\nfrom langflow.services.auth.utils import create_super_user, get_password_hash\\nfrom langflow.services.database.models.file.model import File\\nfrom langflow.services.database.models.user import UserUpdate\\nfrom langflow.services.database.models.user.model import User\\nfrom langflow.services.database.utils import session_getter\\nfrom langflow.services.deps import get_db_service, get_settings_service\\nfrom lfx.services.settings.constants import DEFAULT_SUPERUSER\\nfrom sqlalchemy import text\\nfrom sqlmodel import select\\n\\nCURRENT_CREDENTIAL = \\\"test\\\" + \\\"password\\\"\\nREPLACEMENT_CREDENTIAL = \\\"new\\\" + \\\"password\\\"\\n\\n\\n@pytest.fixture\\nasync def super_user(client):  # noqa: ARG001\\n    settings_manager = get_settings_service()\\n    auth_settings = settings_manager.auth_settings\\n    async with session_getter(get_db_service()) as db:\\n        return await create_super_user(\\n            db=db,\\n            username=auth_settings.SUPERUSER,\\n            password=(\\n                auth_settings.SUPERUSER_PASSWORD.get_secret_value()\\n                if hasattr(auth_settings.SUPERUSER_PASSWORD, \\\"get_secret_value\\\")\\n                else auth_settings.SUPERUSER_PASSWORD\\n            ),\\n        )\\n\\n\\n@pytest.fixture\\nasync def super_user_headers(\\n    client: AsyncClient,\\n    super_user,  # noqa: ARG001\\n):\\n    settings_service = get_settings_service()\\n    auth_settings = settings_service.auth_settings\\n    login_data = {\\n        # SUPERUSER may be reset to default depending on AUTO_LOGIN; use constant for stability in tests\\n        \\\"username\\\": DEFAULT_SUPERUSER if auth_settings.AUTO_LOGIN else auth_settings.SUPERUSER,\\n        \\\"password\\\": (\\n            auth_settings.SUPERUSER_PASSWORD.get_secret_value()\\n            if hasattr(auth_settings.SUPERUSER_PASSWORD, \\\"get_secret_value\\\")\\n            else auth_settings.SUPERUSER_PASSWORD\\n        ),\\n    }\\n    response = await client.post(\\\"api/v1/login\\\", data=login_data)\\n    assert response.status_code == 200\\n    tokens = response.json()\\n    a_token = tokens[\\\"access_token\\\"]\\n    return {\\\"Authorization\\\": f\\\"Bearer {a_token}\\\"}\\n\\n\\n@pytest.fixture\\nasync def deactivated_user(client):  # noqa: ARG001\\n    async with session_getter(get_db_service()) as session:\\n        user = User(\\n            username=\\\"deactivateduser\\\",\\n            password=get_password_hash(\\\"testpassword\\\"),\\n            is_active=False,\\n            is_superuser=False,\\n            last_login_at=datetime.now(tz=timezone.utc),\\n        )\\n        session.add(user)\\n        await session.commit()\\n        await session.refresh(user)\\n    return user\\n\\n\\nasync def test_user_waiting_for_approval(client):\\n    username = \\\"waitingforapproval\\\"\\n    password = \\\"testpassword\\\"  # noqa: S105\\n\\n    # Debug: Check if the user already exists\\n    async with session_getter(get_db_service()) as session:\\n        stmt = select(User).where(User.username == username)\\n        existing_user = (await session.exec(stmt)).first()\\n        if existing_user:\\n            pytest.fail(\\n                f\\\"User {username} already exists before the test. Database URL: {get_db_service().database_url}\\\"\\n            )\\n\\n    # Create a user that is not active and has never logged in\\n    async with session_getter(get_db_service()) as session:\\n        user = User(\\n            username=username,\\n            password=get_password_hash(password),\\n            is_active=False,\\n            last_login_at=None,\\n        )\\n        session.add(user)\\n        await session.commit()\\n\\n    login_data = {\\\"username\\\": \\\"waitingforapproval\\\", \\\"password\\\": \\\"testpassword\\\"}\\n    response = await client.post(\\\"api/v1/login\\\", data=login_data)\\n    assert response.status_code == 400\\n    assert response.json()[\\\"detail\\\"] == \\\"Waiting for approval\\\"\\n\\n    # Debug: Check if the user still exists after the test\\n    async with session_getter(get_db_service()) as session:\\n        stmt = select(User).where(User.username == username)\\n        existing_user = (await session.exec(stmt)).first()\\n        if existing_user:\\n            pass\\n        else:\\n            pytest.fail(f\\\"User {username} does not exist after the test. This is unexpected.\\\")\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_deactivated_user_cannot_login(client: AsyncClient, deactivated_user):\\n    login_data = {\\\"username\\\": deactivated_user.username, \\\"password\\\": \\\"testpassword\\\"}\\n    response = await client.post(\\\"api/v1/login\\\", data=login_data)\\n    assert response.status_code == 401, response.json()\\n    assert response.json()[\\\"detail\\\"] == \\\"Inactive user\\\", response.text\\n\\n\\n@pytest.mark.usefixtures(\\\"deactivated_user\\\")\\nasync def test_deactivated_user_cannot_access(client: AsyncClient, logged_in_headers):\\n    # Assuming the headers for deactivated_user\\n    response = await client.get(\\\"api/v1/users/\\\", headers=logged_in_headers)\\n    assert response.status_code == 403, response.status_code\\n    assert response.json()[\\\"detail\\\"] == \\\"The user doesn't have enough privileges\\\", response.text\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_data_consistency_after_update(client: AsyncClient, active_user, logged_in_headers, super_user_headers):\\n    user_id = active_user.id\\n    update_data = UserUpdate(is_active=False)\\n\\n    response = await client.patch(f\\\"/api/v1/users/{user_id}\\\", json=update_data.model_dump(), headers=super_user_headers)\\n    assert response.status_code == 200, response.json()\\n\\n    # Fetch the updated user from the database\\n    response = await client.get(\\\"api/v1/users/whoami\\\", headers=logged_in_headers)\\n    assert response.status_code == 401, response.json()\\n    assert response.json()[\\\"detail\\\"] == \\\"User not found or is inactive.\\\"\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_data_consistency_after_delete(client: AsyncClient, test_user, super_user_headers):\\n    user_id = test_user.get(\\\"id\\\")\\n    response = await client.delete(f\\\"/api/v1/users/{user_id}\\\", headers=super_user_headers)\\n    assert response.status_code == 200, response.json()\\n\\n    # Attempt to fetch the deleted user from the database\\n    response = await client.get(\\\"api/v1/users/\\\", headers=super_user_headers)\\n    assert response.status_code == 200\\n    assert all(user[\\\"id\\\"] != user_id for user in response.json()[\\\"users\\\"])\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_inactive_user(client: AsyncClient):\\n    # Create a user that is not active and has a last_login_at value\\n    async with session_getter(get_db_service()) as session:\\n        user = User(\\n            username=\\\"inactiveuser\\\",\\n            password=get_password_hash(\\\"testpassword\\\"),\\n            is_active=False,\\n            last_login_at=datetime(2023, 1, 1, 0, 0, 0, tzinfo=timezone.utc),\\n        )\\n        session.add(user)\\n        await session.commit()\\n\\n    login_data = {\\\"username\\\": \\\"inactiveuser\\\", \\\"password\\\": \\\"testpassword\\\"}\\n    response = await client.post(\\\"api/v1/login\\\", data=login_data)\\n    assert response.status_code == 401\\n    assert response.json()[\\\"detail\\\"] == \\\"Inactive user\\\"\\n\\n\\n@pytest.mark.api_key_required\\ndef test_add_user(test_user):\\n    assert test_user[\\\"username\\\"] == \\\"testuser\\\"\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_read_all_users(client: AsyncClient, super_user_headers):\\n    response = await client.get(\\\"api/v1/users/\\\", headers=super_user_headers)\\n    assert response.status_code == 200, response.json()\\n    assert isinstance(response.json()[\\\"users\\\"], list)\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_normal_user_cant_read_all_users(client: AsyncClient, logged_in_headers):\\n    response = await client.get(\\\"api/v1/users/\\\", headers=logged_in_headers)\\n    assert response.status_code == 403, response.json()\\n    assert response.json() == {\\\"detail\\\": \\\"The user doesn't have enough privileges\\\"}\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_patch_user(client: AsyncClient, active_user, logged_in_headers):\\n    user_id = active_user.id\\n    update_data = UserUpdate(\\n        username=\\\"newname\\\",\\n    )\\n\\n    response = await client.patch(f\\\"/api/v1/users/{user_id}\\\", json=update_data.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 200, response.json()\\n    update_data = UserUpdate(\\n        profile_image=\\\"new_image\\\",\\n    )\\n\\n    response = await client.patch(f\\\"/api/v1/users/{user_id}\\\", json=update_data.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 200, response.json()\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_patch_reset_password(client: AsyncClient, active_user, logged_in_headers):\\n    user_id = active_user.id\\n    update_data = {\\n        \\\"current_password\\\": CURRENT_CREDENTIAL,\\n        \\\"password\\\": REPLACEMENT_CREDENTIAL,\\n    }\\n\\n    response = await client.patch(\\n        f\\\"/api/v1/users/{user_id}/reset-password\\\",\\n        json=update_data,\\n        headers=logged_in_headers,\\n    )\\n    assert response.status_code == 200, response.json()\\n    # Now we need to test if the new password works\\n    login_data = {\\\"username\\\": active_user.username, \\\"password\\\": REPLACEMENT_CREDENTIAL}\\n    response = await client.post(\\\"api/v1/login\\\", data=login_data)\\n    assert response.status_code == 200\\n\\n\\n@pytest.mark.api_key_required\\n@pytest.mark.usefixtures(\\\"active_user\\\")\\nasync def test_patch_user_wrong_id(client: AsyncClient, logged_in_headers):\\n    user_id = \\\"wrong_id\\\"\\n    update_data = UserUpdate(\\n        username=\\\"newname\\\",\\n    )\\n\\n    response = await client.patch(f\\\"/api/v1/users/{user_id}\\\", json=update_data.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 422, response.json()\\n    json_response = response.json()\\n    detail = json_response[\\\"detail\\\"]\\n    error = detail[0]\\n    assert error[\\\"loc\\\"] == [\\\"path\\\", \\\"user_id\\\"]\\n    assert error[\\\"type\\\"] == \\\"uuid_parsing\\\"\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_delete_user(client: AsyncClient, test_user, super_user_headers):\\n    user_id = test_user[\\\"id\\\"]\\n    response = await client.delete(f\\\"/api/v1/users/{user_id}\\\", headers=super_user_headers)\\n    assert response.status_code == 200\\n    assert response.json() == {\\\"detail\\\": \\\"User deleted\\\"}\\n\\n\\n@pytest.mark.api_key_required\\n@pytest.mark.usefixtures(\\\"test_user\\\")\\nasync def test_delete_user_wrong_id(client: AsyncClient, super_user_headers):\\n    user_id = \\\"wrong_id\\\"\\n    response = await client.delete(f\\\"/api/v1/users/{user_id}\\\", headers=super_user_headers)\\n    assert response.status_code == 422\\n    json_response = response.json()\\n    detail = json_response[\\\"detail\\\"]\\n    error = detail[0]\\n    assert error[\\\"loc\\\"] == [\\\"path\\\", \\\"user_id\\\"]\\n    assert error[\\\"type\\\"] == \\\"uuid_parsing\\\"\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_delete_user_cascades_to_files(client: AsyncClient, test_user, super_user_headers):  # noqa: ARG001\\n    \\\"\\\"\\\"Deleting a user should cascade-delete associated file records (e.g. _mcp_servers).\\\"\\\"\\\"\\n    user_id = test_user[\\\"id\\\"]\\n\\n    # Create a file record owned by the user\\n    import tempfile\\n\\n    async with session_getter(get_db_service()) as session:\\n        with tempfile.TemporaryDirectory() as tmpdirname:\\n            file_path = f\\\"{tmpdirname}/{user_id}\\\"\\n            file = File(user_id=user_id, name=f\\\"_mcp_servers_{user_id}.json\\\", path=file_path, size=42)\\n            session.add(file)\\n            await session.commit()\\n            file_id = file.id\\n\\n    # Verify the file exists\\n    async with session_getter(get_db_service()) as session:\\n        assert await session.get(File, file_id) is not None\\n\\n    # Delete the user using a Core-level bulk DELETE to bypass ORM relationship cascades\\n    async with session_getter(get_db_service()) as session:\\n        from sqlalchemy import delete\\n\\n        await session.exec(delete(User).where(User.id == user_id))\\n        await session.commit()\\n\\n    # Verify the file was cascade-deleted by the database FK\\n    async with session_getter(get_db_service()) as session:\\n        assert await session.get(File, file_id) is None\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_delete_user_db_level_cascade(client):  # noqa: ARG001\\n    \\\"\\\"\\\"Raw SQL DELETE on users should cascade-delete File rows via DB-level ON DELETE CASCADE.\\\"\\\"\\\"\\n    import tempfile\\n\\n    # Create a user and an associated file\\n    async with session_getter(get_db_service()) as session:\\n        user = User(\\n            username=\\\"cascade_test_user\\\",\\n            password=get_password_hash(\\\"testpassword\\\"),\\n            is_active=True,\\n            last_login_at=datetime.now(tz=timezone.utc),\\n        )\\n        session.add(user)\\n        await session.commit()\\n        await session.refresh(user)\\n        user_id = user.id\\n\\n        with tempfile.TemporaryDirectory() as tmpdirname:\\n            file_path = f\\\"{tmpdirname}/{user_id}\\\"\\n            file = File(user_id=user_id, name=f\\\"_mcp_servers_{user_id}.json\\\", path=file_path, size=42)\\n            session.add(file)\\n            await session.commit()\\n            await session.refresh(file)\\n            file_id = file.id\\n\\n    # Verify the file exists before deletion\\n    async with session_getter(get_db_service()) as session:\\n        assert await session.get(File, file_id) is not None\\n\\n    # Delete the user via raw SQL (bypasses ORM cascade, tests DB-level ON DELETE CASCADE)\\n    db_service = get_db_service()\\n    async with db_service.engine.connect() as conn:\\n        await conn.execute(text(\\\"PRAGMA foreign_keys = ON\\\"))\\n        await conn.execute(text('DELETE FROM \\\"user\\\" WHERE id = :id'), {\\\"id\\\": str(user_id)})\\n        await conn.commit()\\n\\n    # Verify the file was cascade-deleted at the DB level (use a fresh session to avoid cache)\\n    async with db_service.engine.connect() as conn:\\n        result = await conn.execute(text(\\\"SELECT id FROM file WHERE id = :id\\\"), {\\\"id\\\": str(file_id)})\\n        assert result.first() is None\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_normal_user_cant_delete_user(client: AsyncClient, test_user, logged_in_headers):\\n    user_id = test_user[\\\"id\\\"]\\n    response = await client.delete(f\\\"/api/v1/users/{user_id}\\\", headers=logged_in_headers)\\n    assert response.status_code == 403\\n    assert response.json() == {\\\"detail\\\": \\\"Permission denied\\\"}\\n\\n\\n# ==================== Profile Picture Tests ====================\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_user_can_update_profile_picture(client: AsyncClient, active_user, logged_in_headers):\\n    \\\"\\\"\\\"Test that a user can update their profile picture.\\\"\\\"\\\"\\n    user_id = active_user.id\\n    profile_image = \\\"Space/046-rocket.svg\\\"\\n    update_data = UserUpdate(profile_image=profile_image)\\n\\n    response = await client.patch(f\\\"/api/v1/users/{user_id}\\\", json=update_data.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 200, f\\\"Failed to update profile picture: {response.json()}\\\"\\n\\n    # Verify the profile image was updated\\n    response = await client.get(\\\"api/v1/users/whoami\\\", headers=logged_in_headers)\\n    assert response.status_code == 200\\n    user_data = response.json()\\n    assert user_data[\\\"profile_image\\\"] == profile_image\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_user_profile_picture_persists(client: AsyncClient, active_user, logged_in_headers):\\n    \\\"\\\"\\\"Test that profile picture persists across requests.\\\"\\\"\\\"\\n    user_id = active_user.id\\n    profile_image = \\\"People/001-man.svg\\\"\\n    update_data = UserUpdate(profile_image=profile_image)\\n\\n    # Update profile picture\\n    response = await client.patch(f\\\"/api/v1/users/{user_id}\\\", json=update_data.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 200\\n\\n    # Check it persists in multiple requests\\n    for _ in range(3):\\n        response = await client.get(\\\"api/v1/users/whoami\\\", headers=logged_in_headers)\\n        assert response.status_code == 200\\n        assert response.json()[\\\"profile_image\\\"] == profile_image\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_user_can_change_profile_picture_multiple_times(client: AsyncClient, active_user, logged_in_headers):\\n    \\\"\\\"\\\"Test that a user can change their profile picture multiple times.\\\"\\\"\\\"\\n    user_id = active_user.id\\n    profile_images = [\\n        \\\"Space/046-rocket.svg\\\",\\n        \\\"People/001-man.svg\\\",\\n        \\\"Space/001-asteroid.svg\\\",\\n    ]\\n\\n    for profile_image in profile_images:\\n        update_data = UserUpdate(profile_image=profile_image)\\n        response = await client.patch(\\n            f\\\"/api/v1/users/{user_id}\\\", json=update_data.model_dump(), headers=logged_in_headers\\n        )\\n        assert response.status_code == 200\\n\\n        # Verify the update\\n        response = await client.get(\\\"api/v1/users/whoami\\\", headers=logged_in_headers)\\n        assert response.status_code == 200\\n        assert response.json()[\\\"profile_image\\\"] == profile_image\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_profile_pictures_endpoint_returns_files(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Test that the profile pictures list endpoint returns files after app startup.\\\"\\\"\\\"\\n    response = await client.get(\\\"api/v1/files/profile_pictures/list\\\", headers=logged_in_headers)\\n\\n    assert response.status_code == 200, f\\\"Expected 200, got {response.status_code}: {response.json()}\\\"\\n\\n    data = response.json()\\n    assert \\\"files\\\" in data\\n    files = data[\\\"files\\\"]\\n\\n    # After the fix, profile pictures should be available\\n    assert len(files) > 0, \\\"Profile pictures list should not be empty after app startup\\\"\\n    assert any(\\\"Space/\\\" in f for f in files), \\\"Should have Space category profile pictures\\\"\\n    assert any(\\\"People/\\\" in f for f in files), \\\"Should have People category profile pictures\\\"\\n\\n\\n@pytest.mark.api_key_required\\nasync def test_profile_picture_image_can_be_accessed(client: AsyncClient, logged_in_headers):\\n    \\\"\\\"\\\"Test that profile picture images can be accessed/downloaded.\\\"\\\"\\\"\\n    # First get the list of available profile pictures\\n    response = await client.get(\\\"api/v1/files/profile_pictures/list\\\", headers=logged_in_headers)\\n    assert response.status_code == 200\\n\\n    files = response.json()[\\\"files\\\"]\\n    assert len(files) > 0, \\\"Should have profile pictures available\\\"\\n\\n    # Try to access the first profile picture\\n    first_file = files[0]\\n    folder, filename = first_file.split(\\\"/\\\", 1)\\n\\n    response = await client.get(f\\\"api/v1/files/profile_pictures/{folder}/{filename}\\\", headers=logged_in_headers)\\n    assert response.status_code == 200, f\\\"Failed to access profile picture: {first_file}\\\"\\n    assert len(response.content) > 0, \\\"Profile picture should have content\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_validate_code.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5ba4a9b7ef1b5545b603125410b0705844cf66a121994e5db1848d5c3d7faf5d\",\"content\":\"from pathlib import Path\\nfrom unittest import mock\\n\\nimport pytest\\nfrom langflow.utils.validate import (\\n    create_class,\\n    create_function,\\n    execute_function,\\n    extract_function_name,\\n    validate_code,\\n)\\nfrom requests.exceptions import MissingSchema\\n\\n\\ndef test_create_function():\\n    code = \\\"\\\"\\\"\\nfrom pathlib import Path\\n\\ndef my_function(x: str) -> Path:\\n    return Path(x)\\n\\\"\\\"\\\"\\n\\n    function_name = extract_function_name(code)\\n    function = create_function(code, function_name)\\n    result = function(\\\"test\\\")\\n    assert result == Path(\\\"test\\\")\\n\\n\\ndef test_validate_code():\\n    # Test case with a valid import and function\\n    code1 = \\\"\\\"\\\"\\nimport math\\n\\ndef square(x):\\n    return x ** 2\\n\\\"\\\"\\\"\\n    errors1 = validate_code(code1)\\n    assert errors1 == {\\\"imports\\\": {\\\"errors\\\": []}, \\\"function\\\": {\\\"errors\\\": []}}\\n\\n    # Test case with an invalid import and valid function\\n    code2 = \\\"\\\"\\\"\\nimport non_existent_module\\n\\ndef square(x):\\n    return x ** 2\\n\\\"\\\"\\\"\\n    errors2 = validate_code(code2)\\n    assert errors2 == {\\n        \\\"imports\\\": {\\\"errors\\\": [\\\"No module named 'non_existent_module'\\\"]},\\n        \\\"function\\\": {\\\"errors\\\": []},\\n    }\\n\\n    # Test case with a valid import and invalid function syntax\\n    code3 = \\\"\\\"\\\"\\nimport math\\n\\ndef square(x)\\n    return x ** 2\\n\\\"\\\"\\\"\\n    errors3 = validate_code(code3)\\n    assert errors3 == {\\n        \\\"imports\\\": {\\\"errors\\\": []},\\n        \\\"function\\\": {\\\"errors\\\": [\\\"expected ':' (<unknown>, line 4)\\\"]},\\n    }\\n\\n\\ndef test_execute_function_success():\\n    code = \\\"\\\"\\\"\\nimport math\\n\\ndef my_function(x):\\n    return math.sin(x) + 1\\n    \\\"\\\"\\\"\\n    result = execute_function(code, \\\"my_function\\\", 0.5)\\n    assert result == 1.479425538604203\\n\\n\\ndef test_execute_function_missing_module():\\n    code = \\\"\\\"\\\"\\nimport some_missing_module\\n\\ndef my_function(x):\\n    return some_missing_module.some_function(x)\\n    \\\"\\\"\\\"\\n    with pytest.raises(ModuleNotFoundError):\\n        execute_function(code, \\\"my_function\\\", 0.5)\\n\\n\\ndef test_execute_function_missing_function():\\n    code = \\\"\\\"\\\"\\nimport math\\n\\ndef my_function(x):\\n    return math.some_missing_function(x)\\n    \\\"\\\"\\\"\\n    with pytest.raises(AttributeError):\\n        execute_function(code, \\\"my_function\\\", 0.5)\\n\\n\\ndef test_execute_function_missing_schema():\\n    code = \\\"\\\"\\\"\\nimport requests\\n\\ndef my_function(x):\\n    return requests.get(x).text\\n    \\\"\\\"\\\"\\n    with mock.patch(\\\"requests.get\\\", side_effect=MissingSchema), pytest.raises(MissingSchema):\\n        execute_function(code, \\\"my_function\\\", \\\"invalid_url\\\")\\n\\n\\ndef test_create_class():\\n    code = \\\"\\\"\\\"\\nfrom langflow.custom import CustomComponent\\n\\nclass ExternalClass:\\n    def __init__(self, value):\\n        self.value = value\\n\\nclass MyComponent(CustomComponent):\\n    def build(self):\\n        return ExternalClass(\\\"test\\\")\\n\\\"\\\"\\\"\\n    class_name = \\\"MyComponent\\\"\\n    created_class = create_class(code, class_name)\\n    instance = created_class()\\n    result = instance.build()\\n    assert result.value == \\\"test\\\"\\n\\n\\ndef test_create_class_module_import():\\n    code = \\\"\\\"\\\"\\nfrom langflow.custom import CustomComponent\\nfrom PIL import ImageDraw\\n\\nclass ExternalClass:\\n    def __init__(self, value):\\n        self.value = value\\n\\nclass MyComponent(CustomComponent):\\n    def build(self):\\n        return ExternalClass(\\\"test\\\")\\n\\\"\\\"\\\"\\n    class_name = \\\"MyComponent\\\"\\n    created_class = create_class(code, class_name)\\n    instance = created_class()\\n    result = instance.build()\\n    assert result.value == \\\"test\\\"\\n\\n\\ndef test_create_class_with_multiple_external_classes():\\n    code = \\\"\\\"\\\"\\nfrom langflow.custom import CustomComponent\\n\\nclass ExternalClass1:\\n    def __init__(self, value):\\n        self.value = value\\n\\nclass ExternalClass2:\\n    def __init__(self, value):\\n        self.value = value\\n\\nclass MyComponent(CustomComponent):\\n    def build(self):\\n        return ExternalClass1(\\\"test1\\\"), ExternalClass2(\\\"test2\\\")\\n\\\"\\\"\\\"\\n    class_name = \\\"MyComponent\\\"\\n    created_class = create_class(code, class_name)\\n    instance = created_class()\\n    result1, result2 = instance.build()\\n    assert result1.value == \\\"test1\\\"\\n    assert result2.value == \\\"test2\\\"\\n\\n\\ndef test_create_class_with_external_variables_and_functions():\\n    code = \\\"\\\"\\\"\\nfrom langflow.custom import CustomComponent\\n\\nexternal_variable = \\\"external_value\\\"\\n\\ndef external_function():\\n    return \\\"external_function_value\\\"\\n\\nclass MyComponent(CustomComponent):\\n    def build(self):\\n        return external_variable, external_function()\\n\\\"\\\"\\\"\\n    class_name = \\\"MyComponent\\\"\\n    created_class = create_class(code, class_name)\\n    instance = created_class()\\n    result_variable, result_function = instance.build()\\n    assert result_variable == \\\"external_value\\\"\\n    assert result_function == \\\"external_function_value\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_version.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1a6a3b240941a9058309708d886cebdb7b93e2f8353dde154c277ae988bc2117\",\"content\":\"from langflow.utils.version import _compute_non_prerelease_version, get_version_info\\n\\n\\ndef test_version():\\n    info = get_version_info()\\n    assert info[\\\"version\\\"] is not None\\n    assert info[\\\"main_version\\\"] is not None\\n    assert info[\\\"package\\\"] is not None\\n\\n\\ndef test_compute_main():\\n    assert _compute_non_prerelease_version(\\\"1.0.10.post0\\\") == \\\"1.0.10\\\"\\n    assert _compute_non_prerelease_version(\\\"1.0.10.a1\\\") == \\\"1.0.10\\\"\\n    assert _compute_non_prerelease_version(\\\"1.0.10.b112\\\") == \\\"1.0.10\\\"\\n    assert _compute_non_prerelease_version(\\\"1.0.10.rc0\\\") == \\\"1.0.10\\\"\\n    assert _compute_non_prerelease_version(\\\"1.0.10.dev9\\\") == \\\"1.0.10\\\"\\n    assert _compute_non_prerelease_version(\\\"1.0.10\\\") == \\\"1.0.10\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_voice_mode.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fcbfe930c0c7fe37ee083daea8fb39d63801e96ac35043c8f84ad601e6a7b513\",\"content\":\"import numpy as np\\nimport pytest\\n\\ntry:\\n    import webrtcvad\\nexcept ImportError:\\n    pytestmark = pytest.mark.skip(reason=\\\"webrtcvad is not installed. Skipping voice mode tests.\\\")\\n\\nfrom langflow.utils.voice_utils import (\\n    BYTES_PER_16K_FRAME,\\n    BYTES_PER_24K_FRAME,\\n    SAMPLE_RATE_24K,\\n    VAD_SAMPLE_RATE_16K,\\n    resample_24k_to_16k,\\n)\\n\\n\\ndef test_resample_24k_to_16k_valid_frame():\\n    \\\"\\\"\\\"Test that valid 960-byte frames (20ms @ 24kHz) resample to 640 bytes (20ms @ 16kHz).\\\"\\\"\\\"\\n    # Generate a fake 20ms @ 24kHz frame (960 bytes)\\n    duration_samples_24k = int(0.02 * SAMPLE_RATE_24K)  # 480 samples\\n    # Use the newer numpy random Generator\\n    rng = np.random.default_rng()\\n    fake_frame_24k = (rng.random(duration_samples_24k) * 32767).astype(np.int16)\\n    frame_24k_bytes = fake_frame_24k.tobytes()\\n\\n    assert len(frame_24k_bytes) == BYTES_PER_24K_FRAME  # 960\\n\\n    # Resample\\n    frame_16k_bytes = resample_24k_to_16k(frame_24k_bytes)\\n\\n    # Check length after resampling\\n    assert len(frame_16k_bytes) == BYTES_PER_16K_FRAME  # 640\\n\\n\\ndef test_resample_24k_to_16k_invalid_frame():\\n    \\\"\\\"\\\"Test that passing an invalid size frame raises a ValueError.\\\"\\\"\\\"\\n    invalid_frame = b\\\"\\\\x00\\\\x01\\\" * 100  # only 200 bytes, not 960\\n    with pytest.raises(ValueError, match=\\\"Expected exactly\\\"):\\n        _ = resample_24k_to_16k(invalid_frame)\\n\\n\\ndef test_webrtcvad_silence_detection():\\n    \\\"\\\"\\\"Make sure that passing all-zero frames leads to is_speech == False.\\\"\\\"\\\"\\n    vad = webrtcvad.Vad(mode=0)\\n\\n    # Generate 1 second of silence @16k, chunk it in 20ms frames\\n    num_samples = VAD_SAMPLE_RATE_16K  # 1 second\\n    silent_audio = np.zeros(num_samples, dtype=np.int16).tobytes()\\n\\n    frame_size = BYTES_PER_16K_FRAME  # 640\\n    num_frames = len(silent_audio) // frame_size\\n\\n    speech_frames = 0\\n    for i in range(num_frames):\\n        frame_16k = silent_audio[i * frame_size : (i + 1) * frame_size]\\n\\n        is_speech = vad.is_speech(frame_16k, VAD_SAMPLE_RATE_16K)\\n        if is_speech:\\n            speech_frames += 1\\n\\n    # Expect zero frames labeled as speech\\n    assert speech_frames == 0\\n\\n\\ndef test_webrtcvad_with_real_data():\\n    \\\"\\\"\\\"End-to-end test.\\n\\n    - Generate synthetic 24kHz audio\\n    - Break into 20ms frames\\n    - Resample to 16k\\n    - Check how many frames VAD detects as speech.\\n    This test is approximate, since random audio won't always be \\\"speech.\\\"\\n    \\\"\\\"\\\"\\n    # Instead of reading from a file, generate synthetic audio\\n    # Create 1 second of random audio data at 24kHz\\n    num_samples = SAMPLE_RATE_24K  # 1 second\\n    rng = np.random.default_rng(seed=42)  # Use a fixed seed for reproducibility\\n\\n    # Generate random audio (this won't be detected as speech, but that's fine for testing)\\n    raw_data_24k = (rng.random(num_samples) * 32767).astype(np.int16).tobytes()\\n\\n    # We'll chunk into 20ms frames (960 bytes each)\\n    frame_size_24k = BYTES_PER_24K_FRAME  # 960\\n    total_frames = len(raw_data_24k) // frame_size_24k\\n\\n    vad = webrtcvad.Vad(mode=2)\\n\\n    resampled_all = bytearray()\\n    speech_count = 0\\n    for i in range(total_frames):\\n        frame_24k = raw_data_24k[i * frame_size_24k : (i + 1) * frame_size_24k]\\n        frame_16k = resample_24k_to_16k(frame_24k)\\n\\n        resampled_all.extend(frame_16k)  # Append to our buffer\\n\\n        is_speech = vad.is_speech(frame_16k, VAD_SAMPLE_RATE_16K)\\n        if is_speech:\\n            speech_count += 1\\n\\n    # For random noise, we expect very few frames to be detected as speech\\n    # We're not making a strict assertion, just verifying the process works\\n    assert len(resampled_all) == (total_frames * BYTES_PER_16K_FRAME)\\n\\n    # Log the speech detection rate\\n    speech_count / total_frames if total_frames > 0 else 0\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_voice_mode_client_scoping.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"67b1e002d70bebf61ab7fc76a5fdb35385c7ae53e8b4e0fb3c9c6614bb2505fd\",\"content\":\"\\\"\\\"\\\"Regression tests for voice-mode dependency loading and cross-tenant client confusion.\\n\\nThe ElevenLabs client must be built per requesting user (no process-global\\nsingleton), and the voice/TTS config caches must be keyed by the authenticated\\nuser, not just the client-supplied session_id.\\n\\\"\\\"\\\"\\n\\nimport builtins\\nimport importlib\\nimport sys\\nimport types\\nfrom types import SimpleNamespace\\nfrom unittest.mock import AsyncMock\\n\\nimport langflow.api.v1.voice_mode as vm\\nimport pytest\\nfrom fastapi import HTTPException\\n\\n\\ndef test_voice_mode_module_import_does_not_require_openai(monkeypatch):\\n    \\\"\\\"\\\"The server must boot when the optional OpenAI voice SDK is absent.\\\"\\\"\\\"\\n    real_import = builtins.__import__\\n\\n    def import_without_openai(name, *args, **kwargs):\\n        if name == \\\"openai\\\" or name.startswith(\\\"openai.\\\"):\\n            error_message = \\\"No module named 'openai'\\\"\\n            raise ModuleNotFoundError(error_message, name=\\\"openai\\\")\\n        return real_import(name, *args, **kwargs)\\n\\n    monkeypatch.setattr(builtins, \\\"__import__\\\", import_without_openai)\\n    vm.__dict__.pop(\\\"OpenAI\\\", None)\\n\\n    importlib.reload(vm)\\n\\n\\n@pytest.mark.asyncio\\nasync def test_get_or_create_elevenlabs_client_is_per_user(monkeypatch):\\n    \\\"\\\"\\\"Each user gets an ElevenLabs client built from their OWN key (no shared singleton).\\\"\\\"\\\"\\n    keys = {\\\"user-a\\\": \\\"key-a\\\", \\\"user-b\\\": \\\"key-b\\\"}\\n\\n    class FakeVariableService:\\n        async def get_variable(self, *, user_id, name, field, session):  # noqa: ARG002\\n            return keys[user_id]\\n\\n    monkeypatch.setattr(vm, \\\"get_variable_service\\\", lambda: FakeVariableService())\\n\\n    captured: list[str] = []\\n\\n    def fake_elevenlabs(*, api_key):\\n        captured.append(api_key)\\n        return f\\\"client::{api_key}\\\"\\n\\n    monkeypatch.setattr(vm, \\\"ElevenLabs\\\", fake_elevenlabs)\\n\\n    client_a = await vm.get_or_create_elevenlabs_client(\\\"user-a\\\", \\\"sess\\\")\\n    client_b = await vm.get_or_create_elevenlabs_client(\\\"user-b\\\", \\\"sess\\\")\\n\\n    # Built from each user's own key \u2014 user-b is NOT served user-a's cached client.\\n    assert client_a == \\\"client::key-a\\\"\\n    assert client_b == \\\"client::key-b\\\"\\n    assert captured == [\\\"key-a\\\", \\\"key-b\\\"]\\n\\n\\n@pytest.mark.asyncio\\nasync def test_get_or_create_elevenlabs_client_requires_user_and_session():\\n    \\\"\\\"\\\"No user/session -> no client (avoids falling back to some other tenant's key).\\\"\\\"\\\"\\n    assert await vm.get_or_create_elevenlabs_client(None, None) is None\\n    assert await vm.get_or_create_elevenlabs_client(\\\"user\\\", None) is None\\n\\n\\n@pytest.mark.asyncio\\nasync def test_voice_catalog_denial_precedes_credential_and_provider_lookup(monkeypatch):\\n    \\\"\\\"\\\"A revoked voice grant reaches neither the variable service nor ElevenLabs.\\\"\\\"\\\"\\n    denied_guard = AsyncMock(side_effect=HTTPException(status_code=403, detail=\\\"denied\\\"))\\n    client_lookup = AsyncMock()\\n    monkeypatch.setattr(vm, \\\"ensure_voice_permission\\\", denied_guard)\\n    monkeypatch.setattr(vm, \\\"get_or_create_elevenlabs_client\\\", client_lookup)\\n\\n    with pytest.raises(HTTPException) as exc_info:\\n        await vm.get_elevenlabs_voice_ids(\\n            current_user=SimpleNamespace(id=\\\"revoked-user\\\"),\\n            session=object(),\\n        )\\n\\n    assert exc_info.value.status_code == 403\\n    denied_guard.assert_awaited_once()\\n    client_lookup.assert_not_awaited()\\n\\n\\ndef test_get_voice_config_scoped_by_user():\\n    \\\"\\\"\\\"Same client-supplied session_id but different users must not share a VoiceConfig.\\\"\\\"\\\"\\n    vm.voice_config_cache.clear()\\n\\n    a = vm.get_voice_config(\\\"shared-session\\\", \\\"user-a\\\")\\n    b = vm.get_voice_config(\\\"shared-session\\\", \\\"user-b\\\")\\n    a_again = vm.get_voice_config(\\\"shared-session\\\", \\\"user-a\\\")\\n\\n    assert a is not b\\n    assert a is a_again  # same (user, session) is still cached\\n\\n\\ndef test_get_tts_config_scoped_by_user(monkeypatch):\\n    \\\"\\\"\\\"Same session_id but different users must not share a TTSConfig / OpenAI client.\\\"\\\"\\\"\\n    vm.tts_config_cache.clear()\\n    fake_openai = types.ModuleType(\\\"openai\\\")\\n    fake_openai.OpenAI = lambda *, api_key: {\\\"api_key\\\": api_key}\\n    monkeypatch.setitem(sys.modules, \\\"openai\\\", fake_openai)\\n\\n    a = vm.get_tts_config(\\\"shared-session\\\", \\\"openai-key-a\\\", \\\"user-a\\\")\\n    b = vm.get_tts_config(\\\"shared-session\\\", \\\"openai-key-b\\\", \\\"user-b\\\")\\n\\n    assert a is not b\\n    # The OpenAI client (built from each user's key) is not shared across users.\\n    assert a.get_openai_client() is not b.get_openai_client()\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/backend/tests/unit/test_webhook.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"9801ec6062bf6ac6ad1422f61fa7473af0d89a9a3758d0802ca0ad1b61214a74\",\"content\":\"import asyncio\\nfrom unittest.mock import patch\\n\\nimport aiofiles\\nimport anyio\\nimport pytest\\nfrom langflow.services.event_manager import WebhookEventManager\\n\\n\\n@pytest.fixture(autouse=True)\\ndef _check_openai_api_key_in_environment_variables():\\n    pass\\n\\n\\n# =============================================================================\\n# SUCCESS TESTS\\n# =============================================================================\\n\\n\\nasync def test_webhook_endpoint_returns_202_accepted(client, added_webhook_test, created_api_key):\\n    \\\"\\\"\\\"Test that webhook endpoint returns 202 Accepted on valid request.\\\"\\\"\\\"\\n    endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n    endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n\\n    payload = {\\\"test_key\\\": \\\"test_value\\\"}\\n    response = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json=payload)\\n\\n    assert response.status_code == 202\\n    assert response.json()[\\\"message\\\"] == \\\"Task started in the background\\\"\\n    assert response.json()[\\\"status\\\"] == \\\"in progress\\\"\\n\\n\\nasync def test_webhook_endpoint_by_flow_id(client, added_webhook_test, created_api_key):\\n    \\\"\\\"\\\"Test that webhook can be accessed by flow ID.\\\"\\\"\\\"\\n    flow_id = added_webhook_test[\\\"id\\\"]\\n    endpoint = f\\\"api/v1/webhook/{flow_id}\\\"\\n\\n    payload = {\\\"data\\\": \\\"test\\\"}\\n    response = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json=payload)\\n\\n    assert response.status_code == 202\\n\\n\\nasync def test_webhook_with_json_payload(client, added_webhook_test, created_api_key):\\n    \\\"\\\"\\\"Test webhook with various JSON payload types.\\\"\\\"\\\"\\n    endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n    endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n\\n    # Test with nested JSON\\n    payload = {\\\"nested\\\": {\\\"key\\\": \\\"value\\\", \\\"array\\\": [1, 2, 3]}}\\n    response = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json=payload)\\n    assert response.status_code == 202\\n\\n    # Test with array payload\\n    payload = [{\\\"item\\\": 1}, {\\\"item\\\": 2}]\\n    response = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json=payload)\\n    assert response.status_code == 202\\n\\n\\nasync def test_webhook_endpoint_requires_api_key_when_auto_login_false(client, added_webhook_test):\\n    \\\"\\\"\\\"Test that webhook endpoint requires API key when WEBHOOK_AUTH_ENABLE=true.\\\"\\\"\\\"\\n    # Modify the auth_settings.WEBHOOK_AUTH_ENABLE on the real settings service\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n    original_webhook_auth_enable = settings_service.auth_settings.WEBHOOK_AUTH_ENABLE\\n\\n    try:\\n        settings_service.auth_settings.WEBHOOK_AUTH_ENABLE = True\\n\\n        endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n        endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n\\n        payload = {\\\"path\\\": \\\"/tmp/test_file.txt\\\"}  # noqa: S108\\n\\n        # Should fail without API key when webhook auth is enabled\\n        response = await client.post(endpoint, json=payload)\\n        assert response.status_code == 403\\n        assert \\\"API key required when webhook authentication is enabled\\\" in response.json()[\\\"detail\\\"]\\n    finally:\\n        settings_service.auth_settings.WEBHOOK_AUTH_ENABLE = original_webhook_auth_enable\\n\\n\\nasync def test_webhook_endpoint_with_valid_api_key(client, added_webhook_test, created_api_key):\\n    \\\"\\\"\\\"Test that webhook works when valid API key is provided.\\\"\\\"\\\"\\n    endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n    endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n\\n    # Create a temporary file\\n    async with aiofiles.tempfile.TemporaryDirectory() as tmp:\\n        file_path = anyio.Path(tmp) / \\\"test_file.txt\\\"\\n        payload = {\\\"path\\\": str(file_path)}\\n\\n        # Should work with valid API key\\n        response = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json=payload)\\n        assert response.status_code == 202\\n\\n        # Wait for background task to complete (webhook returns 202 immediately)\\n        await asyncio.sleep(2)\\n        assert await file_path.exists(), f\\\"File {file_path} does not exist\\\"\\n\\n    file_does_not_exist = not await file_path.exists()\\n    assert file_does_not_exist, f\\\"File {file_path} still exists\\\"\\n\\n\\nasync def test_webhook_endpoint_unauthorized_user_flow(client, added_webhook_test):\\n    \\\"\\\"\\\"Test that webhook fails when user doesn't own the flow.\\\"\\\"\\\"\\n    # Modify the auth_settings.WEBHOOK_AUTH_ENABLE on the real settings service\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n    original_webhook_auth_enable = settings_service.auth_settings.WEBHOOK_AUTH_ENABLE\\n\\n    try:\\n        settings_service.auth_settings.WEBHOOK_AUTH_ENABLE = True\\n\\n        # This test would need a different user's API key to test authorization\\n        # For now, we'll use an invalid API key to simulate this\\n        endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n        endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n\\n        payload = {\\\"path\\\": \\\"/tmp/test_file.txt\\\"}  # noqa: S108\\n\\n        # Should fail with invalid API key\\n        response = await client.post(endpoint, headers={\\\"x-api-key\\\": \\\"invalid_key\\\"}, json=payload)\\n        assert response.status_code == 403\\n        # Error message may be \\\"Invalid API key\\\" or \\\"API key authentication failed\\\" depending on implementation\\n        assert \\\"api key\\\" in response.json()[\\\"detail\\\"].lower()\\n    finally:\\n        settings_service.auth_settings.WEBHOOK_AUTH_ENABLE = original_webhook_auth_enable\\n\\n\\nasync def test_webhook_flow_on_run_endpoint(client, added_webhook_test, created_api_key):\\n    endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n    endpoint = f\\\"api/v1/run/{endpoint_name}?stream=false\\\"\\n    # Just test that \\\"Random Payload\\\" returns 202\\n    # returns 202\\n    payload = {\\n        \\\"output_type\\\": \\\"any\\\",\\n    }\\n    response = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json=payload)\\n    assert response.status_code == 200, response.json()\\n\\n\\nasync def test_webhook_with_auto_login_enabled(client, added_webhook_test):\\n    \\\"\\\"\\\"Test webhook behavior when WEBHOOK_AUTH_ENABLE=false - should work without API key.\\\"\\\"\\\"\\n    # Modify the auth_settings.WEBHOOK_AUTH_ENABLE on the real settings service\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n    original_webhook_auth_enable = settings_service.auth_settings.WEBHOOK_AUTH_ENABLE\\n\\n    try:\\n        settings_service.auth_settings.WEBHOOK_AUTH_ENABLE = False\\n\\n        endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n        endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n\\n        payload = {\\\"path\\\": \\\"/tmp/test_auto_login.txt\\\"}  # noqa: S108\\n\\n        # Should work without API key when webhook auth is disabled\\n        response = await client.post(endpoint, json=payload)\\n        assert response.status_code == 202\\n    finally:\\n        settings_service.auth_settings.WEBHOOK_AUTH_ENABLE = original_webhook_auth_enable\\n\\n\\ndef test_webhook_auth_enable_defaults_to_true():\\n    \\\"\\\"\\\"Regression guard: WEBHOOK_AUTH_ENABLE must default to True (secure by default).\\n\\n    Defaulting to False previously allowed anyone who knew a flow UUID to execute\\n    that flow unauthenticated as the flow owner. We read the class-level default\\n    directly so a stray LANGFLOW_WEBHOOK_AUTH_ENABLE env var can't mask a regression.\\n    \\\"\\\"\\\"\\n    from lfx.services.settings.auth import AuthSettings\\n\\n    assert AuthSettings.model_fields[\\\"WEBHOOK_AUTH_ENABLE\\\"].default is True\\n\\n\\nasync def test_webhook_rejects_unauthenticated_request_by_default(client, added_webhook_test):\\n    \\\"\\\"\\\"Under the default config, an unauthenticated POST to /webhook must return 403.\\\"\\\"\\\"\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n    # Confirm the runtime default matches the secure-by-default value before exercising it.\\n    assert settings_service.auth_settings.WEBHOOK_AUTH_ENABLE is True\\n\\n    endpoint = f\\\"api/v1/webhook/{added_webhook_test['endpoint_name']}\\\"\\n    response = await client.post(endpoint, json={\\\"test\\\": \\\"unauthenticated_trigger\\\"})\\n\\n    assert response.status_code == 403\\n    assert \\\"API key required\\\" in response.json()[\\\"detail\\\"]\\n\\n\\nasync def test_webhook_with_random_payload_requires_auth(client, added_webhook_test, created_api_key):\\n    \\\"\\\"\\\"Test that webhook with random payload still requires authentication.\\\"\\\"\\\"\\n    # Modify the auth_settings.WEBHOOK_AUTH_ENABLE on the real settings service\\n    from langflow.services.deps import get_settings_service\\n\\n    settings_service = get_settings_service()\\n\\n    # Ensure we're modifying the same settings service used by the application\\n    original_webhook_auth_enable = settings_service.auth_settings.WEBHOOK_AUTH_ENABLE\\n\\n    try:\\n        settings_service.auth_settings.WEBHOOK_AUTH_ENABLE = True\\n\\n        endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n        endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n\\n        # Should fail without API key\\n        response = await client.post(endpoint, json=\\\"Random Payload\\\")\\n        assert response.status_code == 403\\n\\n        # Should work with API key (even with random payload)\\n        response = await client.post(\\n            endpoint,\\n            headers={\\\"x-api-key\\\": created_api_key.api_key},\\n            json=\\\"Random Payload\\\",\\n        )\\n        assert response.status_code == 202, f\\\"Expected 202, got {response.status_code}: {response.json()}\\\"\\n    finally:\\n        settings_service.auth_settings.WEBHOOK_AUTH_ENABLE = original_webhook_auth_enable\\n\\n\\n# =============================================================================\\n# ERROR TESTS\\n# =============================================================================\\n\\n\\nasync def test_webhook_not_found_invalid_endpoint(client, created_api_key):\\n    \\\"\\\"\\\"Test that webhook returns 404 for non-existent endpoint.\\\"\\\"\\\"\\n    endpoint = \\\"api/v1/webhook/non-existent-endpoint-12345\\\"\\n    payload = {\\\"test\\\": \\\"data\\\"}\\n\\n    response = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json=payload)\\n    assert response.status_code == 404\\n\\n\\n# async def test_webhook_not_found_invalid_flow_id(client, created_api_key):\\n#     \\\"\\\"\\\"Test that webhook returns 404 for invalid flow ID.\\\"\\\"\\\"\\n#     endpoint = \\\"api/v1/webhook/00000000-0000-0000-0000-000000000000\\\"\\n#     payload = {\\\"test\\\": \\\"data\\\"}\\n\\n#     response = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json=payload)\\n#     assert response.status_code == 404\\n\\n\\nasync def test_webhook_invalid_api_key(client, added_webhook_test):\\n    \\\"\\\"\\\"Test that webhook returns 403 for invalid API key when auth is enabled.\\\"\\\"\\\"\\n    from unittest.mock import AsyncMock, MagicMock\\n\\n    from fastapi import HTTPException\\n    from langflow.services.auth.service import AuthService\\n\\n    # Create a mock settings service with WEBHOOK_AUTH_ENABLE=True\\n    mock_auth_settings = MagicMock()\\n    mock_auth_settings.WEBHOOK_AUTH_ENABLE = True\\n\\n    mock_settings_service = MagicMock()\\n    mock_settings_service.auth_settings = mock_auth_settings\\n\\n    # Create a mock auth service\\n    mock_auth_service = MagicMock(spec=AuthService)\\n    mock_auth_service.settings_service = mock_settings_service\\n    mock_auth_service.get_webhook_user = AsyncMock(side_effect=HTTPException(status_code=403, detail=\\\"Invalid API key\\\"))\\n\\n    with patch(\\\"langflow.api.v1.endpoints.get_auth_service\\\", return_value=mock_auth_service):\\n        endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n        endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n        payload = {\\\"test\\\": \\\"data\\\"}\\n\\n        response = await client.post(endpoint, headers={\\\"x-api-key\\\": \\\"invalid-api-key\\\"}, json=payload)\\n        assert response.status_code == 403\\n        assert \\\"api key\\\" in response.json()[\\\"detail\\\"].lower()\\n\\n\\nasync def test_webhook_missing_api_key_when_required(client, added_webhook_test):\\n    \\\"\\\"\\\"Test that webhook returns 403 when API key is missing and auth is enabled.\\\"\\\"\\\"\\n    from unittest.mock import AsyncMock, MagicMock\\n\\n    from fastapi import HTTPException\\n    from langflow.services.auth.service import AuthService\\n\\n    # Create a mock settings service with WEBHOOK_AUTH_ENABLE=True\\n    mock_auth_settings = MagicMock()\\n    mock_auth_settings.WEBHOOK_AUTH_ENABLE = True\\n\\n    mock_settings_service = MagicMock()\\n    mock_settings_service.auth_settings = mock_auth_settings\\n\\n    # Create a mock auth service\\n    mock_auth_service = MagicMock(spec=AuthService)\\n    mock_auth_service.settings_service = mock_settings_service\\n    mock_auth_service.get_webhook_user = AsyncMock(\\n        side_effect=HTTPException(status_code=403, detail=\\\"API key required when webhook authentication is enabled\\\")\\n    )\\n\\n    with patch(\\\"langflow.api.v1.endpoints.get_auth_service\\\", return_value=mock_auth_service):\\n        endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n        endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n        payload = {\\\"test\\\": \\\"data\\\"}\\n\\n        response = await client.post(endpoint, json=payload)\\n        assert response.status_code == 403\\n        assert \\\"API key required\\\" in response.json()[\\\"detail\\\"]\\n\\n\\n# =============================================================================\\n# EDGE CASE TESTS\\n# =============================================================================\\n\\n\\nasync def test_webhook_with_empty_payload(client, added_webhook_test, created_api_key):\\n    \\\"\\\"\\\"Test webhook with empty JSON payload.\\\"\\\"\\\"\\n    endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n    endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n\\n    response = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json={})\\n    assert response.status_code == 202\\n\\n\\nasync def test_webhook_with_string_payload(client, added_webhook_test, created_api_key):\\n    \\\"\\\"\\\"Test webhook with string payload instead of JSON object.\\\"\\\"\\\"\\n    endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n    endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n\\n    response = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json=\\\"plain string\\\")\\n    assert response.status_code == 202\\n\\n\\nasync def test_webhook_with_null_payload_returns_bad_request(client, added_webhook_test, created_api_key):\\n    \\\"\\\"\\\"Test webhook with null payload returns 400 Bad Request.\\\"\\\"\\\"\\n    endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n    endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n\\n    response = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json=None)\\n    # Null payload is not valid JSON body, returns 400\\n    assert response.status_code == 400\\n\\n\\nasync def test_webhook_with_large_payload(client, added_webhook_test, created_api_key):\\n    \\\"\\\"\\\"Test webhook with large payload.\\\"\\\"\\\"\\n    endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n    endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n\\n    # Create a large payload\\n    large_payload = {\\\"data\\\": \\\"x\\\" * 10000, \\\"items\\\": list(range(1000))}\\n    response = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json=large_payload)\\n    assert response.status_code == 202\\n\\n\\nasync def test_webhook_with_special_characters_in_payload(client, added_webhook_test, created_api_key):\\n    \\\"\\\"\\\"Test webhook with special characters in payload.\\\"\\\"\\\"\\n    endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n    endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n\\n    payload = {\\n        \\\"unicode\\\": \\\"\u3053\u3093\u306b\u3061\u306f\u4e16\u754c \ud83c\udf0d\\\",\\n        \\\"special\\\": \\\"<script>alert('xss')</script>\\\",\\n        \\\"quotes\\\": 'He said \\\"hello\\\"',\\n        \\\"newlines\\\": \\\"line1\\\\nline2\\\\rline3\\\",\\n    }\\n    response = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json=payload)\\n    assert response.status_code == 202\\n\\n\\n# =============================================================================\\n# VERTEX BUILD TESTS\\n# =============================================================================\\n\\n\\nasync def test_webhook_creates_vertex_builds(client, added_webhook_test, created_api_key):\\n    \\\"\\\"\\\"Test that webhook execution creates vertex builds in the database.\\\"\\\"\\\"\\n    flow_id = added_webhook_test[\\\"id\\\"]\\n    endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n    endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n\\n    # Execute the webhook\\n    payload = {\\\"test\\\": \\\"vertex_build_test\\\"}\\n    response = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json=payload)\\n    assert response.status_code == 202\\n\\n    # Wait for background task to complete\\n    await asyncio.sleep(2)\\n\\n    # Check vertex builds were created\\n    builds_endpoint = f\\\"api/v1/monitor/builds?flow_id={flow_id}\\\"\\n    builds_response = await client.get(builds_endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key})\\n\\n    assert builds_response.status_code == 200\\n    builds_data = builds_response.json()\\n    assert \\\"vertex_builds\\\" in builds_data\\n    # Should have at least one vertex build (Webhook component)\\n    assert len(builds_data[\\\"vertex_builds\\\"]) > 0\\n\\n\\nasync def test_webhook_vertex_builds_contain_expected_data(client, added_webhook_test, created_api_key):\\n    \\\"\\\"\\\"Test that vertex builds contain expected structure and data.\\\"\\\"\\\"\\n    flow_id = added_webhook_test[\\\"id\\\"]\\n    endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n    endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n\\n    # Execute the webhook\\n    payload = {\\\"verify\\\": \\\"structure\\\"}\\n    response = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json=payload)\\n    assert response.status_code == 202\\n\\n    # Wait for background task to complete\\n    await asyncio.sleep(2)\\n\\n    # Check vertex builds\\n    builds_endpoint = f\\\"api/v1/monitor/builds?flow_id={flow_id}\\\"\\n    builds_response = await client.get(builds_endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key})\\n\\n    assert builds_response.status_code == 200\\n    builds_data = builds_response.json()\\n\\n    # Verify structure of vertex builds\\n    for builds in builds_data[\\\"vertex_builds\\\"].values():\\n        assert isinstance(builds, list)\\n        for build in builds:\\n            assert \\\"id\\\" in build\\n            assert \\\"valid\\\" in build\\n            assert \\\"timestamp\\\" in build\\n            assert \\\"flow_id\\\" in build\\n            assert str(build[\\\"flow_id\\\"]) == flow_id\\n\\n\\nasync def test_webhook_multiple_executions_create_multiple_builds(client, added_webhook_test, created_api_key):\\n    \\\"\\\"\\\"Test that multiple webhook executions create multiple vertex builds.\\\"\\\"\\\"\\n    flow_id = added_webhook_test[\\\"id\\\"]\\n    endpoint_name = added_webhook_test[\\\"endpoint_name\\\"]\\n    endpoint = f\\\"api/v1/webhook/{endpoint_name}\\\"\\n\\n    # Execute webhook multiple times\\n    for i in range(3):\\n        payload = {\\\"execution\\\": i}\\n        response = await client.post(endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key}, json=payload)\\n        assert response.status_code == 202\\n\\n    # Wait for all background tasks to complete\\n    await asyncio.sleep(5)\\n\\n    # Check vertex builds\\n    builds_endpoint = f\\\"api/v1/monitor/builds?flow_id={flow_id}\\\"\\n    builds_response = await client.get(builds_endpoint, headers={\\\"x-api-key\\\": created_api_key.api_key})\\n\\n    assert builds_response.status_code == 200\\n    builds_data = builds_response.json()\\n\\n    # Should have vertex builds\\n    assert len(builds_data[\\\"vertex_builds\\\"]) > 0\\n\\n\\nasync def test_vertex_builds_endpoint_returns_empty_for_new_flow(client, logged_in_headers):\\n    \\\"\\\"\\\"Test that vertex builds endpoint returns empty for a flow with no executions.\\\"\\\"\\\"\\n    from langflow.services.database.models.flow.model import FlowCreate\\n    from lfx.components.input_output import ChatInput\\n    from lfx.graph import Graph\\n\\n    # Create a new flow without executing it\\n    chat_input = ChatInput()\\n    graph = Graph(start=chat_input, end=chat_input)\\n    graph_dict = graph.dump(name=\\\"Empty Test Flow\\\")\\n    flow = FlowCreate(**graph_dict)\\n\\n    response = await client.post(\\\"api/v1/flows/\\\", json=flow.model_dump(), headers=logged_in_headers)\\n    assert response.status_code == 201\\n    flow_id = response.json()[\\\"id\\\"]\\n\\n    try:\\n        # Check vertex builds - should be empty\\n        builds_endpoint = f\\\"api/v1/monitor/builds?flow_id={flow_id}\\\"\\n        builds_response = await client.get(builds_endpoint, headers=logged_in_headers)\\n\\n        assert builds_response.status_code == 200\\n        builds_data = builds_response.json()\\n        assert builds_data[\\\"vertex_builds\\\"] == {}\\n    finally:\\n        # Cleanup\\n        await client.delete(f\\\"api/v1/flows/{flow_id}\\\", headers=logged_in_headers)\\n\\n\\n# =============================================================================\\n# WEBHOOK EVENT MANAGER TESTS\\n# =============================================================================\\n\\n\\nasync def test_webhook_event_manager_subscribe_unsubscribe():\\n    \\\"\\\"\\\"Test subscribing and unsubscribing from webhook events.\\\"\\\"\\\"\\n    manager = WebhookEventManager()\\n    flow_id = \\\"test-flow-123\\\"\\n\\n    # Initially no listeners\\n    assert not manager.has_listeners(flow_id)\\n\\n    # Subscribe\\n    queue = await manager.subscribe(flow_id)\\n    assert manager.has_listeners(flow_id)\\n\\n    # Unsubscribe\\n    await manager.unsubscribe(flow_id, queue)\\n    assert not manager.has_listeners(flow_id)\\n\\n\\nasync def test_webhook_event_manager_emit():\\n    \\\"\\\"\\\"Test emitting events to subscribers.\\\"\\\"\\\"\\n    manager = WebhookEventManager()\\n    flow_id = \\\"test-flow-456\\\"\\n\\n    # Subscribe\\n    queue = await manager.subscribe(flow_id)\\n\\n    # Emit event\\n    await manager.emit(flow_id, \\\"test_event\\\", {\\\"key\\\": \\\"value\\\"})\\n\\n    # Check event was received\\n    event = await asyncio.wait_for(queue.get(), timeout=1.0)\\n    assert event[\\\"event\\\"] == \\\"test_event\\\"\\n    assert event[\\\"data\\\"] == {\\\"key\\\": \\\"value\\\"}\\n    assert \\\"timestamp\\\" in event\\n\\n    # Cleanup\\n    await manager.unsubscribe(flow_id, queue)\\n\\n\\nasync def test_webhook_event_manager_emit_no_listeners():\\n    \\\"\\\"\\\"Test that emit with no listeners doesn't raise errors.\\\"\\\"\\\"\\n    manager = WebhookEventManager()\\n    flow_id = \\\"test-flow-789\\\"\\n\\n    # Should not raise any errors\\n    await manager.emit(flow_id, \\\"test_event\\\", {\\\"key\\\": \\\"value\\\"})\\n\\n\\nasync def test_webhook_event_manager_duration_tracking():\\n    \\\"\\\"\\\"Test build duration tracking.\\\"\\\"\\\"\\n    manager = WebhookEventManager()\\n    flow_id = \\\"test-flow-duration\\\"\\n    vertex_id = \\\"vertex-1\\\"\\n\\n    # Record start time\\n    manager.record_build_start(flow_id, vertex_id)\\n\\n    # Wait a bit\\n    await asyncio.sleep(0.1)\\n\\n    # Get duration\\n    duration = manager.get_build_duration(flow_id, vertex_id)\\n    assert duration is not None\\n    assert \\\"ms\\\" in duration  # Should be in milliseconds format\\n\\n    # Duration should be cleared after getting it\\n    duration_again = manager.get_build_duration(flow_id, vertex_id)\\n    assert duration_again is None\\n\\n\\nasync def test_webhook_event_manager_format_duration():\\n    \\\"\\\"\\\"Test duration formatting.\\\"\\\"\\\"\\n    # Test milliseconds\\n    assert WebhookEventManager._format_duration(0.5) == \\\"500 ms\\\"\\n    assert WebhookEventManager._format_duration(0.999) == \\\"999 ms\\\"\\n\\n    # Test seconds\\n    assert WebhookEventManager._format_duration(1.0) == \\\"1.0 s\\\"\\n    assert WebhookEventManager._format_duration(30.5) == \\\"30.5 s\\\"\\n\\n    # Test minutes\\n    assert WebhookEventManager._format_duration(60.0) == \\\"1m 0.0s\\\"\\n    assert WebhookEventManager._format_duration(90.5) == \\\"1m 30.5s\\\"\\n\\n\\nasync def test_webhook_event_manager_multiple_subscribers():\\n    \\\"\\\"\\\"Test multiple subscribers receive the same events.\\\"\\\"\\\"\\n    manager = WebhookEventManager()\\n    flow_id = \\\"test-flow-multi\\\"\\n\\n    # Subscribe multiple times\\n    queue1 = await manager.subscribe(flow_id)\\n    queue2 = await manager.subscribe(flow_id)\\n\\n    # Emit event\\n    await manager.emit(flow_id, \\\"broadcast\\\", {\\\"msg\\\": \\\"hello\\\"})\\n\\n    # Both should receive the event\\n    event1 = await asyncio.wait_for(queue1.get(), timeout=1.0)\\n    event2 = await asyncio.wait_for(queue2.get(), timeout=1.0)\\n\\n    assert event1[\\\"data\\\"] == {\\\"msg\\\": \\\"hello\\\"}\\n    assert event2[\\\"data\\\"] == {\\\"msg\\\": \\\"hello\\\"}\\n\\n    # Cleanup\\n    await manager.unsubscribe(flow_id, queue1)\\n ";
